def safe_imread(path: str) -> np.ndarray:
    data = np.fromfile(path, dtype=np.uint8)
    return cv2.imdecode(data, cv2.IMREAD_COLOR)

def get_stitcher():
    return cv2.Stitcher_create(cv2.Stitcher_SCANS) if hasattr(cv2, "Stitcher_create") else cv2.createStitcher(False)

def merge_lines(lines_list, gap=20):
    if not lines_list: return []
    lines_list.sort()
    groups, current_group = [], [lines_list[0]]
    for i in range(1, len(lines_list)):
        if lines_list[i] - current_group[0] <= gap:
            current_group.append(lines_list[i])
        else:
            groups.append(int(np.mean(current_group)))
            current_group = [lines_list[i]]
    if current_group: groups.append(int(np.mean(current_group)))
    return groups

def get_robust_gap(lines_list, min_gap=40, max_gap=150):
    if len(lines_list) < 2: return 0
    gaps = np.diff(lines_list)
    valid_gaps = gaps[(gaps > min_gap) & (gaps < max_gap)]
    return int(np.median(valid_gaps)) if len(valid_gaps) > 0 else 0

def refine_grid_lines(lines, expected_gap, tolerance=0.35):
    if not lines or len(lines) < 2: return lines
    valid_lines = []
    for l in lines:
        if any(abs(abs(l - other) - expected_gap) <= expected_gap * tolerance for other in lines if l != other):
            valid_lines.append(l)
    return sorted(valid_lines) if valid_lines else lines

def auto_deskew(image: np.ndarray) -> np.ndarray:
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    edges = cv2.Canny(gray, 50, 150, apertureSize=3)
    lines = cv2.HoughLinesP(edges, 1, np.pi/180, 80, minLineLength=100, maxLineGap=10)
    if lines is None: return image
    angles = []
    for line in np.asarray(lines).reshape(-1, 4):
        x1, y1, x2, y2 = line
        if x1 == x2: continue
        angle = np.degrees(np.arctan2(y2 - y1, x2 - x1))
        angle = (angle + 45) % 90 - 45
        angles.append(angle)
    if not angles: return image
    median_angle = np.median(angles)
    if abs(median_angle) < 0.2 or abs(median_angle) > 15.0: return image
    h, w = image.shape[:2]
    center = (w // 2, h // 2)
    M = cv2.getRotationMatrix2D(center, median_angle, 1.0)
    return cv2.warpAffine(image, M, (w, h), flags=cv2.INTER_CUBIC, borderMode=cv2.BORDER_REPLICATE)

def is_duplicate(nx, ny, nr, centers, dup_dist):
    for bx, by, br in centers:
        dist = np.sqrt((nx - bx)**2 + (ny - by)**2)
        if dist < dup_dist or dist < max(nr, br): return True
    return False

# =========================
# Scale-bar & Edge Validation
# =========================
CELL_MIN_DIAMETER_BAR_RATIO = 0.040
CELL_MAX_DIAMETER_BAR_RATIO = 0.450

def estimate_scale_bar_px(bgr_img: np.ndarray):
    if bgr_img is None or bgr_img.size == 0: return None
    gray = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2GRAY)
    h, w = gray.shape[:2]
    x0, y0 = int(w * 0.55), int(h * 0.68)
    roi = gray[y0:h-2, x0:w-2]
    if roi.size == 0: return None

    thr = max(180, int(np.percentile(roi, 98)))
    _, bw = cv2.threshold(roi, thr, 255, cv2.THRESH_BINARY)
    bw = cv2.morphologyEx(bw, cv2.MORPH_CLOSE, cv2.getStructuringElement(cv2.MORPH_RECT, (31, 3)), iterations=1)
    bw = cv2.morphologyEx(bw, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (23, 2)), iterations=1)

    cnts, _ = cv2.findContours(bw, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    candidates = []
    for c in cnts:
        x, y, ww, hh = cv2.boundingRect(c)
        if ww < 25 or hh < 2: continue
        aspect = ww / max(hh, 1)
        area = cv2.contourArea(c)
        if aspect >= 7.0 and area >= ww * max(1.0, hh) * 0.35:
            candidates.append((ww, x, y, hh))

    if not candidates: return None
    bar_px = float(max(candidates, key=lambda t: t[0])[0])
    if bar_px < max(20.0, w * 0.025) or bar_px > w * 0.22: return None
    return bar_px

def _size_limits_from_scale(scale_bar_px, scale_ratio):
    if scale_bar_px is not None and scale_bar_px > 0:
        min_r = max(2.0, (scale_bar_px * CELL_MIN_DIAMETER_BAR_RATIO) / 2.0)
        max_r = max(min_r + 1.5, (scale_bar_px * CELL_MAX_DIAMETER_BAR_RATIO) / 2.0)
    else:
        min_r = max(1.4, 1.2 * scale_ratio)
        max_r = max(7.0, 16.0 * scale_ratio)
    return float(min_r), float(max_r)

# 💡 THE FINAL BOUNCER: "나 사실 세포 아님 ㅋㅋ" 필터
def _cell_like_candidate(roi_gray, cx, cy, radius, scale_ratio, scale_bar_px, contour=None, strict_dark_background=False, track_id=1, grid_ignore=None):
    h, w = roi_gray.shape[:2]
    if h < 8 or w < 8: return False

    # 0. 십자포화 구역 척결 (Grid Interference Rejection)
    if grid_ignore is not None:
        if grid_ignore[int(cy), int(cx)] == 0: 
            return False

    r = float(max(radius, 1.0))
    min_r, max_r = _size_limits_from_scale(scale_bar_px, scale_ratio)
    if r < min_r or r > max_r: return False

    if contour is not None:
        area = float(cv2.contourArea(contour))
        if area <= 0: return False
        peri = cv2.arcLength(contour, True)
        if peri > 0 and (4.0 * np.pi * area / (peri * peri)) < 0.25: return False
        _, _, bw, bh = cv2.boundingRect(contour)
        aspect = bw / max(bh, 1)
        if aspect < 0.35 or aspect > 2.80: return False

    pad = int(max(8, r * 3.2))
    x0, x1 = max(0, int(cx - pad)), min(w, int(cx + pad + 1))
    y0, y1 = max(0, int(cy - pad)), min(h, int(cy + pad + 1))
    local = roi_gray[y0:y1, x0:x1]
    if local.size < 25: return False

    yy, xx = np.ogrid[y0:y1, x0:x1]
    dist = np.sqrt((xx - cx) ** 2 + (yy - cy) ** 2)

    cell_mask = dist <= max(2.0, r * 1.10)
    core_mask = dist <= max(1.5, r * 0.55)
    ring_mask = (dist >= max(2.4, r * 1.55)) & (dist <= max(4.2, r * 2.90))

    if np.count_nonzero(cell_mask) < 7 or np.count_nonzero(ring_mask) < 10: return False

    cell_vals = local[cell_mask]
    core_vals = local[core_mask] if np.count_nonzero(core_mask) > 0 else cell_vals
    ring_vals = local[ring_mask]

    bg_med = float(np.median(ring_vals))
    cell_med = float(np.median(cell_vals))
    core_med = float(np.median(core_vals))

    # 💡 출신 성분별 대조비 문지기 (Engine-Specific Discrimination)
    core_contrast = abs(core_med - bg_med)
    cell_contrast = abs(cell_med - bg_med)

    if track_id == 1:
        min_contrast = 3.0 # Threshold 통과 엘리트는 느슨하게
    elif track_id == 2:
        min_contrast = 7.0 # Hough 의심종자 강화
    else:
        min_contrast = 10.0 # DoG 초강력 사형선고

    if core_contrast < min_contrast and cell_contrast < min_contrast:
        return False

    contrast_thr = max(5.0, float(np.std(ring_vals)) * 1.2, float(np.std(local)) * 0.35)
    changed_mask = (np.abs(local.astype(np.float32) - bg_med) > contrast_thr) & cell_mask
    changed_pixels = int(np.count_nonzero(changed_mask))
    expected_area = np.pi * r * r
    changed_frac = changed_pixels / max(float(np.count_nonzero(cell_mask)), 1.0)

    if track_id in [2, 4]:
        if changed_frac < 0.20: return False

    if bg_med < 50:
        if strict_dark_background:
            min_changed_pixels, min_changed_frac, min_active_sectors = max(5, int(expected_area * 0.14)), 0.15, 3
        else:
            min_changed_pixels, min_changed_frac, min_active_sectors = max(4, int(expected_area * 0.10)), 0.10, 3
    else:
        min_changed_pixels, min_changed_frac, min_active_sectors = max(3, int(expected_area * 0.06)), 0.06, 2

    if changed_pixels < min_changed_pixels or changed_frac < min_changed_frac: return False

    changed_u8 = np.zeros_like(local, dtype=np.uint8)
    changed_u8[changed_mask] = 255
    n_lbl, _, stats, _ = cv2.connectedComponentsWithStats(changed_u8, connectivity=8)
    if n_lbl <= 1: return False

    largest_idx = int(np.argmax(stats[1:, cv2.CC_STAT_AREA])) + 1
    largest_area = int(stats[largest_idx, cv2.CC_STAT_AREA])

    min_largest_area = max(3, int(expected_area * (0.06 if strict_dark_background else 0.04)))
    if largest_area < min_largest_area: return False

    angles = np.arctan2(yy - cy, xx - cx)
    active = sum(1 for k in range(8) if np.count_nonzero(changed_mask & (angles >= -np.pi + k*(np.pi/4)) & (angles < -np.pi + (k+1)*(np.pi/4))) >= 1)
    if active < min_active_sectors: return False

    return True

def _blob_recovery_candidates(roi_gray, grid_ignore, scale_ratio, scale_bar_px):
    h, w = roi_gray.shape[:2]
    if h < 8 or w < 8: return []

    min_r, max_r = _size_limits_from_scale(scale_bar_px, scale_ratio)
    min_r = max(1.5, float(min_r))
    max_r = max(min_r + 1.0, float(max_r))
    src = cv2.bitwise_and(roi_gray, grid_ignore)

    blur_small = cv2.GaussianBlur(src, (0, 0), max(0.7, min_r * 0.45))
    blur_large = cv2.GaussianBlur(src, (0, 0), max(1.8, min(max_r * 1.25, 10.0)))
    dog = cv2.subtract(blur_small, blur_large)

    k = int(max(5, min(31, round(max_r * 2.8)))) | 1
    top_hat = cv2.morphologyEx(src, cv2.MORPH_TOPHAT, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k)))

    response = cv2.bitwise_and(cv2.addWeighted(dog, 0.75, top_hat, 0.55, 0), grid_ignore)
    vals = response[response > 0]
    if vals.size == 0: return []

    thr = max(12.0, float(np.mean(vals) + 1.6 * np.std(vals)))
    _, mask = cv2.threshold(response, thr, 255, cv2.THRESH_BINARY)
    mask = cv2.morphologyEx(cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8)), cv2.MORPH_CLOSE, np.ones((2, 2), np.uint8))

    cnts, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    candidates = []
    min_area, max_area = max(2.5, np.pi * (min_r * 0.4) ** 2), max(np.pi * (min_r * 0.4) ** 2 * 3.0, np.pi * (max_r * 1.4) ** 2)

    for c in cnts:
        area = float(cv2.contourArea(c))
        if min_area < area < max_area:
            M = cv2.moments(c)
            if M["m00"] != 0:
                cx, cy = int(M["m10"] / M["m00"]), int(M["m01"] / M["m00"])
                _, enc_r = cv2.minEnclosingCircle(c)
                area_r = np.sqrt(max(area, 1.0) / np.pi)
                candidates.append((cx, cy, max(min_r * 0.7, min(max_r, max(float(enc_r), area_r) * 1.2))))

    return candidates if len(candidates) <= max(6, int((h * w) / 450.0)) else []

