ANALYSIS_WIDTH = 1600
MODEL_FILENAME = "cell_rtrees_25-11_4pairs.xml"
MODEL_SCORE_THRESHOLD = 0.80
MODEL_NMS_DISTANCE = 10.0  # legacy reference only; Track 5 now uses radius-aware NMS
