AUTO_ROI_PADDING_RATIO = 0.15


# Microalgae images are normalized to a fixed high-resolution preprocessing
# canvas, then returned at ANALYSIS_WIDTH so the separately embedded RTrees
# model sees the same spatial scale used during training.
MICROALGAE_DETAIL_WIDTH = 2400
INDEPENDENT_PAIR_GEOMETRY = True
PAIR_CLASSIFY_WIDTH = 1200


def _resize_keep_aspect(bgr_img, target_width, sharpen=False):
    if bgr_img is None or bgr_img.size == 0:
        raise ValueError("Empty microscopy image")
    h, w = bgr_img.shape[:2]
    target_width = max(320, int(target_width))
    target_h = max(1, int(round(h * target_width / float(w))))
    interpolation = cv2.INTER_LANCZOS4 if target_width > w else cv2.INTER_AREA
    resized = cv2.resize(bgr_img, (target_width, target_h), interpolation=interpolation)
    if sharpen:
        blur = cv2.GaussianBlur(resized, (0, 0), 1.0)
        resized = cv2.addWeighted(resized, 1.22, blur, -0.22, 0)
    return resized


def _gray_world_white_balance(bgr_img):
    """Conservative gray-world white balance with clipped channel gains."""
    img = np.asarray(bgr_img, dtype=np.uint8)
    work = img.astype(np.float32)
    # Ignore extreme black/white pixels (borders and scale bars) when possible.
    luminance = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    valid = (luminance > 8) & (luminance < 247)
    if np.count_nonzero(valid) > 1000:
        means = np.array([np.mean(work[:, :, c][valid]) for c in range(3)], dtype=np.float32)
    else:
        means = work.reshape(-1, 3).mean(axis=0)
    target = float(np.mean(means))
    gains = np.clip(target / np.maximum(means, 1.0), 0.65, 1.65)
    balanced = np.clip(work * gains.reshape(1, 1, 3), 0, 255).astype(np.uint8)
    return balanced


def _standardize_microalgae_bgr(bgr_img, output_width=ANALYSIS_WIDTH):
    """Unify scale, white balance, brightness and local contrast.

    Processing order:
      1) fixed high-resolution scale normalization (upscale with Lanczos when needed),
      2) gray-world white balance,
      3) robust LAB luminance normalization + mild CLAHE,
      4) detail-preserving resize to the model's fixed analysis width.
    """
    detail_width = max(int(output_width), MICROALGAE_DETAIL_WIDTH)
    detail = _resize_keep_aspect(bgr_img, detail_width, sharpen=False)
    detail = _gray_world_white_balance(detail)

    lab = cv2.cvtColor(detail, cv2.COLOR_BGR2LAB)
    lightness, chan_a, chan_b = cv2.split(lab)
    p_low, p_high = np.percentile(lightness, (1.5, 98.5))
    if p_high - p_low >= 8.0:
        lightness = np.clip(
            18.0 + (lightness.astype(np.float32) - p_low) * (222.0 / (p_high - p_low)),
            0, 255,
        ).astype(np.uint8)
    clahe = cv2.createCLAHE(clipLimit=1.8, tileGridSize=(10, 10))
    lightness = clahe.apply(lightness)
    normalized = cv2.cvtColor(cv2.merge((lightness, chan_a, chan_b)), cv2.COLOR_LAB2BGR)

    normalized = _resize_keep_aspect(normalized, int(output_width), sharpen=True)
    return normalized


def _explicit_pair_hint(path):
    """Read only unambiguous Q-pair hints from a file or parent-folder name."""
    compact = os.path.abspath(str(path)).lower()
    compact = compact.replace(' ', '').replace('_', '').replace('-', '')
    top_tokens = ('q1q2', 'q12', 'quadrant1quadrant2', 'quadrants12')
    bottom_tokens = ('q3q4', 'q34', 'quadrant3quadrant4', 'quadrants34')
    if any(token in compact for token in top_tokens):
        return 'top'
    if any(token in compact for token in bottom_tokens):
        return 'bottom'
    return None


def _quadrant_pair_signature(bgr_img):
    """Infer Q1-Q2 versus Q3-Q4 from the dense horizontal-grid band.

    In the user's two-field acquisition, the Q1-Q2 image has the dense
    hemocytometer band near the bottom, whereas Q3-Q4 has it near the top.
    A positive score therefore means Q1-Q2; a negative score means Q3-Q4.
    """
    img = _standardize_microalgae_bgr(bgr_img, PAIR_CLASSIFY_WIDTH)
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (3, 3), 0)
    binary = cv2.adaptiveThreshold(
        blur, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
        cv2.THRESH_BINARY, 51, -3,
    )
    line_length = max(50, int(round(gray.shape[1] * 0.05)))
    horizontal = cv2.morphologyEx(
        binary, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_length, 1)),
    )
    horizontal = cv2.dilate(
        horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)), iterations=1
    )
    row_coverage = horizontal.mean(axis=1).astype(np.float32) / 255.0
    height = len(row_coverage)
    top = row_coverage[int(0.01 * height):int(0.48 * height)]
    bottom = row_coverage[int(0.52 * height):int(0.99 * height)]
    baseline = 0.08
    top_strength = float(np.sum(np.clip(top - baseline, 0.0, None)))
    bottom_strength = float(np.sum(np.clip(bottom - baseline, 0.0, None)))
    score = bottom_strength - top_strength
    confidence = min(0.999, abs(score) / max(1.0, top_strength + bottom_strength))
    mode = 'top' if score >= 0.0 else 'bottom'
    return mode, confidence, score, top_strength, bottom_strength


def _resolve_quadrant_pair_order(paths, images):
    """Return image entries ordered as Q1-Q2 then Q3-Q4.

    With one image, only its inferred pair is returned. With two images, the
    higher dense-band score is assigned Q1-Q2 and the lower score Q3-Q4,
    regardless of upload order. Explicit q1q2/q3q4 names take priority.
    """
    if len(paths) != len(images):
        raise ValueError("Image path/data length mismatch")
    entries = []
    for path, image in zip(paths, images):
        mode, confidence, score, top_strength, bottom_strength = _quadrant_pair_signature(image)
        hint = _explicit_pair_hint(path)
        if hint is not None:
            mode = hint
            confidence = max(confidence, 0.995)
        entries.append({
            'path': path,
            'image': image,
            'mode': mode,
            'confidence': float(confidence),
            'score': float(score),
            'top_strength': float(top_strength),
            'bottom_strength': float(bottom_strength),
            'explicit': hint is not None,
        })

    if len(entries) == 1:
        return entries

    # For the normal two-image workflow, force a unique top/bottom assignment.
    # First honor a unique explicit hint; infer the other image automatically.
    if len(entries) >= 2:
        first_two = entries[:2]
        explicit_top = [e for e in first_two if e['explicit'] and e['mode'] == 'top']
        explicit_bottom = [e for e in first_two if e['explicit'] and e['mode'] == 'bottom']
        if len(explicit_top) == 1 and len(explicit_bottom) == 1:
            top_entry, bottom_entry = explicit_top[0], explicit_bottom[0]
        elif len(explicit_top) == 1:
            top_entry = explicit_top[0]
            bottom_entry = next(e for e in first_two if e is not top_entry)
            bottom_entry['mode'] = 'bottom'
        elif len(explicit_bottom) == 1:
            bottom_entry = explicit_bottom[0]
            top_entry = next(e for e in first_two if e is not bottom_entry)
            top_entry['mode'] = 'top'
        else:
            ordered = sorted(first_two, key=lambda e: e['score'], reverse=True)
            top_entry, bottom_entry = ordered[0], ordered[-1]
            top_entry['mode'] = 'top'
            bottom_entry['mode'] = 'bottom'
        return [top_entry, bottom_entry] + entries[2:]

    return entries


HALF_NAMES = {"top": "윗부분(Q1-Q2)", "bottom": "아랫부분(Q3-Q4)"}


def _capture_set_problem(resolved):
    """Check that a standard hemocytometer analysis gets one upper (Q1-Q2) and
    one lower (Q3-Q4) capture.  High-magnification fields (1 mm squares not
    resolved) have no halves and are not checked.  Returns None or a dict."""
    infos = []
    for e in resolved[:2]:
        try:
            mode, conf, score, _, _ = _quadrant_pair_signature(e["image"])
        except Exception:
            return None
        if e.get("explicit"):
            mode, clear = e["mode"], True
        else:
            clear = abs(float(score)) >= 20.0
        try:
            g = cv2.cvtColor(_resize_keep_aspect(e["image"], ANALYSIS_WIDTH), cv2.COLOR_BGR2GRAY)
            ppm, _ = _hemocytometer_px_per_mm(g)
        except Exception:
            ppm = None
        if ppm and not (0.85 <= ppm / STANDARD_PX_PER_MM <= 1.15):
            return None
        infos.append({"path": e["path"], "mode": mode, "clear": clear})
    if len(infos) == 1 and infos[0]["clear"]:
        have = infos[0]["mode"]
        need = "bottom" if have == "top" else "top"
        return {"kind": "single", "have": have, "need": need,
                "message": (f"{HALF_NAMES[have]} 사진만 들어왔습니다.\n"
                            f"혈구계 {HALF_NAMES[need]} 사진도 함께 넣어주세요.\n\n"
                            f"현재 사진: {os.path.basename(infos[0]['path'])}")}
    if len(infos) == 2 and infos[0]["clear"] and infos[1]["clear"] and infos[0]["mode"] == infos[1]["mode"]:
        have = infos[0]["mode"]
        need = "bottom" if have == "top" else "top"
        return {"kind": "same_half", "have": have, "need": need,
                "message": (f"두 사진이 모두 혈구계 {HALF_NAMES[have]}입니다. 사진을 잘못 넣었습니다.\n"
                            f"한 장은 {HALF_NAMES['top']}, 다른 한 장은 {HALF_NAMES['bottom']}이어야 합니다.\n\n"
                            + "\n".join(f"- {os.path.basename(i['path'])}: {HALF_NAMES[i['mode']]}" for i in infos))}
    return None


def _pair_label(mode):
    return 'Q1-Q2' if mode == 'top' else 'Q3-Q4'
