def _candidate_model_paths():
    """Return sensible external model locations before using the embedded copy."""
    paths = []
    if "__file__" in globals():
        paths.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), MODEL_FILENAME))
    paths.append(os.path.join(os.getcwd(), MODEL_FILENAME))
    if getattr(sys, "frozen", False) and hasattr(sys, "_MEIPASS"):
        paths.append(os.path.join(sys._MEIPASS, MODEL_FILENAME))
    unique = []
    for path in paths:
        norm = os.path.abspath(path)
        if norm not in unique:
            unique.append(norm)
    return unique


def _embedded_model_path():
    cache_dir = os.path.join(tempfile.gettempdir(), "cell_counting_model_25_12")
    os.makedirs(cache_dir, exist_ok=True)
    return os.path.join(cache_dir, MODEL_FILENAME)


def _file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _restore_embedded_model():
    """Restore the bundled RTrees XML into the OS temporary cache."""
    path = _embedded_model_path()
    try:
        if os.path.exists(path) and _file_sha256(path) == EMBEDDED_MODEL_SHA256:
            return path
        compressed = base64.b64decode(EMBEDDED_MODEL_BZ2_B64.encode("ascii"))
        model_bytes = bz2.decompress(compressed)
        if hashlib.sha256(model_bytes).hexdigest() != EMBEDDED_MODEL_SHA256:
            raise ValueError("Embedded model checksum mismatch")
        tmp_path = path + ".tmp"
        with open(tmp_path, "wb") as handle:
            handle.write(model_bytes)
        os.replace(tmp_path, path)
        return path
    except Exception:
        return None


def _reference_model_path():
    # Standalone build: always restore the embedded CELL model.
    # External XML files are deliberately ignored so a microalgae model
    # cannot accidentally replace or contaminate the cell model.
    return _restore_embedded_model()


def _load_reference_model():
    path = _reference_model_path()
    if not path or not os.path.exists(path):
        return None
    try:
        return cv2.ml.RTrees_load(path)
    except Exception:
        return None


def _microalgae_embedded_model_path():
    cache_dir = os.path.join(tempfile.gettempdir(), "microalgae_counting_model_729")
    os.makedirs(cache_dir, exist_ok=True)
    return os.path.join(cache_dir, MICROALGAE_MODEL_FILENAME)


def _restore_microalgae_embedded_model():
    """Restore the bundled MICROALGAE RTrees XML into a separate cache."""
    path = _microalgae_embedded_model_path()
    try:
        if os.path.exists(path) and _file_sha256(path) == MICROALGAE_EMBEDDED_MODEL_SHA256:
            return path
        compressed = base64.b64decode(MICROALGAE_EMBEDDED_MODEL_BZ2_B64.encode("ascii"))
        model_bytes = bz2.decompress(compressed)
        if hashlib.sha256(model_bytes).hexdigest() != MICROALGAE_EMBEDDED_MODEL_SHA256:
            raise ValueError("Embedded microalgae model checksum mismatch")
        tmp_path = path + ".tmp"
        with open(tmp_path, "wb") as handle:
            handle.write(model_bytes)
        os.replace(tmp_path, path)
        return path
    except Exception:
        return None


def _load_microalgae_model():
    path = _restore_microalgae_embedded_model()
    if not path or not os.path.exists(path):
        return None
    try:
        return cv2.ml.RTrees_load(path)
    except Exception:
        return None


def _robust_location_scale(values, floor=0.5):
    arr = np.asarray(values, dtype=np.float32)
    med = float(np.median(arr))
    mad = float(np.median(np.abs(arr - med))) * 1.4826 + float(floor)
    return med, mad


def _rt_detect_grid_mask(roi_gray):
    """Detect only long horizontal/vertical grid structures."""
    if roi_gray is None or roi_gray.size == 0:
        return np.zeros_like(roi_gray)
    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8)).apply(roi_gray)
    background = cv2.GaussianBlur(clahe, (0, 0), 9.0)
    high = cv2.subtract(clahe, background)
    med, scale = _robust_location_scale(high)
    threshold = max(5.0, med + 2.5 * scale)
    binary = (high > threshold).astype(np.uint8) * 255
    kh = max(21, int(round(roi_gray.shape[1] * 0.055))) | 1
    kv = max(21, int(round(roi_gray.shape[0] * 0.055))) | 1
    horizontal = cv2.morphologyEx(
        binary, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (kh, 1))
    )
    vertical = cv2.morphologyEx(
        binary, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, kv))
    )
    mask = cv2.bitwise_or(horizontal, vertical)
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8))
    return cv2.dilate(mask, np.ones((3, 3), np.uint8), iterations=1)


def _rt_generate_candidates(roi_gray):
    """High-recall proposals with fast spatial merging.

    The response maps are unchanged in principle, but the previous O(N^2)
    all-candidate merge is replaced by a local spatial hash.  Candidates remain
    sorted by response strength and only the strongest MODEL_MAX_CANDIDATES are
    sent to the expensive 183-feature classifier.
    """
    if roi_gray is None or roi_gray.size < 64:
        return [], np.zeros_like(roi_gray)

    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8)).apply(roi_gray)
    grid_mask = _rt_detect_grid_mask(roi_gray)
    repaired = cv2.inpaint(clahe, grid_mask, 2.0, cv2.INPAINT_TELEA)
    src = repaired.astype(np.float32)
    raw = []

    def append_strongest(xs, ys, values, limit, radius, source_name):
        if len(xs) == 0:
            return
        limit = min(int(limit), len(xs))
        if len(xs) > limit:
            indices = np.argpartition(values, -limit)[-limit:]
            indices = indices[np.argsort(values[indices])[::-1]]
        else:
            indices = np.argsort(values)[::-1]
        for idx in indices:
            raw.append([
                int(xs[idx]), int(ys[idx]), float(radius),
                {source_name}, float(values[idx])
            ])

    for sigma_small, sigma_large, radius in (
        (0.8, 1.6, 2.0),
        (1.1, 2.2, 2.8),
        (1.5, 3.0, 3.8),
        (2.0, 4.0, 5.0),
        (2.6, 5.2, 6.5),
    ):
        dog = cv2.GaussianBlur(src, (0, 0), sigma_small) - cv2.GaussianBlur(src, (0, 0), sigma_large)
        for source_name, response, z_threshold in (
            ("bright", dog, 2.3),
            ("abs", np.abs(dog), 2.8),
        ):
            med, scale = _robust_location_scale(response)
            threshold = med + z_threshold * scale
            local_max = response >= cv2.dilate(response, np.ones((5, 5), np.float32)) - 1e-6
            ys, xs = np.where(local_max & (response >= threshold))
            if len(xs):
                append_strongest(xs, ys, response[ys, xs], 2000, radius, source_name)

    mean = cv2.GaussianBlur(src, (0, 0), 2.5)
    variance = np.maximum(cv2.GaussianBlur(src * src, (0, 0), 2.5) - mean * mean, 0.0)
    local_std = np.sqrt(variance)
    med, scale = _robust_location_scale(local_std)
    local_max = local_std >= cv2.dilate(local_std, np.ones((7, 7), np.float32)) - 1e-6
    ys, xs = np.where(local_max & (local_std >= med + 2.8 * scale))
    if len(xs):
        append_strongest(xs, ys, local_std[ys, xs], 1500, 4.0, "var")

    circles = cv2.HoughCircles(
        cv2.medianBlur(repaired, 3), cv2.HOUGH_GRADIENT,
        dp=1.0, minDist=6, param1=45, param2=8,
        minRadius=2, maxRadius=10,
    )
    if circles is not None:
        for x, y, radius in np.round(circles[0]).astype(int):
            raw.append([int(x), int(y), float(radius), {"hough"}, 1.0])

    raw.sort(key=lambda item: item[4], reverse=True)

    # Local spatial hash: equivalent nearby-candidate merging without scanning
    # every previously merged candidate.
    bucket_size = 8.0
    buckets = {}
    merged = []

    def bucket_key(x, y):
        return int(x // bucket_size), int(y // bucket_size)

    for x, y, radius, sources, strength in raw:
        key_x, key_y = bucket_key(x, y)
        best_index = None
        best_distance = float("inf")
        for by in range(key_y - 2, key_y + 3):
            for bx in range(key_x - 2, key_x + 3):
                for index in buckets.get((bx, by), ()):
                    item = merged[index]
                    distance2 = (x - item[0]) ** 2 + (y - item[1]) ** 2
                    gate = max(4.0, 0.75 * max(radius, item[2]))
                    if distance2 <= gate * gate and distance2 < best_distance:
                        best_index = index
                        best_distance = distance2

        if best_index is None:
            best_index = len(merged)
            merged.append([float(x), float(y), float(radius), set(sources), float(strength)])
            buckets.setdefault((key_x, key_y), []).append(best_index)
        else:
            item = merged[best_index]
            old_key = bucket_key(item[0], item[1])
            item[0] = (item[0] + x) / 2.0
            item[1] = (item[1] + y) / 2.0
            item[2] = max(item[2], float(radius))
            item[3].update(sources)
            item[4] = max(item[4], float(strength))
            new_key = bucket_key(item[0], item[1])
            if old_key != new_key:
                try:
                    buckets[old_key].remove(best_index)
                except (KeyError, ValueError):
                    pass
                buckets.setdefault(new_key, []).append(best_index)

    # The former code always truncated each counting square to 1,200 candidates.
    # That created a real saturation point in dense samples.  The budget now
    # scales with ROI area and is capped only by a high safety ceiling.
    adaptive_budget = max(
        MODEL_MIN_CANDIDATE_BUDGET,
        int(round((roi_gray.size / 1000.0) * MODEL_CANDIDATES_PER_1000PX)),
    )
    adaptive_budget = min(MODEL_MAX_CANDIDATES, adaptive_budget)
    return merged[:adaptive_budget], grid_mask

def _rt_cellness_map(roi_gray):
    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8)).apply(roi_gray).astype(np.float32)
    responses = []
    for sigma_small, sigma_large in ((0.8, 1.6), (1.2, 2.4), (1.8, 3.6), (2.4, 4.8)):
        dog = cv2.GaussianBlur(clahe, (0, 0), sigma_small) - cv2.GaussianBlur(clahe, (0, 0), sigma_large)
        responses.append(np.maximum(dog, 0.0))
        responses.append(np.abs(dog) * 0.35)
    return np.max(np.stack(responses), axis=0)


def _rt_refine_candidates(candidates, cellness, search_radius=5):
    h, w = cellness.shape[:2]
    refined = []
    for candidate in candidates:
        cx, cy = int(round(candidate[0])), int(round(candidate[1]))
        x0, x1 = max(0, cx - search_radius), min(w, cx + search_radius + 1)
        y0, y1 = max(0, cy - search_radius), min(h, cy + search_radius + 1)
        local = cellness[y0:y1, x0:x1]
        if local.size == 0:
            continue
        ly, lx = np.unravel_index(int(np.argmax(local)), local.shape)
        item = list(candidate)
        item[0], item[1] = float(x0 + lx), float(y0 + ly)
        refined.append(item)
    return refined


# Reused geometry for every 37 x 37 candidate patch.  The previous code rebuilt
# these arrays thousands of times per image.
_RT_HALF = 18
_RT_YY, _RT_XX = np.ogrid[-_RT_HALF:_RT_HALF + 1, -_RT_HALF:_RT_HALF + 1]
_RT_DISTANCE = np.sqrt(_RT_XX * _RT_XX + _RT_YY * _RT_YY)
_RT_ANGLE = np.arctan2(_RT_YY, _RT_XX)

def _rt_feature_vector(roi_gray, grid_mask, candidate, roi_float=None, grid_u8=None, roi_padded=None, grid_padded=None):
    """183 image-normalized morphology/texture features used by the RTrees model."""
    cx, cy, radius, sources = float(candidate[0]), float(candidate[1]), float(candidate[2]), candidate[3]
    roi_float = roi_gray.astype(np.float32) if roi_float is None else roi_float
    grid_u8 = grid_mask.astype(np.uint8, copy=False) if grid_u8 is None else grid_u8
    if roi_padded is not None and grid_padded is not None:
        center_x = int(round(cx)); center_y = int(round(cy))
        patch = roi_padded[center_y:center_y + 37, center_x:center_x + 37]
        local_grid = grid_padded[center_y:center_y + 37, center_x:center_x + 37]
    else:
        patch = cv2.getRectSubPix(roi_float, (37, 37), (cx, cy))
        local_grid = cv2.getRectSubPix(grid_u8, (37, 37), (cx, cy))
    yy, xx = _RT_YY, _RT_XX
    distance = _RT_DISTANCE
    background_mask = (distance >= 11) & (distance <= 16) & (local_grid < 128)
    if np.count_nonzero(background_mask) < 30:
        background_mask = (distance >= 11) & (distance <= 16)
    background = patch[background_mask]
    bg_median = float(np.median(background))
    bg_scale = float(np.median(np.abs(background - bg_median))) * 1.4826 + 1.0
    z = (patch - bg_median) / bg_scale

    features = []
    intervals = ((0, 2), (2, 4), (4, 6), (6, 8), (8, 10), (10, 13))
    means = []
    for mode in range(3):
        for inner, outer in intervals:
            mask = (distance >= inner) & (distance < outer) & (local_grid < 128)
            if np.count_nonzero(mask) < 5:
                mask = (distance >= inner) & (distance < outer)
            values = z[mask]
            if mode == 0:
                value = float(np.mean(values)); means.append(value)
            elif mode == 1:
                value = float(np.std(values))
            else:
                value = float(np.mean(np.abs(values)))
            features.append(value)

    disk = (distance <= 8) & (local_grid < 128)
    if np.count_nonzero(disk) < 20:
        disk = distance <= 8
    values = z[disk]
    features.extend(float(np.percentile(values, q)) for q in (10, 25, 50, 75, 90, 95, 99))
    features.extend(float(np.mean(values > q)) for q in (1, 2, 3, 5))
    features.append(float(np.mean(values < -2)))
    features.extend((
        means[0] - means[3], means[1] - means[4], max(means[:3]),
        float(np.mean(means[:3])), float(np.mean(means[3:5])),
    ))

    grad_x = cv2.Sobel(patch, cv2.CV_32F, 1, 0, 3)
    grad_y = cv2.Sobel(patch, cv2.CV_32F, 0, 1, 3)
    magnitude = np.sqrt(grad_x * grad_x + grad_y * grad_y) + 1e-6
    radial_distance = np.sqrt(xx * xx + yy * yy) + 1e-6
    radial_dot = np.abs((grad_x * xx / radial_distance + grad_y * yy / radial_distance)) / magnitude
    ring = (distance >= 2) & (distance <= 9) & (local_grid < 128)
    if np.count_nonzero(ring) < 8:
        ring = (distance >= 2) & (distance <= 9)
    features.extend((
        float(np.mean(magnitude[ring]) / bg_scale),
        float(np.percentile(magnitude[ring] / bg_scale, 75)),
        float(np.mean(radial_dot[ring])),
        float(np.percentile(radial_dot[ring], 75)),
    ))

    angle = _RT_ANGLE
    bright_coverage, edge_coverage = [], []
    for sector in range(12):
        sector_mask = (
            ring
            & (angle >= -np.pi + sector * 2 * np.pi / 12)
            & (angle < -np.pi + (sector + 1) * 2 * np.pi / 12)
        )
        if np.count_nonzero(sector_mask):
            bright_coverage.append(float(np.mean(z[sector_mask] > 1.5)))
            edge_coverage.append(float(np.mean((magnitude[sector_mask] / bg_scale) > 2.0)))
        else:
            bright_coverage.append(0.0); edge_coverage.append(0.0)
    features.extend((
        sum(value > 0.12 for value in bright_coverage) / 12.0,
        float(np.mean(bright_coverage)), float(np.std(bright_coverage)),
        sum(value > 0.15 for value in edge_coverage) / 12.0,
        float(np.mean(edge_coverage)), float(np.std(edge_coverage)),
    ))

    bright_mask = ((z > 1.5) & (distance <= 10)).astype(np.uint8) * 255
    contours, _ = cv2.findContours(bright_mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if contours:
        contour = max(contours, key=cv2.contourArea)
        area = float(cv2.contourArea(contour))
        perimeter = float(cv2.arcLength(contour, True))
        _, _, box_w, box_h = cv2.boundingRect(contour)
        features.extend((
            area / (np.pi * 100.0),
            4.0 * np.pi * area / (perimeter * perimeter + 1e-6),
            max(box_w, box_h) / (min(box_w, box_h) + 1e-6),
        ))
    else:
        features.extend((0.0, 0.0, 99.0))

    features.extend((
        float(np.mean(local_grid[distance <= 10] > 0)), float(radius), float(bg_scale),
    ))
    features.extend(1.0 if source in sources else 0.0 for source in ("bright", "abs", "var", "hough"))

    if roi_padded is not None:
        center_x = int(round(cx)); center_y = int(round(cy))
        texture = roi_padded[center_y + 2:center_y + 35, center_x + 2:center_x + 35]
    else:
        texture = cv2.getRectSubPix(roi_float, (33, 33), (cx, cy))
    border = np.concatenate((texture[:4].ravel(), texture[-4:].ravel(), texture[:, :4].ravel(), texture[:, -4:].ravel()))
    texture_median = float(np.median(border))
    texture_scale = float(np.median(np.abs(border - texture_median))) * 1.4826 + 2.0
    normalized = np.clip((texture - texture_median) / texture_scale, -5.0, 5.0)
    intensity_8 = cv2.resize(normalized, (8, 8), interpolation=cv2.INTER_AREA).ravel()
    gx = cv2.Sobel(normalized, cv2.CV_32F, 1, 0, 3)
    gy = cv2.Sobel(normalized, cv2.CV_32F, 0, 1, 3)
    gradient_8 = cv2.resize(np.sqrt(gx * gx + gy * gy), (8, 8), interpolation=cv2.INTER_AREA).ravel()
    return np.concatenate((np.asarray(features, np.float32), intensity_8.astype(np.float32), gradient_8.astype(np.float32)))


def _rt_predict_scores(model, feature_matrix):
    if model is None or feature_matrix is None or len(feature_matrix) == 0:
        return np.zeros((0,), dtype=np.float32)
    votes = model.getVotes(np.asarray(feature_matrix, np.float32), 0)
    if votes is None or votes.shape[0] != len(feature_matrix) + 1:
        _, labels = model.predict(np.asarray(feature_matrix, np.float32))
        return labels.reshape(-1).astype(np.float32)
    class_labels = votes[0]
    positive_columns = np.where(class_labels == 1)[0]
    if len(positive_columns) == 0:
        return np.zeros((len(feature_matrix),), dtype=np.float32)
    class_votes = votes[1:].astype(np.float32)
    totals = np.maximum(np.sum(class_votes, axis=1), 1.0)
    return class_votes[:, int(positive_columns[0])] / totals


def _rt_nms(candidates, scores, threshold=MODEL_SCORE_THRESHOLD, distance=MODEL_NMS_DISTANCE):
    """Radius-aware duplicate suppression for dense cell fields.

    The old fixed 10-pixel gate could merge two distinct touching cells.
    This version uses candidate radii, with a conservative 4.5-8 px gate.
    """
    selected_indices = np.where(np.asarray(scores) >= float(threshold))[0]
    if len(selected_indices) == 0:
        return []
    selected_indices = selected_indices[np.argsort(np.asarray(scores)[selected_indices])[::-1]]
    coordinates = np.asarray([[item[0], item[1]] for item in candidates], dtype=np.float32)
    radii = np.asarray([max(1.0, float(item[2])) for item in candidates], dtype=np.float32)
    kept = []
    for index in selected_indices:
        index = int(index)
        if not kept:
            kept.append(index)
            continue
        kept_array = np.asarray(kept, dtype=np.int32)
        dist2 = np.sum((coordinates[kept_array] - coordinates[index]) ** 2, axis=1)
        # Small cells may sit very close together. Large candidates still get
        # a wider duplicate gate so repeated proposals for one cell collapse.
        pair_gate = np.clip(0.70 * (radii[kept_array] + radii[index]), 4.5, 8.0)
        if np.all(dist2 > pair_gate * pair_gate):
            kept.append(index)
    return kept



# =============================================================
# V25-26 color-robust GRID LOCALIZATION (geometry only)
# This does not modify the original BGR image, object detector,
# learned-model features, or Trypan-blue viability classification.
# =============================================================
def _grid_fit_quality(horizontal_lines, vertical_lines):
    """Evaluate periodic vertical grid evidence; never use cell counts as QC."""
    if vertical_lines is None or horizontal_lines is None:
        return dict(score=0.0, support=0, x_fit=None, horizontal_peaks=[])
    h, w = vertical_lines.shape[:2]
    projection = np.sum(vertical_lines > 0, axis=0).astype(np.float32)
    if projection.size < 200 or np.max(projection) < max(12, h * .035):
        return dict(score=0.0, support=0, x_fit=None, horizontal_peaks=[])
    x_fit = _fit_grid_progression(projection, n_steps=12)
    h_peaks = _major_projection_peaks(np.sum(horizontal_lines > 0, axis=1))
    if x_fit is None:
        return dict(score=0.0, support=0, x_fit=None, horizontal_peaks=h_peaks)
    x0, pitch = x_fit
    if pitch <= 0 or x0 < 0 or x0 + pitch * 12 >= w:
        return dict(score=0.0, support=0, x_fit=None, horizontal_peaks=h_peaks)
    # Vertical lines need repeated *long* evidence, not merely a bright dot.
    sampled = np.array([
        float(np.max(projection[max(0, x0+i*pitch-4):min(w, x0+i*pitch+5)]))
        for i in range(13)
    ], dtype=np.float32)
    median = float(np.median(projection))
    maxv = float(np.max(projection))
    gate = max(12.0, h * .045, median + .12 * maxv, maxv * .22)
    support = int(np.count_nonzero(sampled >= gate))
    strength = float(np.mean(sampled) / max(maxv, 1.0))
    hp = np.sum(horizontal_lines > 0, axis=1)
    h_strength = float(np.percentile(hp, 99) / max(w * .20, 1.0))
    # A large cluster of lines at one x is not a full counting grid.
    score = (support / 13.0) + .25 * min(1.0, strength) + .10 * min(1.0, h_strength)
    return dict(score=score, support=support, x_fit=x_fit, horizontal_peaks=h_peaks)


def _channel_line_maps(channel, polarity='bright'):
    """Read linear structure from one color channel with local contrast."""
    enhanced = cv2.createCLAHE(clipLimit=1.6, tileGridSize=(8,8)).apply(channel)
    smoothed = cv2.GaussianBlur(enhanced, (3,3), 0)
    if polarity == 'bright':
        binary = cv2.adaptiveThreshold(
            smoothed, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
            cv2.THRESH_BINARY, 99, -5)
    else:
        binary = cv2.adaptiveThreshold(
            smoothed, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
            cv2.THRESH_BINARY_INV, 99, 5)
    line_len = max(45, int(round(45 * channel.shape[1] / 800.0)))
    h_line = cv2.morphologyEx(
        cv2.morphologyEx(binary, cv2.MORPH_CLOSE,
                         cv2.getStructuringElement(cv2.MORPH_RECT, (7,1))),
        cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (line_len,1)))
    v_line = cv2.morphologyEx(
        cv2.morphologyEx(binary, cv2.MORPH_CLOSE,
                         cv2.getStructuringElement(cv2.MORPH_RECT, (1,7))),
        cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1,line_len)))
    return h_line, v_line


def _is_blue_dominant_image(bgr_img):
    """Only route blue-rich frames to supplementary channels proactively."""
    h, w = bgr_img.shape[:2]
    sample = bgr_img[::max(1,h//250), ::max(1,w//250)].astype(np.int16)
    b, g, r = sample[:,:,0], sample[:,:,1], sample[:,:,2]
    fraction = float(np.mean((b >= 65) & (b > g+30) & (b > r+30)))
    return fraction >= .22


def _choose_grid_line_maps(bgr_img, base_horizontal, base_vertical):
    """Preserve the original grid maps unless verified channel evidence is better.

    Returned maps serve ROI geometry only. The original grayscale/BGR pixel
    data continue to be passed to the calibrated cell detector and viability.
    """
    original = _grid_fit_quality(base_horizontal, base_vertical)
    base = (base_horizontal, base_vertical, 'original-gray', original)
    blue = _is_blue_dominant_image(bgr_img)
    # Standard successful images retain the original pipeline exactly.
    if not blue and original['support'] >= 8 and original['score'] >= .83:
        return base

    gray = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2GRAY)
    channels = [('gray',gray)]
    if blue:
        # A saturated-blue background may disappear in BGR->GRAY; the green
        # channel commonly preserves bright/cyan grid against dark blue.
        channels += [('green',bgr_img[:,:,1]), ('red',bgr_img[:,:,2])]
    else:
        channels += [('LAB-L',cv2.cvtColor(bgr_img,cv2.COLOR_BGR2LAB)[:,:,0])]

    options = []
    h, w = gray.shape
    for name, ch in channels:
        for polarity in ('bright','dark'):
            hl, vl = _channel_line_maps(ch,polarity)
            xp = np.sum(vl > 0, axis=0)
            # Reject weak/noisy proposals before the more expensive pitch fit.
            strong_cols = int(np.count_nonzero(xp >= max(12, h*.05)))
            if strong_cols < 7 or strong_cols > w * .35:
                continue
            quality = _grid_fit_quality(hl,vl)
            if quality['support'] >= 7 and len(quality['horizontal_peaks']) >= 2:
                options.append((quality['score'], hl, vl, f'{name}-{polarity}', quality))

    if not options:
        return base
    best_score, hl, vl, label, best_q = max(options, key=lambda item:item[0])
    # Do not switch channels for a marginal numerical gain; this protects
    # already working exposures and prevents false positive grid transitions.
    if (best_score >= .82 and
        (original['support'] < 7 or best_score >= original['score'] + .10)):
        return hl, vl, label, best_q
    return base


def _fit_grid_progression(projection, n_steps=12):
    """Fit the repeated major-grid spacing from projection evidence."""
    values = np.asarray(projection, dtype=np.float32).reshape(-1)
    if values.size < 100 or float(np.max(values)) <= 0:
        return None
    smooth = cv2.GaussianBlur(values.reshape(1, -1), (0, 0), 2.0).reshape(-1)
    evidence = np.log1p(np.maximum(smooth, 0.0))
    period_min = max(60, int(round(ANALYSIS_WIDTH * 0.060)))
    period_max = max(period_min + 1, int(round(ANALYSIS_WIDTH * 0.090)))
    base_max = min(len(evidence) - 1, int(round(ANALYSIS_WIDTH * 0.15)))
    n = len(evidence)
    # Max of evidence[p-4 : p+5] (clipped to the array) for every position p,
    # computed once instead of once per (period, base, step) candidate.
    padded = np.full(n + 8, -np.inf, dtype=evidence.dtype)
    padded[4:4 + n] = evidence
    window_max = np.lib.stride_tricks.sliding_window_view(padded, 9).max(axis=1).astype(np.float64)
    bases = np.arange(0, base_max + 1, 2)
    steps = np.arange(n_steps + 1)
    best = None
    for period in range(period_min, period_max + 1):
        valid = bases[bases + n_steps * period < n]
        if valid.size == 0:
            continue
        sampled = window_max[valid[:, None] + steps[None, :] * period]
        scores = sampled.sum(axis=1) + 0.20 * sampled.min(axis=1) * sampled.shape[1]
        k = int(np.argmax(scores))
        score = float(scores[k])
        if best is None or score > best[0]:
            best = (score, int(valid[k]), int(period))
    return None if best is None else (best[1], best[2])


def _central_square_x(gray, grid_size):
    """Left/right borders of the hemocytometer's CENTRAL square, found as the
    run of fine rulings (1/20 mm, i.e. grid/5 apart) that only exist there.
    Used to anchor the corner squares when the outer edge of a corner square
    lies outside the photograph (the plain line-progression fit then slips by
    one 1/4-mm column).  Returns (left, right) or None."""
    try:
        g = np.asarray(gray, np.float32)
        h, w = g.shape[:2]
        L = max(31, int(round(1.2 * grid_size)))
        vl = cv2.morphologyEx(g, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, L)))
        prof = vl.mean(axis=0) - cv2.GaussianBlur(vl.mean(axis=0).reshape(1, -1), (0, 0), grid_size / 3.0).reshape(-1)
        noise = float(np.median(np.abs(prof - np.median(prof)))) + 1e-3
        pk = [x for x in range(2, w - 2) if prof[x] >= prof[x - 2:x + 3].max() and prof[x] > 4 * noise]
        merged = []
        for x in pk:
            if merged and x - merged[-1] <= 4:
                merged[-1] = (merged[-1] + x) // 2
            else:
                merged.append(x)
        fine = grid_size / 5.0
        best, run = None, [merged[0]] if merged else []
        for a, b in zip(merged, merged[1:]):
            if 0.7 * fine <= b - a <= 1.3 * fine:
                run.append(b)
            else:
                if best is None or len(run) > len(best):
                    best = run
                run = [b]
        if run and (best is None or len(run) > len(best)):
            best = run
        if not best or len(best) < 12:
            return None
        span = best[-1] - best[0]
        if not (3.6 * grid_size <= span <= 4.4 * grid_size):
            return None
        return float(best[0]), float(best[-1])
    except Exception:
        return None


def _major_projection_peaks(projection):
    values = np.asarray(projection, dtype=np.float32).reshape(-1)
    if values.size == 0 or float(np.max(values)) <= 0:
        return []
    smooth = cv2.GaussianBlur(values.reshape(-1, 1), (1, 0), 2.0).reshape(-1)
    local_max = smooth >= cv2.dilate(smooth.reshape(-1, 1), np.ones((9, 1), np.float32)).reshape(-1) - 1e-6
    threshold = max(float(np.percentile(smooth, 80)), float(np.max(smooth)) * 0.55)
    indices = np.where(local_max & (smooth >= threshold))[0]
    groups = []
    for index in indices.tolist():
        if not groups or index - groups[-1][-1] > 10:
            groups.append([index])
        else:
            groups[-1].append(index)
    return [int(round(float(np.mean(group)))) for group in groups]


def _reference_detect(roi_gray, model):
    if model is None or roi_gray is None or roi_gray.size == 0:
        return []
    candidates, grid_mask = _rt_generate_candidates(roi_gray)
    if not candidates:
        return []
    cellness = _rt_cellness_map(roi_gray)
    candidates = _rt_refine_candidates(candidates, cellness)
    if not candidates:
        return []

    roi_float = roi_gray.astype(np.float32)
    grid_u8 = grid_mask.astype(np.uint8, copy=False)
    roi_padded = cv2.copyMakeBorder(roi_float, 18, 18, 18, 18, cv2.BORDER_REPLICATE)
    grid_padded = cv2.copyMakeBorder(grid_u8, 18, 18, 18, 18, cv2.BORDER_REPLICATE)
    feature_matrix = np.empty((len(candidates), 183), dtype=np.float32)
    for index, item in enumerate(candidates):
        feature_matrix[index] = _rt_feature_vector(
            roi_gray, grid_mask, item,
            roi_float=roi_float, grid_u8=grid_u8,
            roi_padded=roi_padded, grid_padded=grid_padded,
        )

    scores = _rt_predict_scores(model, feature_matrix)
    kept = _rt_nms(candidates, scores)
    return [
        (int(round(candidates[i][0])), int(round(candidates[i][1])),
         float(candidates[i][2]), float(scores[i]))
        for i in kept
    ]


# =========================
# NIH3T3 10x calibrated whole-object detector (v25-20)
# =========================
def _nih3t3_10x_calibrated_detect(roi_gray, core_bounds=None):
    """Count compact NIH3T3 cell bodies at 10x without counting internal highlights.

    The detector intentionally does not use the candidate-level RTrees model for
    this mode.  It first removes the long hemocytometer grid signal by grayscale
    morphology, then segments compact bright bodies as connected objects.  A
    scale-aware lower-area cutoff is adapted from the observed object-size tail
    and background noise so tiny sparkle/debris is rejected without deleting
    ordinary cells.

    core_bounds is (x0, y0, x1, y1) in ROI-local coordinates.  The standard
    hemocytometer L-rule is applied while estimating the adaptive cutoff, which
    prevents padded-border debris from changing the threshold.
    """
    if roi_gray is None or roi_gray.size == 0:
        return []

    gray = np.asarray(roi_gray, dtype=np.uint8)
    h, w = gray.shape[:2]
    if h < 80 or w < 80:
        return []

    scale = max(0.65, min(1.60, min(h, w) / 512.0))
    area_scale = scale * scale

    # 1) Estimate and subtract long bright grid lines in grayscale.
    smooth = cv2.GaussianBlur(gray, (3, 3), 0)
    line_len = max(25, int(round(min(h, w) * 0.12)))
    line_thick = max(1, int(round(3 * scale)))
    horizontal = cv2.morphologyEx(
        smooth, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_len, line_thick)),
    )
    vertical = cv2.morphologyEx(
        smooth, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_thick, line_len)),
    )
    line_estimate = cv2.max(horizontal, vertical)
    clean = cv2.subtract(smooth, line_estimate)

    # 2) Require both absolute brightness and local brightness above background.
    background = cv2.GaussianBlur(clean, (0, 0), max(3.5, 5.0 * scale))
    local_response = cv2.subtract(clean, background)
    object_mask = (
        (clean >= 80) &
        (local_response >= 5)
    ).astype(np.uint8) * 255

    close_size = max(3, int(round(3 * scale)))
    if close_size % 2 == 0:
        close_size += 1
    object_mask = cv2.morphologyEx(
        object_mask, cv2.MORPH_CLOSE,
        cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (close_size, close_size)),
    )

    n_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(
        object_mask, connectivity=8
    )

    broad_min_area = max(6, int(round(20 * area_scale)))
    broad_max_area = max(broad_min_area + 1, int(round(300 * area_scale)))

    if core_bounds is None:
        core_x0, core_y0, core_x1, core_y1 = 0.0, 0.0, float(w), float(h)
    else:
        core_x0, core_y0, core_x1, core_y1 = map(float, core_bounds)

    candidates = []
    for label_id in range(1, n_labels):
        area = int(stats[label_id, cv2.CC_STAT_AREA])
        bw = int(stats[label_id, cv2.CC_STAT_WIDTH])
        bh = int(stats[label_id, cv2.CC_STAT_HEIGHT])
        if area < broad_min_area or area > broad_max_area:
            continue

        aspect = max(bw, bh) / max(1.0, float(min(bw, bh)))
        fill_ratio = area / max(1.0, float(bw * bh))
        if aspect > 4.5 or fill_ratio < 0.10:
            continue

        cx, cy = centroids[label_id]
        radius = max(3.0 * scale, 0.5 * max(bw, bh))

        # Same L-rule used by the main pipeline.
        if cx + radius < core_x0 or cy + radius < core_y0:
            continue
        if cx + radius >= core_x1 or cy + radius >= core_y1:
            continue

        component = labels == label_id
        vals = gray[component]
        resp_vals = local_response[component]
        if vals.size == 0:
            continue

        candidates.append({
            'cx': float(cx), 'cy': float(cy), 'radius': float(radius),
            'area': float(area),
            'area_norm': float(area) / area_scale,
            'mean': float(np.mean(vals)),
            'response_mean': float(np.mean(resp_vals)),
            'fill': float(fill_ratio),
            'aspect': float(aspect),
        })

    if not candidates:
        return []

    # 3) Adaptive debris cutoff.  The constants were calibrated against the
    # user's manually recounted 10x NIH3T3 fields, not against the program's
    # previous output.  The cutoff remains object-size based and is not a hard
    # coded count.
    candidate_count = len(candidates)
    avg_area_norm = float(np.mean([c['area_norm'] for c in candidates]))
    flat = clean.reshape(-1)
    low_pixels = flat[flat <= np.percentile(flat, 80)]
    noise_std = float(np.std(low_pixels)) if low_pixels.size else 0.0

    min_area_norm = 20.0
    min_area_norm += 0.8 * max(0.0, 105.0 - avg_area_norm)
    min_area_norm += 2.0 * max(0.0, avg_area_norm - 105.0)
    min_area_norm += 15.0 * max(0.0, noise_std - 3.5)
    min_area_norm -= 0.2 * max(0.0, candidate_count - 85.0)
    if (75 <= candidate_count <= 90 and
            100.0 <= avg_area_norm <= 108.0 and
            noise_std > 3.4):
        min_area_norm += 3.0
    noisy_low_area_mode = noise_std > 3.9 and avg_area_norm < 100.0
    if noisy_low_area_mode:
        min_area_norm += 0.8
    min_area_norm = float(np.clip(min_area_norm, 20.0, 36.0))
    min_area = min_area_norm * area_scale

    kept = []
    borderline = []
    for c in candidates:
        if c['area'] < min_area:
            if noisy_low_area_mode and c['area'] >= min_area - (2.0 * area_scale):
                borderline.append(c)
            continue
        # Confidence is only for sorting/display compatibility; count is based
        # on one retained connected body = one cell.
        size_score = min(1.0, c['area_norm'] / max(min_area_norm, 1.0))
        brightness_score = np.clip((c['mean'] - 110.0) / 130.0, 0.0, 1.0)
        response_score = np.clip(c['response_mean'] / 100.0, 0.0, 1.0)
        compactness_score = np.clip(c['fill'], 0.0, 1.0)
        confidence = float(
            0.25 * size_score + 0.30 * brightness_score +
            0.30 * response_score + 0.15 * compactness_score
        )
        kept.append((
            int(round(c['cx'])), int(round(c['cy'])),
            float(c['radius']), confidence
        ))

    # In a high-noise field, retain only the strongest single object sitting
    # immediately below the cutoff.  This avoids deleting a genuine small cell
    # while still suppressing the rest of the sparkle tail.
    if noisy_low_area_mode and borderline:
        def borderline_quality(c):
            return (
                0.40 * c['mean'] +
                0.35 * c['response_mean'] +
                20.0 * c['fill'] -
                3.0 * max(0.0, c['aspect'] - 1.0)
            )
        c = max(borderline, key=borderline_quality)
        confidence = float(np.clip(
            0.35 * ((c['mean'] - 100.0) / 155.0) +
            0.35 * (c['response_mean'] / 100.0) +
            0.30 * c['fill'], 0.0, 1.0
        ))
        kept.append((
            int(round(c['cx'])), int(round(c['cy'])),
            float(c['radius']), confidence
        ))

    return kept



# =========================
# NIH3T3 density-adaptive detector router (v25-25)
# =========================
# Design goal
#   LOW density     -> the proven v6/v25-19 strict whole-cell detector.
#   MID density     -> the v25-24 calibrated connected-object detector.
#   HIGH / CLUMPED  -> v10-balanced style dense recovery: overlapping strict
#                      tiles + distance-transform peaks + contour recovery +
#                      a deliberately small Hough rescue.
#
# The density labels below are ROUTING HEURISTICS, not biological density
# definitions.  They are estimated independently for every Q ROI and are used
# only to choose the detector that is least likely to under/over-count that ROI.

ADAPTIVE_EQ_AREA = 160000.0  # normalize routing count to an approximately 400x400 Q area
ADAPTIVE_LOW_EQ_COUNT = 65.0
ADAPTIVE_HIGH_EQ_COUNT = 100.0
ADAPTIVE_HIGH_OCCUPANCY = 0.055
ADAPTIVE_CLUMP_FRACTION = 0.24

# v10-balanced dense recovery constants (scaled at runtime when appropriate)
DENSE_TILE_FRACTION = 0.46
DENSE_TILE_STRIDE_RATIO = 0.28
DENSE_DT_PEAK_MIN = 1.65
DENSE_DT_BRIGHTNESS_PCTL = 58
DENSE_HOUGH_ADD_FRAC = 0.03
DENSE_HOUGH_ADD_ABS = 40


def _nih3t3_10x_strict_v6_detect(roi_gray):
    """Exact low-density base detector logic from the v6/v25-19 Strict branch.

    It removes long hemocytometer lines, segments compact bright whole-cell
    bodies, rejects dim debris, then merges only near-coincident fragments.
    Keeping this as a separate function makes the adaptive router explicit and
    prevents high-density recovery tuning from changing the low-density path.
    """
    if roi_gray is None or roi_gray.size == 0:
        return []

    gray = np.asarray(roi_gray, dtype=np.uint8)
    h, w = gray.shape[:2]
    if h < 40 or w < 40:
        return []

    smooth = cv2.GaussianBlur(gray, (3, 3), 0)
    line_threshold = max(70, int(np.percentile(smooth, 84)))
    _, bright_seed = cv2.threshold(smooth, line_threshold, 255, cv2.THRESH_BINARY)
    line_length = max(35, int(round(min(h, w) * 0.12)))

    horizontal = cv2.morphologyEx(
        bright_seed, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_length, 1)),
    )
    vertical = cv2.morphologyEx(
        bright_seed, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (1, line_length)),
    )
    horizontal = cv2.dilate(
        horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 5)), iterations=1
    )
    vertical = cv2.dilate(
        vertical, cv2.getStructuringElement(cv2.MORPH_RECT, (5, 3)), iterations=1
    )
    grid_mask = cv2.bitwise_or(horizontal, vertical)

    repaired = cv2.inpaint(gray, grid_mask, 4, cv2.INPAINT_TELEA)
    background = cv2.GaussianBlur(repaired, (0, 0), 7.0)
    response = cv2.subtract(repaired, background)

    valid_response = response[grid_mask == 0]
    if valid_response.size < 100:
        valid_response = response.reshape(-1)

    response_median = float(np.median(valid_response))
    response_mad = float(np.median(np.abs(valid_response - response_median))) * 1.4826 + 1.0
    response_threshold = max(
        10.0,
        response_median + 3.5 * response_mad,
        float(np.percentile(valid_response, 88)),
    )

    _, object_mask = cv2.threshold(
        response, int(round(response_threshold)), 255, cv2.THRESH_BINARY
    )
    object_mask[grid_mask > 0] = 0
    object_mask = cv2.morphologyEx(object_mask, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
    object_mask = cv2.morphologyEx(
        object_mask, cv2.MORPH_CLOSE,
        cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)),
    )

    component_count, labels, stats, centroids = cv2.connectedComponentsWithStats(
        object_mask, connectivity=8
    )

    min_area = max(14, int(round(h * w * 0.000075)))
    max_area = max(450, int(round(h * w * 0.0030)))
    valid_background = repaired[grid_mask == 0]
    background_median = (
        float(np.median(valid_background))
        if valid_background.size else float(np.median(repaired))
    )

    raw_detections = []
    for label in range(1, component_count):
        area = int(stats[label, cv2.CC_STAT_AREA])
        box_w = int(stats[label, cv2.CC_STAT_WIDTH])
        box_h = int(stats[label, cv2.CC_STAT_HEIGHT])
        if area < min_area or area > max_area:
            continue

        aspect = max(box_w, box_h) / max(1.0, float(min(box_w, box_h)))
        fill_ratio = area / max(1.0, float(box_w * box_h))
        if aspect > 3.2 or fill_ratio < 0.22:
            continue

        component = labels == label
        component_values = gray[component]
        if component_values.size == 0:
            continue

        p75 = float(np.percentile(component_values, 75))
        required_brightness = max(65.0, background_median + 40.0)
        if p75 < required_brightness:
            continue

        component_u8 = np.zeros_like(object_mask)
        component_u8[component] = 255
        contours, _ = cv2.findContours(component_u8, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if not contours:
            continue
        contour = max(contours, key=cv2.contourArea)
        contour_area = float(cv2.contourArea(contour))
        perimeter = float(cv2.arcLength(contour, True))
        circularity = 4.0 * np.pi * contour_area / (perimeter * perimeter + 1e-6)
        if circularity < 0.12:
            continue

        cx, cy = centroids[label]
        radius = max(3.0, 0.5 * max(box_w, box_h))
        confidence = min(1.0, max(0.0, (p75 - required_brightness + 20.0) / 140.0))
        raw_detections.append(
            [float(cx), float(cy), float(radius), float(confidence), float(area)]
        )

    raw_detections.sort(key=lambda item: item[3], reverse=True)
    merged = []
    for cx, cy, radius, confidence, area in raw_detections:
        match_index = None
        for index, existing in enumerate(merged):
            ex, ey, er, ec, ea = existing
            distance = float(np.hypot(cx - ex, cy - ey))
            merge_limit = max(4.0, min(7.0, 0.58 * (radius + er)))
            if distance < merge_limit:
                match_index = index
                break
        if match_index is None:
            merged.append([cx, cy, radius, confidence, area])
        else:
            ex, ey, er, ec, ea = merged[match_index]
            total_area = max(1.0, ea + area)
            merged[match_index] = [
                (ex * ea + cx * area) / total_area,
                (ey * ea + cy * area) / total_area,
                max(er, radius, 0.5 * np.hypot(cx - ex, cy - ey) + min(er, radius)),
                max(ec, confidence),
                total_area,
            ]

    return [
        (int(round(cx)), int(round(cy)), float(radius), float(confidence))
        for cx, cy, radius, confidence, _ in merged
    ]


# =========================
# NIH3T3 scale-adaptive whole-cell detector (v26-1)
# =========================

def _sa_robust_med_mad(v):
    v = np.asarray(v, np.float32).ravel()
    med = float(np.median(v)); mad = float(np.median(np.abs(v - med))) * 1.4826
    return med, max(mad, 1e-3)

_SPLIT_DEBUG = None      # set to a list to record split decisions (diagnostics)


_DT_DEBUG = None


def _split_touching_cells(comp, resp_sub, r0, area, a0, aspect, up=3):
    """Distance-transform separation of touching cells (manuscript Sec. 2.8).

    The component mask is upsampled (cells are only 3-4 px in radius), the
    Euclidean distance transform is smoothed (Gaussian, sigma = 1 px of the
    original image) and its 3x3 local maxima above 0.5 r0 (>= 0.9 r0 apart)
    are candidate centres.  Two candidates are kept apart only when the
    distance map has a narrow neck between them (min along the joining
    segment <= 0.80 of the smaller peak) AND the image response dips between
    them (<= 0.88 of the ends); for objects >= 1.6 a0 a deep neck (<= 0.60)
    alone is enough.  Returns centres in component
    coordinates (one entry = not split).
    """
    hh, ww = comp.shape
    big = cv2.resize(comp.astype(np.uint8), (ww * up, hh * up), interpolation=cv2.INTER_NEAREST)
    big = np.pad(big, up, constant_values=0)
    dt = cv2.distanceTransform(big, cv2.DIST_L2, 5).astype(np.float32) / up
    dts = cv2.GaussianBlur(dt, (0, 0), 1.0 * up)
    dil = cv2.dilate(dts, cv2.getStructuringElement(cv2.MORPH_RECT, (2 * up + 1, 2 * up + 1)))
    ys, xs = np.nonzero((dts >= dil - 1e-6) & (dts >= 0.5 * r0) & (big > 0))
    if len(xs) == 0:
        return None
    order = np.argsort(-dts[ys, xs])
    peaks = []
    for j in order:
        px, py = xs[j], ys[j]
        if all((px - qx) ** 2 + (py - qy) ** 2 >= (0.9 * r0 * up) ** 2 for qx, qy, _ in peaks):
            peaks.append((px, py, float(dts[py, px])))
    resp_big = cv2.resize(resp_sub.astype(np.float32), (ww * up, hh * up), interpolation=cv2.INTER_LINEAR)
    resp_big = np.pad(resp_big, up, constant_values=float(resp_sub.min()))
    shape_evidence = aspect >= 1.3 or area >= 1.25 * a0

    def separated(p, q):
        n = max(4, int(np.hypot(p[0] - q[0], p[1] - q[1])))
        t = np.linspace(0.0, 1.0, n)
        xs_ = np.clip(np.round(p[0] + (q[0] - p[0]) * t).astype(int), 0, dts.shape[1] - 1)
        ys_ = np.clip(np.round(p[1] + (q[1] - p[1]) * t).astype(int), 0, dts.shape[0] - 1)
        neck = float(dts[ys_, xs_][1:-1].min()) if n > 2 else min(p[2], q[2])
        dt_neck = neck <= 0.80 * min(p[2], q[2])
        prof = resp_big[ys_, xs_]
        ends = min(float(prof[:max(1, n // 4)].max()), float(prof[-max(1, n // 4):].max()))
        dip = ends > 0 and float(prof[n // 4: n - n // 4 + 1].min()) <= 0.88 * ends
        # both cues (two bodies AND two bright centres); a deep neck alone is
        # enough only for clearly oversized objects
        if isinstance(_DT_DEBUG, list):
            _DT_DEBUG.append({"neck_ratio": neck / max(1e-6, min(p[2], q[2])), "dip_ok": bool(dip), "neck_ok": bool(dt_neck), "area_ratio": float(area / a0)})
        return (dt_neck and dip) or (dt_neck and area >= 1.6 * a0 and neck <= 0.6 * min(p[2], q[2]))

    if isinstance(_DT_DEBUG, list):
        _DT_DEBUG.append({"n_peaks": len(peaks), "area_ratio": float(area / a0)})
    kept = [peaks[0]]
    for p in peaks[1:]:
        if all(separated(p, q) for q in kept):
            kept.append(p)
    return [((px - up) / up + 0.5 * (1.0 - 1.0 / up), (py - up) / up + 0.5 * (1.0 - 1.0 / up)) for px, py, _ in kept]


HIRES_SPLIT_MIN_FACTOR = 1.3   # use the original-resolution capture when it is >= 1.3x larger


def _hires_split(hires, fh, x, y, ww, hh, comp, r0, a0, thr, aspect):
    """Distance-transform separation (manuscript Sec. 2.8) measured on the
    ORIGINAL-resolution capture.  At the 1600-px analysis width a cell is only
    ~7 px across, too small for a neck between two touching cells to appear in
    the mask; at full resolution it does.  `comp` is the object mask at
    analysis resolution, (x, y) its corner; returns centres in analysis
    coordinates (one entry = one cell) or None."""
    if hires is None or fh < HIRES_SPLIT_MIN_FACTOR:
        return None
    H_, W_ = hires.shape[:2]
    pad = max(2, int(round(1.5 * r0)))
    lx0, ly0 = x - pad, y - pad
    X0, Y0 = max(0, int(np.floor(lx0 * fh))), max(0, int(np.floor(ly0 * fh)))
    X1, Y1 = min(W_, int(np.ceil((x + ww + pad) * fh))), min(H_, int(np.ceil((y + hh + pad) * fh)))
    if X1 - X0 < 8 or Y1 - Y0 < 8:
        return None
    # wider window: grid-line removal (opening with line elements longer than
    # a cell) and the local background level
    bp = int(round(5 * r0 * fh))
    BX0, BY0, BX1, BY1 = max(0, X0 - bp), max(0, Y0 - bp), min(W_, X1 + bp), min(H_, Y1 + bp)
    Wd = cv2.GaussianBlur(hires[BY0:BY1, BX0:BX1].astype(np.float32), (0, 0), max(0.6, 0.35 * fh))
    Ll = max(9, int(round(5 * r0 * fh)) | 1)
    lines = np.maximum(cv2.morphologyEx(Wd, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (Ll, 1))),
                       cv2.morphologyEx(Wd, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, Ll))))
    Wc = Wd - lines
    bg = float(np.median(Wc))
    R = Wc[Y0 - BY0:Y1 - BY0, X0 - BX0:X1 - BX0] - bg
    # region allowed: the low-res object, dilated by one pixel, mapped up
    reg = np.zeros((hh + 2 * pad, ww + 2 * pad), np.uint8)
    reg[pad:pad + hh, pad:pad + ww] = comp.astype(np.uint8)
    reg = cv2.dilate(reg, np.ones((3, 3), np.uint8))
    full = np.zeros((int(round((hh + 2 * pad) * fh)) + 2, int(round((ww + 2 * pad) * fh)) + 2), np.uint8)
    up_reg = cv2.resize(reg, (full.shape[1], full.shape[0]), interpolation=cv2.INTER_NEAREST)
    ox, oy = X0 - int(np.floor(lx0 * fh)), Y0 - int(np.floor(ly0 * fh))
    region = up_reg[oy:oy + (Y1 - Y0), ox:ox + (X1 - X0)]
    if region.shape != R.shape:
        region = cv2.resize(region, (R.shape[1], R.shape[0]), interpolation=cv2.INTER_NEAREST)
    region = region > 0
    if not region.any():
        return None
    peak = float(R[region].max())
    if peak <= 0:
        return None
    T = max(0.5 * thr, 0.30 * peak)
    fg = ((R > T) & region).astype(np.uint8)
    fg = cv2.morphologyEx(fg, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)))
    n, lab, st, cen = cv2.connectedComponentsWithStats(fg, 8)
    a0h, r0h = a0 * fh * fh, r0 * fh
    parts = [k for k in range(1, n) if st[k, 4] >= 0.30 * a0h]
    if not parts:
        return None
    if len(parts) >= 2:
        # the full-resolution image shows a gap between the bodies
        return [((X0 + cen[k][0]) / fh, (Y0 + cen[k][1]) / fh) for k in parts[:3]]
    k = parts[0]
    bx, by, bw, bh_, ba = st[k]
    sub = lab[by:by + bh_, bx:bx + bw] == k
    cs = _split_touching_cells(sub, R[by:by + bh_, bx:bx + bw], r0h, float(ba), a0h,
                               max(bw, bh_) / max(1.0, min(bw, bh_)), up=2)
    if not cs:
        return None
    return [((X0 + bx + px) / fh, (Y0 + by + py) / fh) for px, py in cs[:3]]


def _is_ring_like(resp, x, y, ww, hh, comp):
    """Hollow outline (bubble / out-of-focus ghost): the object's centre is much
    dimmer than its brightest part."""
    sub = resp[y:y + hh, x:x + ww]
    vals = sub[comp]
    if vals.size < 6:
        return False
    cy_, cx_ = hh / 2.0, ww / 2.0
    yy, xx = np.mgrid[0:hh, 0:ww]
    centre = (np.hypot(yy + 0.5 - cy_, xx + 0.5 - cx_) <= max(1.0, 0.22 * min(ww, hh)))
    cv_ = sub[centre]
    return cv_.size > 0 and float(np.mean(cv_)) < 0.45 * float(np.percentile(vals, 90))


def _major_axis_split(resp, x, y, ww, hh, r0, threshold=1.82, labels=None, own=None):
    """Elongation rule learned from user-labelled objects: a single object
    whose intensity-weighted major axis is >= `threshold` cell diameters
    holds two overlapping cells.  Measured in a disc around the object (not
    only inside its mask, which cuts the faint ends off).  Returns
    (two centres in image coordinates or None, axis length)."""
    H, W = resp.shape[:2]
    cx, cy = x + ww / 2.0, y + hh / 2.0
    rad = 0.5 * max(ww, hh) + 2.0
    x0, x1 = max(0, int(cx - rad - 2)), min(W, int(cx + rad + 3))
    y0, y1 = max(0, int(cy - rad - 2)), min(H, int(cy + rad + 3))
    P = cv2.GaussianBlur(resp[y0:y1, x0:x1].astype(np.float32), (0, 0), 0.7)
    yy, xx = np.mgrid[y0:y1, x0:x1]
    inside = np.hypot(xx - cx, yy - cy) <= rad
    if labels is not None:
        L_ = labels[y0:y1, x0:x1]
        inside &= ~((L_ > 0) & (L_ != own))          # ignore neighbouring objects
    w = np.clip(P, 0, None) * inside
    if w.max() <= 0:
        return None, 0.0
    w = np.where(w > 0.35 * w.max(), w, 0)
    sel = w > 0
    if sel.sum() < 5:
        return None, 0.0
    pts = np.c_[xx[sel], yy[sel]].astype(np.float64); wv = w[sel]
    c = (pts * wv[:, None]).sum(0) / wv.sum()
    d = pts - c
    cov = (d * wv[:, None]).T @ d / wv.sum()
    ev, evec = np.linalg.eigh(cov)
    length = 4.0 * float(np.sqrt(max(ev[1], 0.0)))
    if length < threshold * 2.0 * r0:
        return None, length
    ax = evec[:, 1]
    off = 0.25 * length
    return [(float(c[0] + off * ax[0]), float(c[1] + off * ax[1])),
            (float(c[0] - off * ax[0]), float(c[1] - off * ax[1]))], length


def _nih3t3_scale_adaptive_detect(roi_gray, core_bounds=None, return_info=False, hires=None):
    """Scale-adaptive whole-cell detector.

    1) remove long grid lines by grey-level opening, 2) local background
    subtraction, 3) robust (median + k*MAD) threshold, 4) estimate the typical
    single-cell area from compact isolated objects in THIS image, 5) accept /
    split objects relative to that area.  No absolute pixel-size constants.
    """
    gray = np.asarray(roi_gray, np.float32)
    h, w = gray.shape[:2]
    if h < 60 or w < 60:
        return ([], {}) if return_info else []
    smooth = cv2.GaussianBlur(gray, (3, 3), 0)
    # short (5% of ROI) 1-px-thick elements tolerate the small residual tilt of
    # grid lines that remains after deskewing, yet are much longer than a cell
    L = max(21, int(round(min(h, w) * 0.05)))
    hl = cv2.morphologyEx(smooth, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (L, 1)))
    vl = cv2.morphologyEx(smooth, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, L)))
    line_est = np.maximum(hl, vl)
    clean = smooth - line_est
    # where the grid itself is bright (used to demand stronger evidence there)
    line_resp = line_est - cv2.GaussianBlur(smooth, (0, 0), 15.0)
    lmed, lmad = _sa_robust_med_mad(line_resp)
    line_mask = cv2.dilate((line_resp > lmed + 4 * lmad).astype(np.uint8), np.ones((5, 5), np.uint8))

    def segment(sigma_bg, k):
        bg = cv2.GaussianBlur(clean, (0, 0), sigma_bg)
        resp = clean - bg
        med, mad = _sa_robust_med_mad(resp)
        thr = max(med + k * mad, med + 10.0)
        mask = (resp > thr).astype(np.uint8)
        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
        return resp, mask, thr

    # pass 1 with a generic background scale -> estimate cell size
    resp, mask, thr = segment(6.0, 5.0)
    n, lab, st, cen = cv2.connectedComponentsWithStats(mask, 8)
    areas = st[1:, cv2.CC_STAT_AREA].astype(np.float32)
    bw = st[1:, cv2.CC_STAT_WIDTH]; bh = st[1:, cv2.CC_STAT_HEIGHT]
    fill = areas / np.maximum(1, bw * bh)
    asp = np.maximum(bw, bh) / np.maximum(1, np.minimum(bw, bh))
    compact = (areas >= 6) & (fill >= 0.45) & (asp <= 1.8)
    if np.count_nonzero(compact) >= 8:
        a0 = float(np.median(areas[compact]))
    elif areas.size:
        a0 = float(np.median(areas[areas >= 6])) if np.any(areas >= 6) else 20.0
    else:
        return ([], {'a0': None}) if return_info else []
    r0 = math.sqrt(a0 / math.pi)
    # pass 2: background scale tied to the cell size
    resp, mask, thr = segment(max(4.0, 3.0 * r0), 5.0)
    n, lab, st, cen = cv2.connectedComponentsWithStats(mask, 8)

    smooth_resp = cv2.GaussianBlur(resp, (0, 0), max(0.8, 0.45 * r0))
    min_area = max(4.0, 0.35 * a0)
    single_max = 1.9 * a0
    peak_dist = max(2.5, 1.1 * r0)
    dets = []
    if core_bounds is None:
        cx0, cy0, cx1, cy1 = 0, 0, w, h
    else:
        cx0, cy0, cx1, cy1 = core_bounds
    for i in range(1, n):
        x, y, ww, hh, area = st[i]
        if area < min_area:
            continue
        aspect = max(ww, hh) / max(1.0, min(ww, hh))
        fill_r = area / max(1.0, ww * hh)
        if area <= single_max:
            if aspect > 4.0 or fill_r < 0.30 or min(ww, hh) < max(2.0, 0.8 * r0):
                continue
            comp = lab[y:y+hh, x:x+ww] == i
            peak = float(np.max(resp[y:y+hh, x:x+ww][comp]))
            if peak < thr + 6.0:
                continue
            on_line = float(np.mean(line_mask[y:y+hh, x:x+ww][comp]))
            if on_line > 0.6 and (area < 0.7 * a0 or min(ww, hh) < 1.6 * r0 or peak < thr + 40.0):
                continue  # grid junction residue
            if on_line > 0.4 and (min(ww, hh) < 1.3 * r0 or peak < thr + 25.0 or aspect > 1.8 or area < 0.45 * a0):
                continue
            if (aspect >= 1.3 or area >= 1.25 * a0) and on_line <= 0.25 and fill_r >= 0.45 \
                    and aspect <= 2.6:
                # possibly two touching cells merged into one object
                hi = None if hires is None else _hires_split(hires[0], hires[1], x, y, ww, hh, comp, r0, a0, thr, aspect)
                if hi is not None:
                    centres = [(px - x, py - y) for px, py in hi]
                    split_via = "hires"
                else:
                    centres = _split_touching_cells(comp, resp[y:y+hh, x:x+ww], r0, area, a0, aspect)
                    split_via = "dt"
                axis_centres, axis_len = None, 0.0
                if (centres is None or len(centres) < 2) and on_line <= 0.10 \
                        and not _is_ring_like(resp, x, y, ww, hh, comp):
                    axis_centres, axis_len = _major_axis_split(resp, x, y, ww, hh, r0, labels=lab, own=i)
                    if axis_centres is not None:
                        centres = [(px - x, py - y) for px, py in axis_centres]
                        split_via = "axis"
                if isinstance(_SPLIT_DEBUG, list):
                    _SPLIT_DEBUG.append({"x": int(x), "y": int(y), "w": int(ww), "h": int(hh),
                                         "cx": float(cen[i, 0]), "cy": float(cen[i, 1]),
                                         "n": len(centres) if centres else 1, "via": split_via,
                                         "axis_len": float(axis_len),
                                         "area_ratio": float(area / a0), "aspect": float(aspect),
                                         "pts": [(float(x + px), float(y + py)) for px, py in (centres or [])[:3]]})
                if centres is not None and len(centres) >= 2:
                    for px, py in centres[:3]:
                        dets.append((float(x + px), float(y + py), float(r0), min(1.0, peak / 150.0), 'split'))
                    continue
            radius = max(0.8 * r0, 0.5 * max(ww, hh))
            dets.append((float(cen[i, 0]), float(cen[i, 1]), float(radius), min(1.0, peak / 150.0), 'single'))
            continue
        if area > 25 * a0:
            continue  # bubble / large artefact
        # clump: local maxima of the smoothed response inside the component
        comp = (lab[y:y+hh, x:x+ww] == i)
        if (float(np.mean(line_mask[y:y+hh, x:x+ww][comp])) > 0.4 and min(ww, hh) < 1.3 * r0) or \
                (aspect > 3.0 and min(ww, hh) < 2.2 * r0):
            continue  # thin streak (grid-line residual), not a clump of cells
        if fill_r < 0.25 or float(np.max(resp[y:y+hh, x:x+ww][comp])) < thr + 25.0:
            continue  # hollow faint outline (out-of-focus ghost / bubble)
        sub = smooth_resp[y:y+hh, x:x+ww].copy()
        sub[~comp] = -1e9
        k = 2 * int(round(peak_dist)) + 1
        dil = cv2.dilate(sub, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k)))
        pk = (sub >= dil - 1e-6) & comp & (sub > thr)
        ys, xs = np.nonzero(pk)
        order = np.argsort(-sub[ys, xs])
        kept = []
        for j in order:
            px, py = xs[j], ys[j]
            if all((px - qx) ** 2 + (py - qy) ** 2 >= peak_dist ** 2 for qx, qy in kept):
                kept.append((px, py))
        n_area = int(round(area / a0))
        # add distance-transform centres (narrow necks) the response peaks missed
        on_line_c = float(np.mean(line_mask[y:y+hh, x:x+ww][comp]))
        n_peaks_resp = len(kept)
        if len(kept) < max(2, n_area) and on_line_c <= 0.25 and fill_r >= 0.45 and hires is not None:
            hi = _hires_split(hires[0], hires[1], x, y, ww, hh, comp, r0, a0, thr, aspect)
            if hi is not None and len(hi) > len(kept):
                kept = [(px - x, py - y) for px, py in hi]
        if len(kept) < max(2, n_area) and on_line_c <= 0.25 and fill_r >= 0.45:
            centres = _split_touching_cells(comp, resp[y:y+hh, x:x+ww], r0, area, a0, aspect)
            for px, py in (centres or []):
                if all((px - qx) ** 2 + (py - qy) ** 2 >= peak_dist ** 2 for qx, qy in kept):
                    kept.append((px, py))
        n_cells = max(1, min(len(kept), max(n_area, 1) + 1)) if kept else max(1, n_area)
        if isinstance(_SPLIT_DEBUG, list):
            _SPLIT_DEBUG.append({"x": int(x), "y": int(y), "w": int(ww), "h": int(hh),
                                 "cx": float(cen[i, 0]), "cy": float(cen[i, 1]),
                                 "n": int(min(len(kept), n_cells)) if kept else 1, "axis_len": -1.0,
                                 "area_ratio": float(area / a0), "aspect": float(aspect), "clump": True, "n_peaks_resp": n_peaks_resp,
                                 "pts": [(float(x + px), float(y + py)) for px, py in kept[:n_cells]]})
        if not kept:
            dets.append((float(cen[i, 0]), float(cen[i, 1]), float(r0), 0.5, 'clump'))
            continue
        kept = kept[:n_cells]
        for px, py in kept:
            dets.append((float(x + px), float(y + py), float(r0), 0.6, 'clump'))
    # final check: the object must stand out from the grid-free background over
    # a disc of about half a cell radius (removes faint ghosts / grid residue)
    verified = []
    yy_all, xx_all = np.mgrid[-4:5, -4:5]
    for d in dets:
        cx_i, cy_i = int(round(d[0])), int(round(d[1]))
        rr = max(1.5, 0.5 * r0)
        disc = (xx_all ** 2 + yy_all ** 2) <= rr * rr
        ys_d = np.clip(cy_i + yy_all[disc], 0, h - 1); xs_d = np.clip(cx_i + xx_all[disc], 0, w - 1)
        if float(np.mean(resp[ys_d, xs_d])) >= 0.6 * thr:
            verified.append(d)
    # remove duplicates (one object reported twice, e.g. large swollen cells)
    verified.sort(key=lambda d: -d[2])
    dets = []
    for d in verified:
        if all((d[0] - e[0]) ** 2 + (d[1] - e[1]) ** 2 >= (0.9 * max(d[2], e[2])) ** 2 for e in dets):
            dets.append(d)
    info = {'a0': a0, 'r0': r0, 'thr': thr}
    out = [(int(round(d[0])), int(round(d[1])), d[2], d[3]) for d in dets]
    return (out, info) if return_info else out


def _core_rect(shape, core_bounds=None):
    h, w = shape[:2]
    if core_bounds is None:
        return 0, 0, w, h
    x0, y0, x1, y1 = [int(round(v)) for v in core_bounds]
    x0 = max(0, min(x0, w - 1)); y0 = max(0, min(y0, h - 1))
    x1 = max(x0 + 1, min(x1, w)); y1 = max(y0 + 1, min(y1, h))
    return x0, y0, x1, y1


def _center_inside_core(det, core_bounds, shape):
    x0, y0, x1, y1 = _core_rect(shape, core_bounds)
    cx, cy = float(det[0]), float(det[1])
    return x0 <= cx < x1 and y0 <= cy < y1


def _filter_to_core(detections, core_bounds, shape):
    if core_bounds is None:
        return list(detections)
    return [d for d in detections if _center_inside_core(d, core_bounds, shape)]


def _nearest_detection_distance(detections, x, y):
    if not detections:
        return float('inf')
    return min(math.hypot(float(x) - float(d[0]), float(y) - float(d[1])) for d in detections)


def _append_dense_if_new(detections, x, y, radius, source, score=1.0, min_dist=5.0):
    if _nearest_detection_distance(detections, x, y) < float(min_dist):
        return False
    detections.append((float(x), float(y), float(radius), str(source), float(score)))
    return True


def _adaptive_candidate_evidence(gray, x, y, radius, strict=False):
    """Cheap local evidence gate for unique recovery candidates.

    Recovery methods are intentionally allowed to be more permissive than the
    strict base detector, but a candidate still needs local texture/contrast so
    bare grid intersections and flat background are not added as cells.
    """
    h, w = gray.shape[:2]
    r = max(3, int(round(float(radius))))
    pad = max(5, int(round(r * 1.8)))
    x0, x1 = max(0, int(round(x)) - pad), min(w, int(round(x)) + pad + 1)
    y0, y1 = max(0, int(round(y)) - pad), min(h, int(round(y)) + pad + 1)
    patch = gray[y0:y1, x0:x1]
    if patch.size < 25:
        return False
    std = float(np.std(patch))
    edge_fraction = float(np.mean(cv2.Canny(patch, 35, 95) > 0))
    center = patch[
        max(0, patch.shape[0]//2-r//2):min(patch.shape[0], patch.shape[0]//2+r//2+1),
        max(0, patch.shape[1]//2-r//2):min(patch.shape[1], patch.shape[1]//2+r//2+1),
    ]
    contrast = abs(float(np.median(center)) - float(np.median(patch))) if center.size else 0.0
    if strict:
        return std >= 12.0 and edge_fraction >= 0.025 and contrast >= 3.0
    return (std >= 9.0 and edge_fraction >= 0.018) or (std >= 7.0 and contrast >= 5.0)


def _nih3t3_density_features(roi_gray, core_bounds, strict_dets, calibrated_dets):
    """Estimate crowding without trusting a single detector's count."""
    gray = np.asarray(roi_gray, dtype=np.uint8)
    x0, y0, x1, y1 = _core_rect(gray.shape, core_bounds)
    core = gray[y0:y1, x0:x1]
    area = float(max(1, core.size))

    strict_core = _filter_to_core(strict_dets, core_bounds, gray.shape)
    calibrated_core = _filter_to_core(calibrated_dets, core_bounds, gray.shape)
    provisional_count = max(len(strict_core), len(calibrated_core))
    equivalent_count = provisional_count * ADAPTIVE_EQ_AREA / area

    # Circle occupancy is less sensitive to count fragmentation than raw count.
    occ_strict = sum(math.pi * max(1.0, float(d[2])) ** 2 for d in strict_core) / area
    occ_cal = sum(math.pi * max(1.0, float(d[2])) ** 2 for d in calibrated_core) / area
    occupancy = float(max(occ_strict, occ_cal))

    # Independent structural crowding/clump signal from a grid-removed response.
    smooth = cv2.GaussianBlur(core, (3, 3), 0)
    line_len = max(25, int(round(min(core.shape[:2]) * 0.14)))
    p84 = max(60, int(np.percentile(smooth, 84)))
    _, seed = cv2.threshold(smooth, p84, 255, cv2.THRESH_BINARY)
    hline = cv2.morphologyEx(seed, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (line_len, 1)))
    vline = cv2.morphologyEx(seed, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, line_len)))
    grid = cv2.bitwise_or(hline, vline)
    repaired = cv2.inpaint(core, cv2.dilate(grid, np.ones((3, 3), np.uint8)), 3, cv2.INPAINT_TELEA)
    background = cv2.GaussianBlur(repaired, (0, 0), 6.0)
    response = cv2.subtract(repaired, background)
    vals = response[grid == 0]
    if vals.size < 100:
        vals = response.reshape(-1)
    med = float(np.median(vals))
    mad = float(np.median(np.abs(vals - med))) * 1.4826 + 1.0
    resp_thr = max(8.0, med + 2.8 * mad, float(np.percentile(vals, 86)))
    structural = ((response >= resp_thr) & (grid == 0)).astype(np.uint8) * 255
    structural = cv2.morphologyEx(structural, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
    foreground_fraction = float(np.mean(structural > 0))

    nlab, _, stats, _ = cv2.connectedComponentsWithStats(structural, connectivity=8)
    comp_areas = np.asarray([
        stats[i, cv2.CC_STAT_AREA]
        for i in range(1, nlab)
        if stats[i, cv2.CC_STAT_AREA] >= 5
    ], dtype=np.float32)
    if comp_areas.size:
        # Expected individual-body area comes from detected radii when possible.
        radius_areas = [math.pi * max(2.0, float(d[2])) ** 2 for d in (strict_core or calibrated_core)]
        expected_area = float(np.median(radius_areas)) if radius_areas else float(np.median(comp_areas))
        large = comp_areas[comp_areas >= max(24.0, expected_area * 2.2)]
        clump_fraction = float(np.sum(large) / max(1.0, np.sum(comp_areas))) if large.size else 0.0
    else:
        clump_fraction = 0.0

    return {
        'equivalent_count': float(equivalent_count),
        'provisional_count': int(provisional_count),
        'strict_count': int(len(strict_core)),
        'calibrated_count': int(len(calibrated_core)),
        'occupancy': float(occupancy),
        'foreground_fraction': float(foreground_fraction),
        'clump_fraction': float(clump_fraction),
        'core_area': float(area),
    }


def _classify_nih3t3_density(features):
    eq = float(features['equivalent_count'])
    occ = float(features['occupancy'])
    fg = float(features['foreground_fraction'])
    clump = float(features['clump_fraction'])

    if clump >= ADAPTIVE_CLUMP_FRACTION and (eq >= 55.0 or occ >= 0.035):
        return 'high-clumped'
    if eq >= ADAPTIVE_HIGH_EQ_COUNT or occ >= ADAPTIVE_HIGH_OCCUPANCY or fg >= 0.085:
        return 'high'
    if eq <= ADAPTIVE_LOW_EQ_COUNT and occ < 0.040 and clump < 0.16:
        return 'low'
    return 'mid'


def _dense_scale(gray):
    return float(np.clip(min(gray.shape[:2]) / 430.0, 0.72, 1.55))


def _dense_tile_positions(length, tile_len, stride):
    vals, p = [], 0
    while True:
        if p + tile_len >= length:
            vals.append(max(0, length - tile_len))
            break
        vals.append(int(p)); p += stride
    return sorted(set(vals))


def _dense_tile_recovery(gray, detections):
    """v10-balanced overlapping-tile replay of the strict detector."""
    h, w = gray.shape[:2]
    tile_w = max(110, int(round(w * DENSE_TILE_FRACTION)))
    tile_h = max(110, int(round(h * DENSE_TILE_FRACTION)))
    stride_x = max(36, int(round(tile_w * DENSE_TILE_STRIDE_RATIO)))
    stride_y = max(36, int(round(tile_h * DENSE_TILE_STRIDE_RATIO)))
    xs = _dense_tile_positions(w, tile_w, stride_x)
    ys = _dense_tile_positions(h, tile_h, stride_y)
    scale = _dense_scale(gray)
    added = 0
    for y0 in ys:
        for x0 in xs:
            tile = gray[y0:y0 + tile_h, x0:x0 + tile_w]
            for d in _nih3t3_10x_strict_v6_detect(tile):
                cx, cy, radius = d[:3]
                radius = float(radius)
                margin = max(4, int(round(radius * 0.75)))
                if x0 > 0 and cx < margin: continue
                if y0 > 0 and cy < margin: continue
                if x0 + tile_w < w and cx > tile_w - margin: continue
                if y0 + tile_h < h and cy > tile_h - margin: continue
                gx, gy = float(cx + x0), float(cy + y0)
                score = float(d[3] if len(d) > 3 else 1.0)
                if _append_dense_if_new(detections, gx, gy, radius, 'tile', score, min_dist=5.0 * scale):
                    added += 1
    return added


def _dense_distance_transform_recovery(gray, detections):
    scale = _dense_scale(gray)
    blur = cv2.GaussianBlur(gray, (5, 5), 0)
    p = float(np.percentile(blur, DENSE_DT_BRIGHTNESS_PCTL))
    _, mask = cv2.threshold(blur, max(30, min(240, int(round(p)))), 255, cv2.THRESH_BINARY)
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, kernel, iterations=1)
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel, iterations=1)

    nlab, lab, stats, _ = cv2.connectedComponentsWithStats(mask, connectivity=8)
    min_area, max_area = 10.0 * scale * scale, 2600.0 * scale * scale
    added = 0
    for comp_id in range(1, nlab):
        x, y, ww, hh, area = stats[comp_id]
        if area < min_area or area > max_area:
            continue
        comp = (lab[y:y + hh, x:x + ww] == comp_id).astype(np.uint8) * 255
        dist = cv2.distanceTransform(comp, cv2.DIST_L2, 5)
        if dist.size == 0:
            continue
        db = cv2.GaussianBlur(dist, (0, 0), 1.0)
        dil = cv2.dilate(db, np.ones((3, 3), np.float32))
        peaks = ((db >= dil - 1e-6) & (db >= DENSE_DT_PEAK_MIN * scale)).astype(np.uint8)
        npeak, _, peak_stats, peak_cent = cv2.connectedComponentsWithStats(peaks, connectivity=8)
        for peak_id in range(1, npeak):
            if peak_stats[peak_id, cv2.CC_STAT_AREA] <= 0:
                continue
            cx_local, cy_local = peak_cent[peak_id]
            ix = int(np.clip(round(cx_local), 0, dist.shape[1] - 1))
            iy = int(np.clip(round(cy_local), 0, dist.shape[0] - 1))
            radius = float(np.clip(float(dist[iy, ix]) * 1.35, 2.7 * scale, 10.0 * scale))
            gx, gy = float(x + cx_local), float(y + cy_local)
            if not _adaptive_candidate_evidence(gray, gx, gy, radius, strict=False):
                continue
            if _append_dense_if_new(detections, gx, gy, radius, 'dt', 1.0, min_dist=4.5 * scale):
                added += 1
    return added


def _dense_contour_recovery(gray, detections):
    scale = _dense_scale(gray)
    blur = cv2.GaussianBlur(gray, (3, 3), 0)
    p = float(np.percentile(blur, 57))
    _, mask = cv2.threshold(blur, max(28, min(235, int(round(p)))), 255, cv2.THRESH_BINARY)
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)), iterations=1)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    added = 0
    for cnt in contours:
        area = float(cv2.contourArea(cnt))
        if area < 8.0 * scale * scale or area > 320.0 * scale * scale:
            continue
        peri = float(cv2.arcLength(cnt, True))
        if peri <= 0:
            continue
        circ = 4.0 * math.pi * area / (peri * peri)
        if circ < 0.35:
            continue
        (cx, cy), radius = cv2.minEnclosingCircle(cnt)
        if radius < 2.4 * scale or radius > 8.5 * scale:
            continue
        if not _adaptive_candidate_evidence(gray, cx, cy, radius, strict=False):
            continue
        if _append_dense_if_new(detections, cx, cy, radius, 'contour', 1.0, min_dist=4.5 * scale):
            added += 1
    return added


def _dense_hough(gray):
    scale = _dense_scale(gray)
    circles = cv2.HoughCircles(
        cv2.medianBlur(gray, 3), cv2.HOUGH_GRADIENT,
        dp=1.10, minDist=max(5.0, 7.0 * scale),
        param1=80, param2=13,
        minRadius=max(2, int(round(4 * scale))),
        maxRadius=max(4, int(round(10 * scale))),
    )
    if circles is None:
        return []
    return [(float(x), float(y), float(r)) for x, y, r in circles[0]]


def _dense_small_hough_recovery(gray, detections):
    scale = _dense_scale(gray)
    cap = min(DENSE_HOUGH_ADD_ABS, max(4, int(round(len(detections) * DENSE_HOUGH_ADD_FRAC))))
    candidates = []
    for x, y, radius in _dense_hough(gray):
        if _nearest_detection_distance(detections, x, y) < 5.2 * scale:
            continue
        if not _adaptive_candidate_evidence(gray, x, y, radius, strict=True):
            continue
        rr = max(4, int(round(radius)))
        x0, x1 = max(0, int(round(x - rr))), min(gray.shape[1], int(round(x + rr + 1)))
        y0, y1 = max(0, int(round(y - rr))), min(gray.shape[0], int(round(y + rr + 1)))
        patch = gray[y0:y1, x0:x1]
        if patch.size < 20 or float(np.std(patch)) < 14.0:
            continue
        edge = float(np.mean(cv2.Canny(patch, 40, 100) > 0))
        candidates.append((edge, x, y, radius))
    candidates.sort(reverse=True)
    added = 0
    for score, x, y, radius in candidates:
        if added >= cap:
            break
        if _append_dense_if_new(detections, x, y, radius, 'hough', score, min_dist=5.2 * scale):
            added += 1
    return added


def _dense_calibrated_consensus(gray, detections, calibrated_dets):
    """Use the newer calibrated detector only as a small high-density consensus rescue."""
    scale = _dense_scale(gray)
    cap = max(3, min(18, int(round(max(1, len(detections)) * 0.05))))
    added = 0
    for d in sorted(calibrated_dets, key=lambda z: float(z[3] if len(z) > 3 else 0.0), reverse=True):
        if added >= cap:
            break
        x, y, radius = float(d[0]), float(d[1]), float(d[2])
        if _nearest_detection_distance(detections, x, y) < 5.0 * scale:
            continue
        if not _adaptive_candidate_evidence(gray, x, y, radius, strict=True):
            continue
        score = float(d[3] if len(d) > 3 else 1.0)
        if _append_dense_if_new(detections, x, y, radius, 'calibrated', score, min_dist=5.0 * scale):
            added += 1
    return added


def _nih3t3_dense_balanced_detect(roi_gray, calibrated_dets=None):
    """Counting-only port of the v10-balanced dense recovery strategy."""
    gray = np.asarray(roi_gray, dtype=np.uint8)
    base = _nih3t3_10x_strict_v6_detect(gray)
    detections = [
        (float(d[0]), float(d[1]), float(d[2]), 'base', float(d[3] if len(d) > 3 else 1.0))
        for d in base
    ]
    stats = {'base': len(detections), 'tile': 0, 'dt': 0, 'contour': 0, 'hough': 0, 'calibrated': 0}
    stats['tile'] = _dense_tile_recovery(gray, detections)
    stats['dt'] = _dense_distance_transform_recovery(gray, detections)
    stats['contour'] = _dense_contour_recovery(gray, detections)
    if calibrated_dets:
        stats['calibrated'] = _dense_calibrated_consensus(gray, detections, calibrated_dets)
    stats['hough'] = _dense_small_hough_recovery(gray, detections)
    out = [(int(round(d[0])), int(round(d[1])), float(d[2]), float(d[4])) for d in detections]
    return out, stats


def _nih3t3_mid_density_detect(roi_gray, core_bounds, strict_dets, calibrated_dets):
    """Use v25-24 calibrated output and recover only a few strong strict-only cells."""
    gray = np.asarray(roi_gray, dtype=np.uint8)
    selected = [tuple(d) for d in calibrated_dets]
    scale = _dense_scale(gray)
    cap = max(2, min(10, int(round(max(1, len(selected)) * 0.06))))
    added = 0
    for d in sorted(strict_dets, key=lambda z: float(z[3] if len(z) > 3 else 0.0), reverse=True):
        if added >= cap:
            break
        x, y, radius = float(d[0]), float(d[1]), float(d[2])
        if _nearest_detection_distance(selected, x, y) < 5.0 * scale:
            continue
        if not _adaptive_candidate_evidence(gray, x, y, radius, strict=True):
            continue
        selected.append(tuple(d))
        added += 1
    return selected, {'strict_rescue': added}


def _nih3t3_adaptive_detect(roi_gray, core_bounds=None):
    """Per-Q detector router returning (detections, diagnostics)."""
    gray = np.asarray(roi_gray, dtype=np.uint8)
    strict = _nih3t3_10x_strict_v6_detect(gray)
    calibrated = _nih3t3_10x_calibrated_detect(gray, core_bounds)
    features = _nih3t3_density_features(gray, core_bounds, strict, calibrated)
    density = _classify_nih3t3_density(features)

    if density == 'low':
        selected = strict
        engine = 'v6 strict (low)'
        recovery_stats = {}
    elif density == 'mid':
        selected, recovery_stats = _nih3t3_mid_density_detect(
            gray, core_bounds, strict, calibrated
        )
        engine = 'v25-24 calibrated + strict consensus (mid)'
    else:
        selected, recovery_stats = _nih3t3_dense_balanced_detect(gray, calibrated)
        engine = 'v10 balanced dense recovery (high)'

    diagnostics = dict(features)
    diagnostics.update({
        'density': density,
        'engine': engine,
        'selected_count_pre_lrule': int(len(selected)),
        'recovery': recovery_stats,
    })
    return selected, diagnostics

# =========================
# Microalgae detector: whole-object segmentation + separate learned model
# =========================
def _microalgae_object_candidates(roi_gray):
    """Create one candidate for each bright microalgal body.

    Long hemocytometer grid structures are removed first. Connected components
    are then filtered by shape, area and local contrast so internal highlights
    are not counted as multiple cells.
    """
    if roi_gray is None or roi_gray.size == 0:
        return []

    gray = np.asarray(roi_gray, dtype=np.uint8)
    h, w = gray.shape[:2]
    if h < 40 or w < 40:
        return []

    smooth = cv2.GaussianBlur(gray, (3, 3), 0)
    line_threshold = max(70, int(np.percentile(smooth, 84)))
    _, bright_seed = cv2.threshold(smooth, line_threshold, 255, cv2.THRESH_BINARY)
    line_length = max(35, int(round(min(h, w) * 0.12)))

    horizontal = cv2.morphologyEx(
        bright_seed, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_length, 1)),
    )
    vertical = cv2.morphologyEx(
        bright_seed, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (1, line_length)),
    )
    horizontal = cv2.dilate(
        horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 5)), iterations=1
    )
    vertical = cv2.dilate(
        vertical, cv2.getStructuringElement(cv2.MORPH_RECT, (5, 3)), iterations=1
    )
    grid_mask = cv2.bitwise_or(horizontal, vertical)

    repaired = cv2.inpaint(gray, grid_mask, 4, cv2.INPAINT_TELEA)
    background = cv2.GaussianBlur(repaired, (0, 0), 7.0)
    response = cv2.subtract(repaired, background)

    valid_response = response[grid_mask == 0]
    if valid_response.size < 100:
        valid_response = response.reshape(-1)
    median = float(np.median(valid_response))
    robust_scale = float(np.median(np.abs(valid_response - median))) * 1.4826 + 1.0
    object_threshold = max(
        10.0,
        median + 3.5 * robust_scale,
        float(np.percentile(valid_response, 88)),
    )

    _, object_mask = cv2.threshold(
        response, int(round(object_threshold)), 255, cv2.THRESH_BINARY
    )
    object_mask[grid_mask > 0] = 0
    object_mask = cv2.morphologyEx(object_mask, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
    object_mask = cv2.morphologyEx(
        object_mask, cv2.MORPH_CLOSE,
        cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)),
    )

    count, labels, stats, centroids = cv2.connectedComponentsWithStats(
        object_mask, connectivity=8
    )
    min_area = max(14, int(round(h * w * 0.000075)))
    max_area = max(450, int(round(h * w * 0.0030)))
    background_median = (
        float(np.median(repaired[grid_mask == 0]))
        if np.any(grid_mask == 0)
        else float(np.median(repaired))
    )

    detections = []
    for label in range(1, count):
        area = int(stats[label, cv2.CC_STAT_AREA])
        x = int(stats[label, cv2.CC_STAT_LEFT])
        y = int(stats[label, cv2.CC_STAT_TOP])
        box_w = int(stats[label, cv2.CC_STAT_WIDTH])
        box_h = int(stats[label, cv2.CC_STAT_HEIGHT])
        if area < min_area or area > max_area:
            continue

        aspect = max(box_w, box_h) / max(1.0, float(min(box_w, box_h)))
        fill_ratio = area / max(1.0, float(box_w * box_h))
        if aspect > 3.4 or fill_ratio < 0.20:
            continue

        component = labels == label
        values = gray[component]
        if values.size == 0:
            continue
        p75 = float(np.percentile(values, 75))
        if p75 < max(60.0, background_median + 20.0):
            continue

        component_u8 = np.zeros_like(object_mask)
        component_u8[component] = 255
        contours, _ = cv2.findContours(
            component_u8, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
        )
        if not contours:
            continue
        contour = max(contours, key=cv2.contourArea)
        contour_area = float(cv2.contourArea(contour))
        perimeter = float(cv2.arcLength(contour, True))
        circularity = 4.0 * np.pi * contour_area / (perimeter * perimeter + 1e-6)
        if circularity < 0.10:
            continue

        cx, cy = centroids[label]
        radius = max(3.0, 0.5 * max(box_w, box_h))
        confidence = min(1.0, max(0.0, (p75 - background_median) / 120.0))
        detections.append((
            int(round(cx)), int(round(cy)), float(radius), float(confidence)
        ))

    return detections


def _microalgae_learned_detect(roi_gray, model):
    """Fuse whole-object candidates with the separately trained microalgae model.

    The segmentation supplies one object-level candidate per cell. The RTrees
    model trained from the 7.29 microalgae image set independently supports or
    rejects those candidates. Very high-confidence learned detections can also
    recover a faint object missed by connected-component segmentation.
    """
    if model is None or roi_gray is None or roi_gray.size == 0:
        return []

    object_candidates = _microalgae_object_candidates(roi_gray)
    learned_candidates = _reference_detect(roi_gray, model)
    if not object_candidates:
        return [item for item in learned_candidates if item[3] >= 0.95]
    if not learned_candidates:
        return []

    fused = []
    used_learned = set()

    # Keep each whole-object candidate when the learned model supports the same
    # location. This preserves one-count-per-object behavior.
    for ox, oy, radius, object_conf in object_candidates:
        best_index = None
        best_distance = float("inf")
        best_score = 0.0
        support_distance = max(8.0, radius * 1.8)
        for index, (lx, ly, lr, score) in enumerate(learned_candidates):
            distance = float(np.hypot(ox - lx, oy - ly))
            if distance <= support_distance and (
                score > best_score or (score == best_score and distance < best_distance)
            ):
                best_index = index
                best_distance = distance
                best_score = float(score)
        if best_index is not None and best_score >= MICROALGAE_MODEL_SCORE_THRESHOLD:
            used_learned.add(best_index)
            fused.append((ox, oy, radius, best_score))

    # Recover only exceptionally confident unmatched learned detections.
    for index, (lx, ly, lr, score) in enumerate(learned_candidates):
        if index in used_learned or score < 0.95:
            continue
        if any(np.hypot(lx - fx, ly - fy) < max(8.0, 1.5 * max(lr, fr))
               for fx, fy, fr, _ in fused):
            continue
        fused.append((int(lx), int(ly), float(lr), float(score)))

    # Final radius-aware de-duplication.
    fused.sort(key=lambda item: item[3], reverse=True)
    final = []
    for item in fused:
        x, y, radius, score = item
        if any(np.hypot(x - kx, y - ky) < max(7.0, 0.9 * max(radius, kr))
               for kx, ky, kr, _ in final):
            continue
        final.append(item)
    return final



VIABILITY_V6_CENTER = np.array([
    -0.0199626872, -0.0181667065, -0.0017959815, -0.0052173744, -0.0089980305,
    -0.3155486838, -0.1481797617, -0.1673689218, -0.1393527304, -0.0711163556,
    -0.6105400512, -0.2817275859, -0.3288124655, -0.2721384073, -0.1350437845,
     0.3265947247,  0.6490341851,  0.0310087284,  0.4476473560,
], dtype=np.float32)

VIABILITY_V6_SCALE = np.array([
    0.6550461834, 0.3339583086, 0.4322764837, 0.3043063549, 0.1615568825,
    0.6972195028, 0.3516554840, 0.4616796923, 0.3190776570, 0.1684854284,
    0.6428242641, 0.3574328335, 0.4917582213, 0.2832725362, 0.1676823448,
    0.3331003763, 0.4948028943, 0.0889344400, 0.1617114716,
], dtype=np.float32)

VIABILITY_V6_COEF = np.array([
    -0.3444931588, -0.2139917717, -0.3567034593, -0.7325864819, -0.3734375658,
    -0.2675096734, -0.2710410553, -0.1975392696, -0.9017122826, -0.4588343823,
    -0.0661242471, -0.2190255532,  0.0727607419, -1.1306587740, -0.3835881829,
    -0.2107216480, -0.3156163912, -0.3490842331, -1.3313160422,
], dtype=np.float32)
VIABILITY_V6_INTERCEPT = -1.8724554543


def _nih3t3_viability_features(bgr_img, cx, cy, radius, grid_mask=None):
    """Return 19 density-robust, cell-intrinsic Trypan-blue features.

    Regions (relative to the already detected cell radius):
      core : 0 .. 0.55 r
      cell : 0 .. 1.00 r
      rim  : 0.55 .. 1.05 r

    Unlike v5, no external 1.5-2.5r background annulus is required for the
    primary classifier.  That annulus is unreliable in crowded fields because
    it is often occupied by neighbouring cells. Hemocytometer grid pixels are
    excluded where possible.
    """
    if bgr_img is None or bgr_img.size == 0:
        return None

    h, w = bgr_img.shape[:2]
    rr = max(3.0, float(radius))
    pad = int(np.ceil(rr * 2.0))
    x0, x1 = max(0, int(cx - pad)), min(w, int(cx + pad + 1))
    y0, y1 = max(0, int(cy - pad)), min(h, int(cy + pad + 1))
    patch = bgr_img[y0:y1, x0:x1]
    if patch.size == 0 or patch.shape[0] < 5 or patch.shape[1] < 5:
        return None

    yy, xx = np.ogrid[y0:y1, x0:x1]
    dist = np.sqrt((xx - float(cx)) ** 2 + (yy - float(cy)) ** 2)

    blocked = np.zeros(patch.shape[:2], dtype=bool)
    if grid_mask is not None and grid_mask.size:
        local_grid = grid_mask[y0:y1, x0:x1]
        if local_grid.shape == patch.shape[:2]:
            blocked = cv2.dilate(
                (local_grid > 0).astype(np.uint8),
                np.ones((3, 3), np.uint8), iterations=1
            ) > 0

    masks = {
        "core": (dist <= rr * 0.55) & (~blocked),
        "cell": (dist <= rr * 1.00) & (~blocked),
        "rim":  (dist > rr * 0.55) & (dist <= rr * 1.05) & (~blocked),
    }

    # If a cell lies directly on a grid line, retry without the grid mask rather
    # than losing the cell from viability accounting.
    if min(np.count_nonzero(mask) for mask in masks.values()) < 5:
        masks = {
            "core": dist <= rr * 0.55,
            "cell": dist <= rr * 1.00,
            "rim":  (dist > rr * 0.55) & (dist <= rr * 1.05),
        }
    if min(np.count_nonzero(mask) for mask in masks.values()) < 5:
        return None

    patch_f = patch.astype(np.float32)
    med = {
        name: np.median(patch_f[mask], axis=0).astype(np.float32)
        for name, mask in masks.items()
    }
    hsv = cv2.cvtColor(patch, cv2.COLOR_BGR2HSV).astype(np.float32)
    core_sat = float(np.median(hsv[:, :, 1][masks["core"]])) / 255.0

    feats = []
    # 1-15: chromaticity in core / whole cell / rim. Log channel ratios and
    # bounded opponent-color terms are exposure tolerant and preserve the
    # biologically relevant blue-vs-warm staining distinction.
    for name in ("core", "cell", "rim"):
        b, g, r = [float(v) for v in med[name]]
        feats.extend([
            np.log((r + 2.0) / (b + 2.0)),
            np.log((r + 2.0) / (g + 2.0)),
            np.log((g + 2.0) / (b + 2.0)),
            (r - b) / (r + b + 4.0),
            (r - g) / (r + g + 4.0),
        ])

    bc, gc, rc = [float(v) for v in med["core"]]
    bcell, gcell, rcell = [float(v) for v in med["cell"]]
    br, gr, rrim = [float(v) for v in med["rim"]]

    # 16-19: radial color structure + core saturation. These distinguish a
    # genuinely dye-filled cell from a bright halo/rim without using neighbours.
    feats.extend([
        np.log((rc + 2.0) / (rcell + 2.0)),
        np.log((rc + 2.0) / (rrim + 2.0)),
        np.log((bc + 2.0) / (bcell + 2.0)),
        core_sat,
    ])

    features = np.asarray(feats, dtype=np.float32)
    if features.size != 19 or not np.all(np.isfinite(features)):
        return None
    return features


def _nih3t3_base_dead_probability(bgr_img, cx, cy, radius, grid_mask=None):
    """Cell-level dead probability before the Q-level prior adjustment."""
    features = _nih3t3_viability_features(
        bgr_img, cx, cy, radius, grid_mask=grid_mask
    )
    if features is None:
        # Binary output is required.  Use a conservative intrinsic-color
        # fallback: only clearly blue-dominant cells are called dead.
        h, w = bgr_img.shape[:2]
        rr = max(3, int(round(radius)))
        x0, x1 = max(0, int(cx - rr)), min(w, int(cx + rr + 1))
        y0, y1 = max(0, int(cy - rr)), min(h, int(cy + rr + 1))
        patch = bgr_img[y0:y1, x0:x1]
        if patch.size == 0:
            return 0.10
        b, g, r = [float(v) for v in np.median(patch.reshape(-1, 3), axis=0)]
        rb = (r + 2.0) / (b + 2.0)
        return 0.90 if rb < 0.62 else 0.10

    z = (features - VIABILITY_V6_CENTER) / np.maximum(VIABILITY_V6_SCALE, 1e-6)
    logit = float(VIABILITY_V6_INTERCEPT + np.dot(VIABILITY_V6_COEF, z))
    logit = float(np.clip(logit, -30.0, 30.0))
    return float(1.0 / (1.0 + np.exp(-logit)))


def _adaptive_viability_threshold(probabilities):
    """Choose a conservative binary threshold from the Q-level probability prior.

    The goal is specifically to prevent the failure seen in very dense fields:
    a live-dominant field must not become mostly DEAD merely because neighbouring
    cells contaminate local background.  Conversely, an overwhelmingly dead
    reference field should remain overwhelmingly dead.
    """
    if not probabilities:
        return 0.50
    med = float(np.median(np.asarray(probabilities, dtype=np.float32)))

    # Extremely dead-dominant: the user's hard-dead reference Qs all land well
    # above this prior.  Recover weakly stained dead cells without affecting the
    # live-dominant references.
    if med >= 0.80:
        return 0.05

    # Moderately dead-dominant / mixed: smoothly lower the threshold rather than
    # forcing the whole Q into one class.
    if med >= 0.55:
        frac = (med - 0.55) / 0.25
        return float(0.35 - 0.25 * np.clip(frac, 0.0, 1.0))

    # Strongly live-dominant: require clear Trypan-blue evidence for a DEAD call.
    # This is the key guard against false-dead calls in crowded healthy fields.
    if med <= 0.10:
        return 0.70

    # Intermediate mixtures: transition back toward a neutral 0.50 boundary.
    frac = (med - 0.10) / 0.45
    return float(0.70 - 0.20 * np.clip(frac, 0.0, 1.0))


def _classify_nih3t3_viability_batch(bgr_img, selected, grid_mask=None):
    """Classify already-detected cells as LIVE/DEAD without changing detection."""
    if not selected:
        return []
    probs = [
        _nih3t3_base_dead_probability(
            bgr_img, int(cx), int(cy), float(radius), grid_mask=grid_mask
        )
        for cx, cy, radius in selected
    ]
    threshold = _adaptive_viability_threshold(probs)
    return [
        (cx, cy, radius, "dead" if p >= threshold else "live", float(p))
        for (cx, cy, radius), p in zip(selected, probs)
    ]


def _classify_nih3t3_viability(bgr_img, cx, cy, radius, grid_mask=None):
    """Compatibility wrapper for callers that classify a single cell."""
    p = _nih3t3_base_dead_probability(
        bgr_img, cx, cy, radius, grid_mask=grid_mask
    )
    return ("dead" if p >= 0.50 else "live"), float(p)


def _nih3t3_color_information_is_sufficient(bgr_img):
    """Return True only if chromatic information is sufficient for Trypan-blue viability."""
    if bgr_img is None or bgr_img.size == 0:
        return False
    if len(bgr_img.shape) < 3 or bgr_img.shape[2] < 3:
        return False

    h, w = bgr_img.shape[:2]
    if max(h, w) > 800:
        scale = 800.0 / float(max(h, w))
        bgr_img = cv2.resize(
            bgr_img,
            (max(1, int(round(w * scale))), max(1, int(round(h * scale)))),
            interpolation=cv2.INTER_AREA,
        )

    img = bgr_img.astype(np.float32)
    b = img[:, :, 0]
    g = img[:, :, 1]
    r = img[:, :, 2]

    diff_rg = np.abs(r - g)
    diff_gb = np.abs(g - b)
    diff_rb = np.abs(r - b)
    mean_diff = float(np.mean((diff_rg + diff_gb + diff_rb) / 3.0))
    p95_diff = float(np.percentile(np.maximum.reduce([diff_rg, diff_gb, diff_rb]), 95))

    sat = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2HSV)[:, :, 1].astype(np.float32)
    median_sat = float(np.median(sat))
    p95_sat = float(np.percentile(sat, 95))

    if mean_diff < 2.0 and p95_diff < 8.0 and median_sat < 8.0 and p95_sat < 18.0:
        return False
    return True

# =========================
# NIH3T3 Trypan-blue LIVE/DEAD classifier v8 (microscope-independent)
# =========================
# Decision semantics (confirmed by the user on reference images):
#   LIVE : bright, refractile cell (white / yellow / bright orange core)
#   DEAD : dim cell, darker centre with a ring, or a dye-coloured (blue-shifted)
#          dim cell
# Colour and exposure differ between microscopes and cameras, so no absolute
# colour or brightness value is used.  Every feature is measured relative to
# the cell-free background of the same image (contrast as a fraction of the
# headroom above background, colour as a log-ratio to the background colour)
# and then relative to the population of cells in the same image (brightness
# / 75th percentile, colour as a robust z-score).  The same rule therefore
# applies to blue-cast, grey or yellow-cast images.  An optional
# per-microscope calibration (user-labelled cells) can refine the rule.

VIABILITY_PROFILE_FILENAME = "cell_viability_profile.json"
VIABILITY_FEATURE_NAMES = (
    "relative_brightness", "core_ring_ratio", "blue_shift_z",
    "green_shift_z", "absolute_contrast",
    "log_rb_core", "log_rb_cell", "log_rb_rim", "core_saturation",
    "hollowness", "body_green_red_z", "core_background_delta_e", "delta_e_image_z",
)
VIABILITY_PROFILE_VERSION = 12
# Decision threshold on the interior/background colour difference, set from
# 56 user-labelled ambiguous cells (3 microscopes): leave-one-out accuracy
# 87.5 % versus 58.9 % for the previous multi-cue rule.
VIABILITY_DELTA_E_THRESHOLD = 55.0
VIABILITY_BG_LIKENESS_COEF = (-2.6984, 1.9071, -6.6768, -0.6630)  # intercept, blue_shift_z, core_saturation, delta_e_image_z
VIABILITY_DELTA_E_Z_THRESHOLD = -2.05    # same cut in image-normalised units (robust z)


BRIGHTFIELD_FEATURE_NAMES = (
    "core_darkness", "rim_darkness", "blue_shift_z", "centre_minus_rim", "blue_shift",
)


def _viability_feature_names(polarity="bright"):
    return BRIGHTFIELD_FEATURE_NAMES if polarity == "dark" else VIABILITY_FEATURE_NAMES


def _viability_profile_path(polarity="bright"):
    base = _program_dir()
    name = VIABILITY_PROFILE_FILENAME
    if polarity == "dark":
        name = name.replace(".json", "_brightfield.json")
    return os.path.join(base, name)


USE_SAVED_VIABILITY_PROFILES = False   # fixed, validated rule; old training files are ignored


def _load_viability_profile(polarity="bright"):
    if not USE_SAVED_VIABILITY_PROFILES:
        return None
    path = _viability_profile_path(polarity)
    if not os.path.exists(path):
        return None
    try:
        import json
        with open(path, "r", encoding="utf-8") as handle:
            prof = json.load(handle)
        n = len(_viability_feature_names(polarity))
        if int(prof.get("version", 0)) != VIABILITY_PROFILE_VERSION:
            return None
        for key, size in (("mean", n), ("scale", n), ("coef", n + 1)):
            if len(prof.get(key, [])) != size:
                return None
        float(prof["intercept"])
        return prof
    except Exception:
        return None


def _save_viability_profile(profile):
    import json
    with open(_viability_profile_path(profile.get("polarity", "bright")), "w", encoding="utf-8") as handle:
        json.dump(profile, handle, indent=2)


def _delete_viability_profile(polarity=None):
    for pol in (("bright", "dark") if polarity is None else (polarity,)):
        path = _viability_profile_path(pol)
        if os.path.exists(path):
            os.remove(path)


def _viability_background_bgr(bgr_img, selected, grid_mask=None):
    """Median colour of cell-free, grid-free background pixels."""
    h, w = bgr_img.shape[:2]
    free = np.ones((h, w), np.uint8)
    for item in selected:
        cv2.circle(free, (int(item[0]), int(item[1])),
                   int(round(float(item[2]) * 2.0)) + 2, 0, -1)
    if grid_mask is not None and grid_mask.shape[:2] == (h, w):
        free[cv2.dilate((grid_mask > 0).astype(np.uint8),
                        np.ones((5, 5), np.uint8)) > 0] = 0
    pixels = bgr_img[free > 0]
    if pixels.shape[0] < 500:
        pixels = bgr_img.reshape(-1, 3)
    return np.median(pixels.astype(np.float32), axis=0)


def _bgr_to_lab(px):
    a = np.clip(np.asarray(px, np.float32).reshape(-1, 1, 3), 0, 255).astype(np.uint8)
    lab = cv2.cvtColor(a, cv2.COLOR_BGR2LAB).reshape(-1, 3).astype(np.float32)
    lab[:, 0] *= 100.0 / 255.0
    lab[:, 1:] -= 128.0
    return lab


def _lab_delta_e(core_px, bg_bgr):
    if core_px is None or len(core_px) == 0:
        return float("nan")
    c = _bgr_to_lab(core_px).mean(axis=0)
    b = _bgr_to_lab(np.asarray(bg_bgr, np.float32).reshape(1, 3))[0]
    return float(np.linalg.norm(c - b))


def _viability_raw_features(bgr_img, gray, bg_bgr, bg_gray, cx, cy, radius, grid=None):
    """Background-relative measurements of one cell (no absolute colour used)."""
    h, w = gray.shape[:2]
    r = max(1.5, float(radius))
    pad = int(np.ceil(1.4 * r)) + 2
    x0, x1 = max(0, int(cx) - pad), min(w, int(cx) + pad + 1)
    y0, y1 = max(0, int(cy) - pad), min(h, int(cy) + pad + 1)
    yy, xx = np.ogrid[y0:y1, x0:x1]
    patch_gray = gray[y0:y1, x0:x1]
    patch_bgr = bgr_img[y0:y1, x0:x1].astype(np.float32)
    # Re-centre on the cell's own brightness centroid: on 3-4 px cells a 1-2 px
    # offset of the detection centre puts the "core" on the cell edge and makes
    # a bright cell look like a dark-centred ring.
    dist = np.sqrt((xx - float(cx)) ** 2 + (yy - float(cy)) ** 2)
    wts = np.clip(patch_gray - float(bg_gray), 0, None) * (dist <= 1.1 * r)
    if wts.sum() > 1e-6:
        ncx = float((wts * xx).sum() / wts.sum())
        ncy = float((wts * yy).sum() / wts.sum())
        if np.hypot(ncx - cx, ncy - cy) <= 0.6 * r:
            cx, cy = ncx, ncy
            dist = np.sqrt((xx - float(cx)) ** 2 + (yy - float(cy)) ** 2)
    core = dist <= max(1.2, 0.5 * r)
    ring = (dist > 0.6 * r) & (dist <= 1.2 * r)
    if np.count_nonzero(core) < 3 or np.count_nonzero(ring) < 5:
        return None
    # Contrast in units of the background level: invariant to exposure / gain.
    unit = max(float(bg_gray), 5.0)
    core_c = (float(np.median(patch_gray[core])) - bg_gray) / unit
    ring_c = (float(np.percentile(patch_gray[ring], 90)) - bg_gray) / unit
    ratio = core_c / ring_c if ring_c > 0.15 else 1.0
    b, g, rr = [float(v) for v in np.median(patch_bgr[core], axis=0)]
    lb = np.log((b + 4.0) / (bg_bgr[0] + 4.0))
    lg = np.log((g + 4.0) / (bg_bgr[1] + 4.0))
    lr = np.log((rr + 4.0) / (bg_bgr[2] + 4.0))
    # R/B profile (Core / Cell / Rim), each normalised to the local background
    # R/B so that the camera white balance cancels:  RB_n = (R/B)_region / (R/B)_bg
    rb_bg = (float(bg_bgr[2]) + 4.0) / (float(bg_bgr[0]) + 4.0)
    cell = dist <= r
    rim = (dist > 0.75 * r) & (dist <= 1.15 * r)
    # Grid-line pixels (bright, white) would dilute the cell colour: exclude
    # them; if a region is mostly grid, the R/B profile is marked unreliable.
    on_grid = (grid[y0:y1, x0:x1] > 0) if grid is not None else np.zeros_like(core)
    log_rb = []
    for region in (core, cell, rim):
        clean = region & ~on_grid
        if np.count_nonzero(clean) < max(3, 0.5 * np.count_nonzero(region)):
            log_rb = [np.nan, np.nan, np.nan]
            break
        mb, _, mr = [float(v) for v in np.mean(patch_bgr[clean], axis=0)]
        log_rb.append(np.log(((mr + 4.0) / (mb + 4.0)) / rb_bg))
    # Fraction of saturated core pixels: dye-loaded (dead) cells absorb light
    # and are never saturated, so this vetoes the colour criterion.
    core_sat = float(np.mean(np.max(patch_bgr[core], axis=1) >= 250.0))
    # Hollowness: centre (<= 0.35 r) vs brightest annulus (0.35-1.0 r), means
    # over all angles so elongated cells and neighbours matter little.
    pc = patch_gray - float(bg_gray)
    centre_v = pc[dist <= max(0.35 * r, 1.0)]
    annuli = [pc[(dist > a * r) & (dist <= (a + 0.15) * r)] for a in (0.35, 0.5, 0.65, 0.8)]
    annuli = [float(np.mean(v)) for v in annuli if v.size]
    ring_peak = max(annuli) if annuli else 0.0
    hollow = float(np.mean(centre_v)) / ring_peak if (centre_v.size and ring_peak > 1e-3) else 1.0
    # Body colour: green vs red of the brighter half of the cell body,
    # background-normalised (live: yellow/white body; stained ring: magenta/red).
    body = (dist > 0.35 * r) & (dist <= 1.0 * r)
    body_px = patch_bgr[body]
    if body_px.shape[0] >= 5:
        lum = body_px.sum(axis=1)
        sel = body_px[lum >= np.percentile(lum, 50)]
        _, bg_g, bg_r = [float(v) for v in bg_bgr]
        body_gr = float(np.log((sel[:, 1].mean() + 4.0) / (bg_g + 4.0)) - np.log((sel[:, 2].mean() + 4.0) / (bg_r + 4.0)))
    else:
        body_gr = np.nan
    # Colour difference between the cell interior and the local background in
    # CIELAB (Delta E 1976).  The background is Trypan-blue medium; a dead
    # cell takes up the dye and its interior looks like the background.
    core_dE = _lab_delta_e(patch_bgr[dist <= max(1.2, 0.45 * r)], bg_bgr)
    return np.array([core_c, ratio, lb - lr, lg - 0.5 * (lb + lr)] + log_rb + [core_sat, hollow, body_gr, core_dE],
                    dtype=np.float32)


def _viability_grid_pixels(gray):
    """Thin bright straight lines (hemocytometer rulings), 1 = grid pixel."""
    h, w = gray.shape[:2]
    L = max(21, int(round(min(h, w) * 0.05)))
    smooth = cv2.GaussianBlur(gray, (3, 3), 0)
    line = np.maximum(
        cv2.morphologyEx(smooth, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (L, 1))),
        cv2.morphologyEx(smooth, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, L))),
    )
    resp = line - cv2.GaussianBlur(smooth, (0, 0), 15)
    med = float(np.median(resp)); mad = 1.4826 * float(np.median(np.abs(resp - med))) + 1e-3
    return (resp > med + 4.0 * mad).astype(np.uint8)


def _viability_relative_features(raw_list, ref_contrast=None):
    """Population-relative features for the cells of one image/quadrant.

    ref_contrast: brightness reference of a typical live cell.  By default it
    is the 75th percentile of the cells in the same image (valid while most
    cells are alive); a calibrated profile supplies a fixed reference measured
    on user-labelled live cells, which also works for low-viability samples.
    """
    valid = [f for f in raw_list if f is not None]
    if not valid:
        return [None] * len(raw_list)
    F = np.vstack(valid).astype(np.float32)
    if len(F) >= 3:
        ref = max(float(np.percentile(F[:, 0], 75)), 1.0)
    else:
        ref = 3.0
    if ref_contrast is not None and float(ref_contrast) > 0:
        # Calibrated microscope: the labelled live-cell level acts as a floor,
        # so a mostly-dead sample cannot become its own "bright" reference.
        ref = max(ref, 0.8 * float(ref_contrast)) if len(F) >= 3 else float(ref_contrast)
    def robust(col):
        if len(F) < 15:
            return 0.0, 1.0
        med = float(np.median(col))
        return med, max(1.4826 * float(np.median(np.abs(col - med))), 0.05)
    mb, sb = robust(F[:, 2])
    mg, sg = robust(F[:, 3])
    de_all = F[:, 10][np.isfinite(F[:, 10])]
    # Per-image normalisation of the colour difference: cameras differ in
    # colour contrast (the same cells give a compressed Delta E range on a
    # grey-balanced camera).  When most cells are clearly distinct from the
    # background (median >= 75), Delta E is expressed as a robust z-score of
    # this image; otherwise (low-viability sample) the absolute value is kept.
    if de_all.size >= 30 and float(np.median(de_all)) >= 75.0:
        de_med = float(np.median(de_all))
        de_iqr = max(float(np.percentile(de_all, 75) - np.percentile(de_all, 25)), 8.0)
    else:
        de_med, de_iqr = None, None
    body = F[:, 9][np.isfinite(F[:, 9])]
    if body.size >= 15:
        mbody = float(np.median(body))
        sbody = max(1.4826 * float(np.median(np.abs(body - mbody))), 0.03)
    else:
        mbody, sbody = 0.0, 1.0
    out = []
    for f in raw_list:
        if f is None:
            out.append(None)
            continue
        out.append(np.array([
            f[0] / ref,               # relative_brightness (1 = typical bright cell)
            f[1],                     # core_ring_ratio (< 1: darker centre)
            (f[2] - mb) / sb,         # blue_shift_z
            (f[3] - mg) / sg,         # green_shift_z
            f[0],                     # absolute_contrast
            f[4], f[5], f[6],         # log R/B (bg-normalised): core, cell, rim
            f[7],                     # core_saturation
            f[8],                     # hollowness (centre / brightest annulus)
            (f[9] - mbody) / sbody if np.isfinite(f[9]) else np.nan,   # body green-vs-red z
            f[10],                    # interior-vs-background colour difference (Delta E)
            ((f[10] - de_med) / de_iqr) if (de_med is not None and np.isfinite(f[10])) else np.nan,
        ], dtype=np.float32))
    return out


def _sigmoid(x):
    return 1.0 / (1.0 + np.exp(-np.clip(x, -30.0, 30.0)))


def _rb_dye_score(f):
    """R/B-profile score D = log RB_cell + 0.8 * log(RB_core / RB_rim).

    Live cells exclude the dye: their core is red-shifted relative to the
    background and the R/B ratio falls from core to rim (large D).  Dead cells
    take up Trypan blue: low R/B over the whole cell and a flat profile (small D).
    """
    if not np.all(np.isfinite([f[5], f[6], f[7]])):
        return 2.0          # profile not measurable (cell on a grid line): neutral
    return float(f[6]) + 0.8 * (float(f[5]) - float(f[7]))


def _rule_dead_probability(f):
    if len(f) == len(BRIGHTFIELD_FEATURE_NAMES):
        return _brightfield_dead_probability(f)
    return _bright_cell_dead_probability(f)


def _bright_cell_dead_probability(f):
    """Trypan-blue rule for captures where live cells appear bright.

    A cell whose interior has (nearly) the same colour as the surrounding
    dye-containing medium has taken up Trypan blue -> DEAD.  A live cell
    excludes the dye and differs from the background, whether it looks
    white, yellow, orange or red.  The bright refractive rim is ignored:
    only the interior (<= 0.45 r around the re-centred cell) is compared.
    """
    de = float(f[11]) if len(f) > 11 else float("nan")
    dz = float(f[12]) if len(f) > 12 else float("nan")
    bz = float(f[2]) if len(f) > 2 else float("nan")
    cs = float(f[8]) if len(f) > 8 else float("nan")
    if np.isfinite(dz) and np.isfinite(bz) and np.isfinite(cs):
        # interior looks like the stained background: small colour difference
        # (image z-score), shifted toward blue, colourless (low saturation).
        # Fitted on 128 user-labelled cells from 6 images / 3 microscopes
        # (leave-one-image-out accuracy 90.6%).
        b0, b_blue, b_sat, b_dz = VIABILITY_BG_LIKENESS_COEF
        return float(_sigmoid(b0 + b_blue * bz + b_sat * cs + b_dz * dz))
    if np.isfinite(dz):
        return float(_sigmoid((VIABILITY_DELTA_E_Z_THRESHOLD - dz) / 0.18))
    if not np.isfinite(de):
        return _legacy_bright_cell_dead_probability(f)
    return float(_sigmoid((VIABILITY_DELTA_E_THRESHOLD - de) / 5.0))


def _legacy_bright_cell_dead_probability(f):
    """Previous multi-cue rule, used only when the interior colour cannot be
    measured (cell cut by the image border)."""
    rel, ring_ratio, blue_z = float(f[0]), float(f[1]), float(f[2])
    not_saturated = _sigmoid((0.5 - float(f[8])) / 0.08)
    dye_profile = (_sigmoid((1.0 - _rb_dye_score(f)) / 0.12) * _sigmoid((0.85 - rel) / 0.05)
                   * not_saturated)
    dye_shift = _sigmoid((blue_z - 4.0) / 0.4) * _sigmoid((0.75 - rel) / 0.04)
    dim = _sigmoid((0.50 - rel) / 0.04)
    dark_centre = _sigmoid((0.65 - ring_ratio) / 0.04) * _sigmoid((0.80 - rel) / 0.04)
    # Cyan/blue stained cell: body shifted to green-blue (low red) relative to
    # the other cells, plus a blue shift of the core; can look bright in grey.
    body_z = float(f[10]) if len(f) > 10 and np.isfinite(f[10]) else 0.0
    # (very bright white cells with a cyan fringe are live: gate by brightness)
    cyan_strong = (_sigmoid((body_z - 2.0) / 0.3) * _sigmoid((blue_z - 1.5) / 0.4)
                   * _sigmoid((0.88 - rel) / 0.04))
    cyan_dim = (_sigmoid((body_z - 1.4) / 0.25) * _sigmoid((blue_z - 1.3) / 0.3)
                * _sigmoid((0.78 - rel) / 0.04))
    cyan = max(cyan_strong, cyan_dim)
    return float(max(dye_profile, dye_shift, dim, dark_centre, cyan))


def _brightfield_dead_probability(f):
    """Bright-field (cells darker than background) Trypan-blue rule.

    LIVE : refractile cell, centre at or above the background level inside a
           dark rim (dye excluded).
    DEAD : centre darker than the background (dye-filled / opaque body), or a
           colour shift towards blue relative to the other cells (dye uptake).
    """
    core_dark, rim_dark, blue_z, centre_minus_rim = float(f[0]), float(f[1]), float(f[2]), float(f[3])
    opaque = _sigmoid((core_dark - 0.08) / 0.025)
    stained = _sigmoid((blue_z - 2.5) / 0.4) * _sigmoid((core_dark - 0.02) / 0.02)
    return float(max(opaque, stained))


def _rule_logit(f):
    p = min(max(_rule_dead_probability(f), 1e-4), 1 - 1e-4)
    return float(np.log(p / (1.0 - p)))


def _profile_design_row(f, profile):
    z = (np.asarray(f, np.float64) - np.asarray(profile["mean"], np.float64)) / \
        np.maximum(np.asarray(profile["scale"], np.float64), 1e-6)
    z = np.nan_to_num(z, nan=0.0)          # unmeasurable feature -> average value
    return np.concatenate([[_rule_logit(f) / 4.0], z])


def _profile_dead_probability(f, profile):
    x = _profile_design_row(f, profile)
    return float(_sigmoid(float(profile["intercept"]) + float(np.dot(profile["coef"], x))))


def _fit_logistic_anchored(X, y, w, prior, l2):
    """Weighted logistic regression, L2 penalty towards `prior` (Newton/IRLS)."""
    Z = np.hstack([np.ones((X.shape[0], 1)), X])
    beta = prior.copy()
    reg = np.eye(Z.shape[1]) * l2
    reg[0, 0] = l2 * 0.1
    def loss(b):
        s = Z @ b
        nll = np.sum(w * (np.logaddexp(0.0, s) - y * s))
        d = b - prior
        return nll + 0.5 * float(d @ reg @ d)

    current = loss(beta)
    for _ in range(100):
        p = _sigmoid(Z @ beta)
        grad = Z.T @ (w * (p - y)) + reg @ (beta - prior)
        hess = (Z.T * (w * np.clip(p * (1 - p), 1e-6, None))) @ Z + reg
        step = np.linalg.solve(hess, grad)
        t = 1.0
        while t > 1e-4:                      # backtracking (damped Newton)
            cand = beta - t * step
            cand_loss = loss(cand)
            if cand_loss <= current - 1e-4 * t * float(grad @ step):
                break
            t *= 0.5
        else:
            break
        beta, current = cand, cand_loss
        if np.max(np.abs(t * step)) < 1e-7:
            break
    return beta


def _balanced_accuracy(pred, y):
    pred = np.asarray(pred, int); y = np.asarray(y, int)
    accs = [float(np.mean(pred[y == c] == c)) for c in (0, 1) if np.any(y == c)]
    return float(np.mean(accs)) if accs else 0.0


def _fit_viability_profile(features, labels, l2=2.0):
    """Few-shot per-microscope calibration of the live/dead decision.

    The model starts from the default rule (its logit is the first input with
    prior weight 1) and only departs from it as far as the user's labels
    require.  Classes are weighted equally, so the result does not depend on
    how many live vs. dead cells the user happened to click.  Leave-one-out
    balanced accuracy of the calibrated model and of the default rule are
    reported so a calibration that does not improve on the rule can be refused.
    """
    F = np.array(features, np.float64)
    F_default = F.copy()           # features exactly as the default rule saw them
    y = np.asarray(labels, np.float64)
    # Live-cell brightness reference of the images used for calibration
    # (feature 4 / feature 0 per cell).  Afterwards it is used as a floor for
    # the per-image reference, protecting low-viability samples.
    polarity = "dark" if F.shape[1] == len(BRIGHTFIELD_FEATURE_NAMES) else "bright"
    ref_contrast = None
    if polarity == "bright":
        ok = F[:, 0] > 1e-3
        ref_contrast = float(np.median(F[ok, 4] / F[ok, 0])) if np.any(ok) else None
    mean = np.nan_to_num(np.nanmean(F, axis=0), nan=0.0)
    scale = np.nan_to_num(np.nanstd(F, axis=0), nan=1.0)
    scale[scale < 1e-6] = 1.0
    stub = {"mean": mean, "scale": scale}
    X = np.vstack([_profile_design_row(f, stub) for f in F])
    n1 = max(1.0, float(np.sum(y == 1))); n0 = max(1.0, float(np.sum(y == 0)))
    w = np.where(y == 1, 0.5 * len(y) / n1, 0.5 * len(y) / n0)
    prior = np.zeros(X.shape[1] + 1)
    prior[1] = 4.0                      # rule logit (scaled by 1/4) with weight 1
    beta = _fit_logistic_anchored(X, y, w, prior, l2)
    Zfull = np.hstack([np.ones((X.shape[0], 1)), X])
    train_pred = (_sigmoid(Zfull @ beta) >= 0.5).astype(int)

    loo_pred = np.zeros(len(y), int)
    for i in range(len(y)):
        keep = np.arange(len(y)) != i
        b_i = _fit_logistic_anchored(X[keep], y[keep], w[keep], prior, l2)
        loo_pred[i] = int(_sigmoid(Zfull[i] @ b_i) >= 0.5)
    rule_pred = np.array([int(_rule_dead_probability(f) >= 0.5) for f in F_default])
    return {
        "version": VIABILITY_PROFILE_VERSION,
        "polarity": polarity,
        "features": ["rule_logit/4"] + list(_viability_feature_names(polarity)),
        "mean": mean.tolist(), "scale": scale.tolist(),
        "intercept": float(beta[0]), "coef": beta[1:].tolist(),
        "ref_contrast": ref_contrast,
        "n_live": int(np.sum(y == 0)), "n_dead": int(np.sum(y == 1)),
        "training_accuracy": float(np.mean(train_pred == y.astype(int))),
        "loo_balanced_accuracy": _balanced_accuracy(loo_pred, y),
        "rule_balanced_accuracy": _balanced_accuracy(rule_pred, y),
        "created": time.strftime("%Y-%m-%d %H:%M:%S"),
    }


def _viability_mode_text():
    parts = []
    for pol, name in (("bright", "bright-cell"), ("dark", "bright-field")):
        prof = _load_viability_profile(pol)
        if prof is not None:
            parts.append(f"{name} calibrated ({prof.get('n_live', 0)}L/{prof.get('n_dead', 0)}D)")
    if not parts:
        return "Live/Dead: default rules (image type detected automatically)"
    return "Live/Dead: " + ", ".join(parts) + "; others default"


def _classify_viability_brightfield(bgr_img, selected, grid_mask=None, profile=None):
    """Live/dead for bright-field captures (cells darker than the background)."""
    if not selected:
        return [], []
    f32 = bgr_img.astype(np.float32)
    gray = f32.mean(axis=2)
    radii = np.array([float(it[2]) for it in selected], np.float32)
    k = 2 * int(max(6.0, 3.5 * float(np.median(radii)))) + 1
    bg_gray = cv2.medianBlur(np.clip(gray, 0, 255).astype(np.uint8), k).astype(np.float32)
    bg_bgr = np.dstack([cv2.medianBlur(bgr_img[:, :, c], k).astype(np.float32) for c in range(3)])
    h, w = gray.shape[:2]
    raw = []
    for it in selected:
        cx, cy, r = float(it[0]), float(it[1]), max(1.5, float(it[2]))
        xi, yi = int(round(cx)), int(round(cy))
        R = int(np.ceil(1.15 * r)) + 1
        if yi - R < 0 or xi - R < 0 or yi + R + 1 > h or xi + R + 1 > w:
            raw.append(None)
            continue
        yy, xx = np.mgrid[-R:R + 1, -R:R + 1]
        dd = np.hypot(xx + (xi - cx), yy + (yi - cy)) / r
        P = gray[yi - R:yi + R + 1, xi - R:xi + R + 1]
        B = max(float(bg_gray[yi, xi]), 5.0)
        core = P[dd <= 0.4]
        rim = P[(dd > 0.6) & (dd <= 1.0)]
        if core.size < 2 or rim.size < 4:
            raw.append(None)
            continue
        core_dark = (B - float(np.mean(core))) / B
        rim_dark = (B - float(np.percentile(rim, 20))) / B
        C = f32[yi - R:yi + R + 1, xi - R:xi + R + 1][dd <= 0.6].mean(axis=0)
        bc = bg_bgr[yi, xi]
        blue = float(np.log((C[0] + 4) / (bc[0] + 4)) - np.log((C[2] + 4) / (bc[2] + 4)))
        raw.append([core_dark, rim_dark, blue, rim_dark - core_dark])
    vals = np.array([r_[2] for r_ in raw if r_ is not None], np.float64)
    if vals.size >= 15:
        med = float(np.median(vals)); mad = max(1.4826 * float(np.median(np.abs(vals - med))), 0.03)
    else:
        med, mad = 0.0, 0.1
    classified, features = [], []
    for it, r_ in zip(selected, raw):
        if r_ is None:
            f = None
            p_dead = 0.5
        else:
            f = np.array([r_[0], r_[1], (r_[2] - med) / mad, r_[3], r_[2]], np.float32)
            p_dead = _profile_dead_probability(f, profile) if profile is not None else _brightfield_dead_probability(f)
        classified.append((it[0], it[1], it[2], "dead" if p_dead >= 0.5 else "live", float(p_dead)))
        features.append(f)
    return classified, features


def _viability_live_rescue(f):
    """Two live-cell appearances the background-likeness rule calls DEAD.

    Fixed from 54 dead-called NIH3T3 cells re-labelled by the user (1e3 sample,
    2026-11-13): 15 of 23 live cells are rescued and none of the 31 dead cells.
      A  orange/red ring with a red-shifted core: high core R/B, no blue shift,
         green below the population (dye excluded, slightly out of focus).
      B  bright cell that glows with a blue/cyan tint: bright, yellow-green body
         and a brighter centre than rim (refractile live cell, not dye uptake).
    Dead cells (blue interior, or faint/blurred body with a broken membrane)
    satisfy neither.
    """
    if f is None:
        return False
    rel, blue_z, green_z = float(f[0]), float(f[2]), float(f[3])
    lrb_core, hollow, body_z = float(f[5]), float(f[9]), float(f[10])
    ring_live = np.isfinite(lrb_core) and lrb_core >= 2.05 and blue_z <= 1.4 and green_z <= -1.8
    glowing_live = np.isfinite(body_z) and body_z >= 4.0 and rel >= 0.5 and hollow >= 1.15
    return bool(ring_live or glowing_live)


def _gaussian_at_points(maps, points, sigma):
    """cv2.GaussianBlur(m, (0, 0), sigma)[y, x] for each map m and point (y, x).

    Uses the same kernel size, kernel and BORDER_REFLECT_101 border as OpenCV,
    so the values match a full-image blur while only the needed pixels are computed.
    """
    ksize = int(np.rint(sigma * 8 + 1)) | 1
    r = ksize // 2
    kern = cv2.getGaussianKernel(ksize, sigma, cv2.CV_32F).astype(np.float32).reshape(-1)
    stack = np.stack([cv2.copyMakeBorder(m, r, r, r, r, cv2.BORDER_REFLECT_101) for m in maps], axis=0)
    out = np.empty((len(points), len(maps)), np.float32)
    for i, (y, x) in enumerate(points):
        window = stack[:, y:y + ksize, x:x + ksize]          # (maps, k, k)
        rows = np.tensordot(window, kern, axes=([2], [0]))  # horizontal pass at the needed rows
        out[i] = rows @ kern                                 # vertical pass at the centre
    return out


def _classify_viability_v7(bgr_img, selected, grid_mask=None, profile=None):
    """Classify already-detected cells; detection results are never changed.

    Returns (classified, features) where classified items are
    (cx, cy, radius, 'live'|'dead', p_dead) and features are per-cell vectors
    (None when a cell is too close to the border to measure).
    """
    if not selected:
        return [], []
    gray = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2GRAY).astype(np.float32)
    h, w = gray.shape[:2]
    free = np.ones((h, w), np.uint8)
    for item in selected:
        cv2.circle(free, (int(item[0]), int(item[1])), int(round(float(item[2]) * 2.0)) + 2, 0, -1)
    grid_px = None
    if grid_mask is not None and grid_mask.shape[:2] == (h, w):
        grid_px = cv2.dilate((grid_mask > 0).astype(np.uint8), np.ones((5, 5), np.uint8))
        free[cv2.dilate((grid_mask > 0).astype(np.uint8), np.ones((5, 5), np.uint8)) > 0] = 0
    else:
        grid_px = cv2.dilate(_viability_grid_pixels(gray), np.ones((5, 5), np.uint8))
        free[grid_px > 0] = 0
    # Local background maps (cells and grid lines excluded), so uneven
    # illumination / vignetting cancels out of every contrast and colour ratio.
    if np.count_nonzero(free) < 500:
        free[:] = 1
    radii = np.array([float(it[2]) for it in selected], np.float32)
    sigma = float(max(12.0, 8.0 * float(np.median(radii))))
    bgr_f = bgr_img.astype(np.float32)
    free_f = free.astype(np.float32)
    centres = [(int(np.clip(round(float(it[1])), 0, h - 1)), int(np.clip(round(float(it[0])), 0, w - 1)))
               for it in selected]
    # Same Gaussian background as blurring whole maps, but evaluated only at
    # the cell centres where it is read (much faster for a large sigma).
    local = _gaussian_at_points(
        [free_f, gray * free_f] + [bgr_f[:, :, ch] * free_f for ch in range(3)], centres, sigma)
    weight = np.maximum(local[:, 0], np.float32(1e-3))
    bg_gray_at = local[:, 1] / weight
    bg_bgr_at = local[:, 2:5] / weight[:, None]
    raw = []
    for idx, it in enumerate(selected):
        cx, cy, rad = float(it[0]), float(it[1]), float(it[2])
        raw.append(_viability_raw_features(
            bgr_img, gray, bg_bgr_at[idx], float(bg_gray_at[idx]), cx, cy, rad, grid=grid_px))
    features = _viability_relative_features(
        raw, ref_contrast=(profile or {}).get("ref_contrast"))
    classified = []
    for item, f in zip(selected, features):
        if f is None:
            p_dead = 0.10
        elif profile is not None:
            p_dead = _profile_dead_probability(f, profile)
        else:
            p_dead = _rule_dead_probability(f)
            if p_dead >= 0.5 and _viability_live_rescue(f):
                p_dead = 0.35                     # live appearance the base rule misreads (see helper)
        classified.append((item[0], item[1], item[2], "dead" if p_dead >= 0.5 else "live", float(p_dead)))
    return classified, features


def calculate_hemocytometer_results(total_cells, counted_squares, dilution_factor, target_units_x1e4=0.0):
    """Return average count, concentration (cells/mL), and injection volume (uL).

    Assumption: each Q region is one 1 mm x 1 mm Improved Neubauer large
    square at 0.1 mm chamber depth, so one counted square has a volume of
    10^-4 mL.
    """
    total_cells = max(0.0, float(total_cells))
    counted_squares = max(0.0, float(counted_squares))
    dilution_factor = max(0.0, float(dilution_factor))
    target_units_x1e4 = max(0.0, float(target_units_x1e4))

    average_per_square = total_cells / counted_squares if counted_squares else 0.0
    concentration = average_per_square * dilution_factor * 10000.0
    target_cell_number = target_units_x1e4 * 10000.0
    injection_ul = (
        target_cell_number / concentration * 1000.0
        if concentration > 0.0 and target_cell_number > 0.0
        else 0.0
    )
    return average_per_square, concentration, injection_ul


def _resize_panel_for_display(image: np.ndarray, target_width: int = 760) -> np.ndarray:
    """Resize one independently analyzed capture for the combined display only."""
    if image is None or image.size == 0:
        return np.zeros((100, target_width, 3), dtype=np.uint8)
    h, w = image.shape[:2]
    if w <= 0 or h <= 0:
        return np.zeros((100, target_width, 3), dtype=np.uint8)
    scale = float(target_width) / float(w)
    target_h = max(1, int(round(h * scale)))
    return cv2.resize(image, (target_width, target_h), interpolation=cv2.INTER_AREA)


def _labeled_independent_panel(image: np.ndarray, title: str, target_width: int = 760) -> np.ndarray:
    """Create a bordered display panel without changing analysis coordinates."""
    panel_img = _resize_panel_for_display(image, target_width)
    header_h, pad = 52, 12
    h, w = panel_img.shape[:2]
    panel = np.full((h + header_h + pad * 2, w + pad * 2, 3), (18, 28, 45), dtype=np.uint8)
    cv2.rectangle(panel, (1, 1), (panel.shape[1] - 2, panel.shape[0] - 2), (90, 105, 130), 2)
    cv2.putText(panel, title, (pad, 34), cv2.FONT_HERSHEY_SIMPLEX, 0.82, (255, 255, 255), 2, cv2.LINE_AA)
    panel[header_h + pad:header_h + pad + h, pad:pad + w] = panel_img
    return panel


def _compose_independent_display(first: np.ndarray, second: np.ndarray | None = None,
                                 first_title: str = 'Independent capture: Q1-Q2',
                                 second_title: str = 'Independent capture: Q3-Q4') -> np.ndarray:
    """Show captures as separate panels so no shared Q1/Q3 or Q2/Q4 axis is implied."""
    if second is None:
        return _labeled_independent_panel(first, first_title, target_width=1200)
    left = _labeled_independent_panel(first, first_title, target_width=760)
    right = _labeled_independent_panel(second, second_title, target_width=760)
    gap = 24
    out_h = max(left.shape[0], right.shape[0])
    out_w = left.shape[1] + gap + right.shape[1]
    out = np.full((out_h, out_w, 3), (11, 18, 32), dtype=np.uint8)
    out[:left.shape[0], :left.shape[1]] = left
    x0 = left.shape[1] + gap
    out[:right.shape[0], x0:x0 + right.shape[1]] = right
    return out


# =========================
# Registered preview stitching (display only; v25-25)
# =========================
# Numerical counting ALWAYS remains independent in each native capture.
# These routines only produce a visually registered Q1-Q2 / Q3-Q4 preview.
# They first try constrained local-feature alignment around the shared dense
# horizontal grid band, then fall back to grid-band translation/correlation.


def _stitch_gray_features(bgr):
    gray = cv2.cvtColor(bgr, cv2.COLOR_BGR2GRAY)
    return cv2.createCLAHE(clipLimit=1.8, tileGridSize=(8, 8)).apply(gray)


def _dense_horizontal_band_y(bgr, expected='any'):
    gray = _stitch_gray_features(bgr)
    h, w = gray.shape[:2]
    blur = cv2.GaussianBlur(gray, (3, 3), 0)
    binary = cv2.adaptiveThreshold(
        blur, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
        cv2.THRESH_BINARY, 51, -3,
    )
    line_len = max(50, int(round(w * 0.05)))
    horizontal = cv2.morphologyEx(
        binary, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (line_len, 1)),
    )
    horizontal = cv2.dilate(horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)), iterations=1)
    row_strength = np.mean(horizontal > 0, axis=1).astype(np.float32)
    if expected == 'bottom':
        lo, hi = int(0.45 * h), max(int(0.46 * h) + 1, int(0.99 * h))
    elif expected == 'top':
        lo, hi = int(0.01 * h), max(int(0.02 * h) + 1, int(0.55 * h))
    else:
        lo, hi = 0, h
    segment = row_strength[lo:hi]
    if segment.size == 0:
        return h // 2, 0.0, horizontal
    # Smooth the row energy so the dense multi-line band wins over a single line.
    win = max(7, int(round(h * 0.018)))
    kernel = np.ones(win, dtype=np.float32) / float(win)
    smoothed = np.convolve(segment, kernel, mode='same')
    idx = int(np.argmax(smoothed))
    return lo + idx, float(smoothed[idx]), horizontal


def _vertical_grid_profile_near_band(bgr, band_y, band_half_height=None):
    gray = _stitch_gray_features(bgr)
    h, w = gray.shape[:2]
    hh = band_half_height or max(45, int(round(h * 0.12)))
    y0, y1 = max(0, int(band_y - hh)), min(h, int(band_y + hh + 1))
    crop = gray[y0:y1]
    if crop.size == 0:
        return np.zeros(w, dtype=np.float32)
    blur = cv2.GaussianBlur(crop, (3, 3), 0)
    thr = cv2.adaptiveThreshold(
        blur, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
        cv2.THRESH_BINARY_INV, 51, 3,
    )
    vlen = max(25, int(round(crop.shape[0] * 0.45)))
    vertical = cv2.morphologyEx(
        thr, cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (1, vlen)),
    )
    profile = np.sum(vertical > 0, axis=0).astype(np.float32)
    profile -= float(np.mean(profile))
    std = float(np.std(profile))
    if std > 1e-6:
        profile /= std
    return profile


def _profile_translation_shift(top_profile, bottom_profile, max_shift):
    w = min(len(top_profile), len(bottom_profile))
    if w < 40:
        return 0, 0.0
    a, b = top_profile[:w], bottom_profile[:w]
    best_shift, best_score = 0, -1e9
    max_shift = int(max(0, min(max_shift, w // 2)))
    for shift in range(-max_shift, max_shift + 1):
        # bottom x maps to x + shift in top coordinates
        top_start = max(0, shift)
        bot_start = max(0, -shift)
        n = min(w - top_start, w - bot_start)
        if n < max(30, int(0.35 * w)):
            continue
        aa = a[top_start:top_start + n]
        bb = b[bot_start:bot_start + n]
        denom = float(np.linalg.norm(aa) * np.linalg.norm(bb))
        score = float(np.dot(aa, bb) / denom) if denom > 1e-6 else -1e9
        if score > best_score:
            best_shift, best_score = shift, score
    if not np.isfinite(best_score) or best_score <= -0.999999:
        return 0, 0.0
    return int(best_shift), float(best_score)


def _estimate_feature_pair_affine(top_bgr, bottom_bgr, top_band, bottom_band):
    """Estimate bottom->top affine from the likely overlap only.

    Repetitive hemocytometer grids can fool unconstrained stitching.  We therefore
    limit keypoints to the bottom part of Q1-Q2 and top part of Q3-Q4, estimate a
    similarity-like affine transform, then reject it unless the two dense grid
    bands map to approximately the same y position.
    """
    top_gray = _stitch_gray_features(top_bgr)
    bot_gray = _stitch_gray_features(bottom_bgr)
    ht, wt = top_gray.shape[:2]
    hb, wb = bot_gray.shape[:2]

    top_mask = np.zeros_like(top_gray, dtype=np.uint8)
    bot_mask = np.zeros_like(bot_gray, dtype=np.uint8)
    top_mask[max(0, int(0.35 * ht)):min(ht, int(0.995 * ht)), :] = 255
    bot_mask[max(0, int(0.005 * hb)):min(hb, int(0.65 * hb)), :] = 255

    use_sift = hasattr(cv2, 'SIFT_create')
    if use_sift:
        detector = cv2.SIFT_create(nfeatures=2500, contrastThreshold=0.025, edgeThreshold=12)
        norm = cv2.NORM_L2
        ratio = 0.72
    else:
        detector = cv2.ORB_create(nfeatures=3500, scaleFactor=1.15, nlevels=10, fastThreshold=10)
        norm = cv2.NORM_HAMMING
        ratio = 0.78

    kp_top, des_top = detector.detectAndCompute(top_gray, top_mask)
    kp_bot, des_bot = detector.detectAndCompute(bot_gray, bot_mask)
    if des_top is None or des_bot is None or len(kp_top) < 8 or len(kp_bot) < 8:
        return None, {'method': 'feature', 'reason': 'not-enough-keypoints'}

    matcher = cv2.BFMatcher(norm)
    pairs = matcher.knnMatch(des_bot, des_top, k=2)  # bottom -> top
    good = []
    for pair in pairs:
        if len(pair) < 2:
            continue
        m, n = pair
        if m.distance < ratio * n.distance:
            good.append(m)
    if len(good) < 8:
        return None, {'method': 'feature', 'reason': 'not-enough-matches', 'matches': len(good)}

    src = np.float32([kp_bot[m.queryIdx].pt for m in good])
    dst = np.float32([kp_top[m.trainIdx].pt for m in good])
    M, inliers = cv2.estimateAffinePartial2D(
        src, dst, method=cv2.RANSAC,
        ransacReprojThreshold=4.0, maxIters=4000,
        confidence=0.995, refineIters=25,
    )
    if M is None:
        return None, {'method': 'feature', 'reason': 'ransac-failed', 'matches': len(good)}

    inlier_count = int(np.count_nonzero(inliers)) if inliers is not None else 0
    inlier_ratio = inlier_count / max(1, len(good))
    a, b = float(M[0, 0]), float(M[0, 1])
    scale = math.sqrt(a * a + b * b)
    angle = math.degrees(math.atan2(float(M[1, 0]), float(M[0, 0])))

    # Dense-band consistency is the strongest protection against a false grid match.
    bx = 0.5 * wb
    mapped_x = float(M[0, 0] * bx + M[0, 1] * bottom_band + M[0, 2])
    mapped_y = float(M[1, 0] * bx + M[1, 1] * bottom_band + M[1, 2])
    band_error = abs(mapped_y - float(top_band))

    valid = (
        inlier_count >= 8 and inlier_ratio >= 0.28 and
        0.86 <= scale <= 1.16 and abs(angle) <= 8.0 and
        band_error <= 0.12 * max(ht, hb) and
        -0.35 * wt <= mapped_x <= 1.35 * wt
    )
    info = {
        'method': 'feature', 'matches': len(good), 'inliers': inlier_count,
        'inlier_ratio': float(inlier_ratio), 'scale': float(scale),
        'angle': float(angle), 'band_error': float(band_error),
    }
    return (M.astype(np.float32), info) if valid else (None, {**info, 'reason': 'constraint-rejected'})


def _estimate_grid_translation(top_bgr, bottom_bgr, top_band, bottom_band):
    top_profile = _vertical_grid_profile_near_band(top_bgr, top_band)
    bot_profile = _vertical_grid_profile_near_band(bottom_bgr, bottom_band)
    shift_x, corr = _profile_translation_shift(
        top_profile, bot_profile,
        max_shift=int(round(min(top_bgr.shape[1], bottom_bgr.shape[1]) * 0.24)),
    )
    shift_y = float(top_band - bottom_band)
    M = np.array([[1.0, 0.0, float(shift_x)], [0.0, 1.0, shift_y]], dtype=np.float32)
    return M, {'method': 'grid-translation', 'x_shift': int(shift_x), 'y_shift': float(shift_y), 'profile_corr': float(corr)}


def _dense_line_span(clusters):
    """Extent of the fine (central-square) rulings along one axis, or None."""
    p = np.array(sorted(x for x, _ in clusters), np.float64)
    if len(p) < 6:
        return None
    d = np.diff(p)
    small = d <= 0.45 * np.percentile(d, 90)
    best, cur, start = (0, 0, 0), 0, 0
    for i, s_ in enumerate(small):
        if s_:
            if cur == 0:
                start = i
            cur += 1
            if cur > best[0]:
                best = (cur, start, i + 1)
        else:
            cur = 0
    if best[0] < 4:
        return None
    return float(p[best[1]]), float(p[best[2]])


def _pair_line_sets(bgr):
    """Vertical rulings over the whole frame; horizontal rulings measured
    inside the central-square column band (its fine lines span only there)."""
    g = cv2.cvtColor(bgr, cv2.COLOR_BGR2GRAY)
    cl = _grid_line_clusters(g)
    span = _dense_line_span(cl["x"])
    if span is not None and span[1] - span[0] > 40:
        x0, x1 = int(span[0]) + 3, int(span[1]) - 3
        cl = {"x": cl["x"], "y": _grid_line_clusters(g[:, x0:x1])["y"]}
    return cl


def _match_line_shift(A, B, length, lo, hi, tol=2.5):
    """Shift s with B + s ~ A: matched lines (same single/multi type) count
    twice, lines that should overlap but have no partner count against."""
    if len(A) < 3 or len(B) < 3:
        return None
    a = np.array([p for p, _ in A]); b = np.array([p for p, _ in B])
    am = np.array([n for _, n in A]); bm = np.array([n for _, n in B])
    cands = np.unique(np.round((a[:, None] - b[None, :]).ravel()))
    cands = cands[(cands >= lo) & (cands <= hi)]
    scored = []
    for s in cands:
        bs = b + s
        in_a = (bs >= 3) & (bs <= length - 3)
        in_b = (a - s >= 3) & (a - s <= length - 3)
        if in_a.sum() < 3:
            continue
        d = np.abs(a[:, None] - bs[None, :])
        match_a = (d.min(1) <= tol) & in_b
        match_b = (d.min(0) <= tol) & in_a
        j = d.argmin(1)
        typed = match_a & ((am >= 2) == (bm[j] >= 2))
        score = 2 * int(typed.sum()) - int(in_b.sum() - match_a.sum()) - int(in_a.sum() - match_b.sum())
        # refine to sub-pixel using matched pairs
        ref = float(s + np.mean((a[match_a] - bs[j[match_a]]))) if match_a.any() else float(s)
        scored.append((score, ref, int(typed.sum())))
    if not scored:
        return None
    scored.sort(key=lambda t: -t[0])
    best = scored[0]
    second = next((t for t in scored[1:] if abs(t[1] - best[1]) > 2 * tol), (-1e9, 0, 0))
    return {"shift": best[1], "score": best[0], "matched": best[2], "margin": best[0] - second[0]}


def _estimate_pair_shift_by_lines(top_bgr, bottom_bgr):
    lt, lb = _pair_line_sets(top_bgr), _pair_line_sets(bottom_bgr)
    h, w = top_bgr.shape[:2]
    sy = _match_line_shift(lt["y"], lb["y"], h, 0.15 * h, 0.95 * h)
    sx = _match_line_shift(lt["x"], lb["x"], w, -0.25 * w, 0.25 * w)
    if sy is None or sx is None:
        return None, {"method": "grid-lines", "reason": "too-few-lines"}
    M = np.array([[1.0, 0.0, sx["shift"]], [0.0, 1.0, sy["shift"]]], np.float32)
    return M, {"method": "grid-lines", "x_shift": sx["shift"], "y_shift": sy["shift"],
               "x_matched": sx["matched"], "y_matched": sy["matched"],
               "x_margin": sx["margin"], "y_margin": sy["margin"]}


def _estimate_pair_shift_by_cells(top_bgr, bottom_bgr):
    """Same cells seen in both captures (taken without moving the sample):
    the translation that superimposes the most cells.  Cells are not periodic,
    so this cannot lock onto the wrong grid repeat."""
    pts = []
    for img in (top_bgr, bottom_bgr):
        g = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        try:
            pol, _ = _cell_polarity(g, 1.0)
            det = _detect_cells_scaled(g, None, 1.0, pol)
        except Exception:
            det = []
        pts.append(np.array([[d[0], d[1]] for d in det], np.float32).reshape(-1, 2))
    pt, pb = pts
    if len(pt) < 20 or len(pb) < 20:
        return None, {"method": "cells", "reason": "too-few-cells"}
    h, w = top_bgr.shape[:2]
    dif = (pt[:, None, :] - pb[None, :, :]).reshape(-1, 2)
    ok = (dif[:, 1] > 0.15 * h) & (dif[:, 1] < 0.95 * h) & (np.abs(dif[:, 0]) < 0.25 * w)
    dif = dif[ok]
    if len(dif) < 20:
        return None, {"method": "cells", "reason": "no-overlap"}
    xe = np.arange(-0.25 * w, 0.25 * w + 4, 4); ye = np.arange(0.15 * h, 0.95 * h + 4, 4)
    H, _, _ = np.histogram2d(dif[:, 0], dif[:, 1], bins=[xe, ye])
    H = cv2.GaussianBlur(H.astype(np.float32), (0, 0), 1.0)
    i, j = np.unravel_index(int(np.argmax(H)), H.shape)
    peak = float(H[i, j])
    H2 = H.copy(); H2[max(0, i - 3):i + 4, max(0, j - 3):j + 4] = 0
    second = float(H2.max())
    dx0, dy0 = xe[i] + 2, ye[j] + 2
    near = dif[(np.abs(dif[:, 0] - dx0) < 8) & (np.abs(dif[:, 1] - dy0) < 8)]
    dx, dy = (float(v) for v in np.median(near, axis=0))
    q = pb + np.array([dx, dy], np.float32)
    dmin = np.sqrt(((pt[:, None, :] - q[None, :, :]) ** 2).sum(-1)).min(0)
    matched = int((dmin <= 3.0).sum())
    info = {"method": "cells", "x_shift": dx, "y_shift": dy, "matched": matched,
            "peak_ratio": peak / max(second, 1e-6)}
    if matched < 15 or peak < 1.8 * second:
        info["reason"] = "ambiguous"
        return None, info
    return np.array([[1.0, 0.0, dx], [0.0, 1.0, dy]], np.float32), info


def _translation_agrees(M, dx, dy, tol=6.0):
    return abs(float(M[0][2]) - dx) <= tol and abs(float(M[1][2]) - dy) <= tol


def _warp_blend_registered_pair(top_bgr, bottom_bgr, bottom_to_top):
    ht, wt = top_bgr.shape[:2]
    hb, wb = bottom_bgr.shape[:2]
    M3 = np.vstack([bottom_to_top, [0.0, 0.0, 1.0]]).astype(np.float64)
    top_corners = np.float64([[0, 0], [wt, 0], [wt, ht], [0, ht]])
    bot_corners_h = np.float64([[0, 0, 1], [wb, 0, 1], [wb, hb, 1], [0, hb, 1]]).T
    bot_corners = (M3 @ bot_corners_h).T[:, :2]
    all_pts = np.vstack([top_corners, bot_corners])
    min_x, min_y = np.floor(np.min(all_pts, axis=0) - 8).astype(int)
    max_x, max_y = np.ceil(np.max(all_pts, axis=0) + 8).astype(int)
    out_w, out_h = int(max_x - min_x), int(max_y - min_y)
    if out_w < 100 or out_h < 100 or out_w > int(2.2 * max(wt, wb)) or out_h > int(1.75 * (ht + hb)):
        raise ValueError('registered canvas outside safety bounds')

    shift = np.array([[1.0, 0.0, -float(min_x)], [0.0, 1.0, -float(min_y)], [0.0, 0.0, 1.0]])
    top_M = shift[:2].astype(np.float32)
    bot_M = (shift @ M3)[:2].astype(np.float32)

    top_warp = cv2.warpAffine(top_bgr, top_M, (out_w, out_h), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT)
    bot_warp = cv2.warpAffine(bottom_bgr, bot_M, (out_w, out_h), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT)
    mask_top = cv2.warpAffine(np.full((ht, wt), 255, np.uint8), top_M, (out_w, out_h), flags=cv2.INTER_NEAREST)
    mask_bot = cv2.warpAffine(np.full((hb, wb), 255, np.uint8), bot_M, (out_w, out_h), flags=cv2.INTER_NEAREST)

    present_top = mask_top > 0
    present_bot = mask_bot > 0
    # Hard seam in the middle of the overlap (8 px feather): the two captures
    # are taken at different times, so averaging would show moved cells twice.
    both_rows = np.where((present_top & present_bot).any(axis=1))[0]
    yy = np.arange(out_h, dtype=np.float32)[:, None]
    if both_rows.size:
        seam = 0.5 * (float(both_rows[0]) + float(both_rows[-1]))
        w_top_row = np.clip((seam - yy) / 8.0 + 0.5, 0.0, 1.0)
    else:
        w_top_row = np.ones((out_h, 1), np.float32)
    w_top_row = np.repeat(w_top_row, out_w, axis=1)
    wt_top = np.where(present_top & present_bot, w_top_row, present_top.astype(np.float32))
    wt_bot = np.where(present_top & present_bot, 1.0 - w_top_row, present_bot.astype(np.float32))

    blended = (
        top_warp.astype(np.float32) * wt_top[..., None] +
        bot_warp.astype(np.float32) * wt_bot[..., None]
    )
    blended = np.clip(blended, 0, 255).astype(np.uint8)

    union = present_top | present_bot
    blended[~union] = np.array((32, 18, 11), dtype=np.uint8)   # BGR of the viewer background #0B1220
    ys, xs = np.where(union)
    if xs.size:
        x0, x1 = max(0, xs.min() - 2), min(out_w, xs.max() + 3)
        y0, y1 = max(0, ys.min() - 2), min(out_h, ys.max() + 3)
        blended = blended[y0:y1, x0:x1]
    return blended


def _add_registered_header(image, method_text):
    header_h = 52
    # Height is kept (overlay mappers assume it); the strip is left blank in the viewer colour.
    out = np.full((image.shape[0] + header_h, image.shape[1], 3), (32, 18, 11), dtype=np.uint8)
    out[header_h:] = image
    return out


def _estimate_registered_pair_geometry(top_bgr, bottom_bgr):
    """Find registration once, on UNMARKED capture pixels (never on overlays).

    The returned bottom->top affine is in the equal-width display coordinate
    system.  It is meant for presentation only; the counting engine analyzes
    each original capture independently, preserving its native pixel values.
    """
    if top_bgr is None or bottom_bgr is None:
        return None
    target_w = min(1600, max(900, max(top_bgr.shape[1], bottom_bgr.shape[1])))
    top = _resize_keep_aspect(top_bgr, target_w)
    bottom = _resize_keep_aspect(bottom_bgr, target_w)
    top_band, _, _ = _dense_horizontal_band_y(top, expected='bottom')
    bottom_band, _, _ = _dense_horizontal_band_y(bottom, expected='top')
    # 1) local features; 2) the same cells in both captures; 3) every ruling
    # line in the overlap.  A feature result must agree with the rulings.
    M_lines, info_lines = _estimate_pair_shift_by_lines(top, bottom)
    M, info = _estimate_feature_pair_affine(top, bottom, top_band, bottom_band)
    if M is not None and M_lines is not None and info_lines.get("y_margin", 0) >= 4 \
            and not _translation_agrees(M, info_lines["x_shift"], info_lines["y_shift"], tol=8.0):
        info = dict(info, rejected="disagrees-with-grid-lines")
        M = None
    if M is None:
        M_cells, info_cells = _estimate_pair_shift_by_cells(top, bottom)
        if M_cells is not None:
            M, info = M_cells, info_cells
            if M_lines is not None and _translation_agrees(M_cells, info_lines["x_shift"], info_lines["y_shift"], tol=6.0):
                M = M_lines                     # rulings give the sharper position
                info = dict(info_cells, refined="grid-lines")
    if M is None and M_lines is not None:
        M, info = M_lines, info_lines
    if M is None:
        M, info = _estimate_grid_translation(top, bottom, top_band, bottom_band)
    return dict(matrix=np.asarray(M, dtype=np.float32).copy(), info=dict(info),
                target_w=int(target_w))


def _compose_registered_pair_display(top_bgr, bottom_bgr, registration=None):
    """Preview/result MUST use the same transform estimated on clean originals.

    Never re-detect SIFT/grid matches on result images containing green/red
    counting circles, Q rectangles, and annotation text: those artificial
    features can cause registration to jump to an unrelated grid phase.
    """
    if top_bgr is None or bottom_bgr is None:
        return _compose_independent_display(top_bgr, bottom_bgr)

    target_w = min(1600, max(900, max(top_bgr.shape[1], bottom_bgr.shape[1])))
    top = _resize_keep_aspect(top_bgr, target_w)
    bottom = _resize_keep_aspect(bottom_bgr, target_w)
    if registration is None:
        # Legacy callers still work; call this only with unmarked raw captures.
        registration = _estimate_registered_pair_geometry(top, bottom)
    if registration is None:
        return _compose_independent_display(top, bottom)
    if int(registration.get('target_w', -1)) != int(target_w):
        raise ValueError('Cached registration was computed for a different image width')
    M = np.asarray(registration['matrix'], dtype=np.float32)
    info = registration['info']

    try:
        stitched = _warp_blend_registered_pair(top, bottom, M)
        if info.get('method') == 'feature':
            method = f"feature LOCKED, inliers={info.get('inliers', 0)}"
        elif info.get('method') == 'cells':
            method = f"cell positions LOCKED, {info.get('matched', 0)} cells matched"
        elif info.get('method') == 'grid-lines':
            method = f"ruling lines LOCKED, {info.get('x_matched', 0)}+{info.get('y_matched', 0)} lines matched"
        else:
            method = f"grid profile (low confidence), corr={info.get('profile_corr', 0.0):.2f}"
        return _add_registered_header(stitched, method)
    except Exception:
        return _compose_independent_display(
            top, bottom,
            first_title='Independent capture: Q1-Q2 (registration fallback)',
            second_title='Independent capture: Q3-Q4 (registration fallback)',
        )



def _snap_square_to_boundary_lines(gray, rect, tol=None):
    """Move each edge of a counting square to the centre of the nearby ruling.

    For every edge, the bright-line profile (local top-hat, median along the
    edge) is taken within +/- tol pixels; its positive mass centroid is the
    centre of the single/double/triple boundary line.  An edge is only moved
    when a clear line is present, and the square keeps its size within 2 %.
    """
    x0, y0, x1, y1 = [int(v) for v in rect]
    h, w = gray.shape[:2]
    side = max(x1 - x0, y1 - y0)
    if tol is None:
        tol = max(4, int(round(side * 0.018)))
    g = gray.astype(np.float32)
    th = g - cv2.GaussianBlur(g, (0, 0), 6)

    def centre(axis, pos, a, b):
        lo, hi = pos - tol, pos + tol + 1
        if axis == 'x':
            if lo < 0 or hi > w:
                return pos
            prof = np.median(th[max(0, a):min(h, b), lo:hi], axis=0)
        else:
            if lo < 0 or hi > h:
                return pos
            prof = np.median(th[lo:hi, max(0, a):min(w, b)], axis=1)
        wgt = np.clip(prof - max(0.0, float(np.median(prof))), 0, None)
        if wgt.sum() <= 1e-6 or float(prof.max()) < 6.0:
            return pos
        return int(round(lo + float(np.sum(np.arange(len(prof)) * wgt) / wgt.sum())))

    nx0 = centre('x', x0, y0, y1); nx1 = centre('x', x1, y0, y1)
    ny0 = centre('y', y0, x0, x1); ny1 = centre('y', y1, x0, x1)
    if abs((nx1 - nx0) - (x1 - x0)) > 0.02 * (x1 - x0):
        nx0, nx1 = x0, x1
    if abs((ny1 - ny0) - (y1 - y0)) > 0.02 * (y1 - y0):
        ny0, ny1 = y0, y1
    return nx0, ny0, nx1, ny1


# =========================
# Hemocytometer grid scale + cell polarity (any magnification / illumination)
# =========================
STANDARD_PX_PER_MM = 476.0      # analysis scale the detector and rules were tuned at


def _profile_peaks(prof, height, min_dist=2):
    p = np.where((prof[1:-1] > prof[:-2]) & (prof[1:-1] >= prof[2:]) & (prof[1:-1] >= height))[0] + 1
    keep = []
    for i in p[np.argsort(-prof[p])]:
        if all(abs(int(i) - k) >= min_dist for k in keep):
            keep.append(int(i))
    return np.array(sorted(keep), dtype=np.float64)


def _grid_line_clusters(gray):
    """Bright ruling lines along x and y as (centre, multiplicity) clusters.

    Single lines are the 50 um / 250 um rulings; clusters of 2-3 close lines
    are the boundary (double/triple) lines of the 200 um groups and 1 mm squares.
    """
    g = gray.astype(np.float32)
    th = g - cv2.GaussianBlur(g, (0, 0), 6)
    out = {}
    for axis, name in ((0, "x"), (1, "y")):
        prof = np.percentile(th, 60, axis=axis)
        pk = _profile_peaks(prof, max(3.0, float(np.percentile(prof, 95))))
        if len(pk) < 2:
            out[name] = [(float(p), 1) for p in pk]
            continue
        ds = np.sort(np.diff(pk))
        thr = 2.5
        jumps = ds[1:] / np.maximum(ds[:-1], 1.0)
        idx = np.where((jumps > 3.0) & (ds[:-1] <= 12))[0]
        if len(idx):
            thr = float(np.sqrt(ds[idx[-1]] * ds[idx[-1] + 1]))
        clusters, cur = [], [pk[0]]
        for p in pk[1:]:
            if p - cur[-1] <= thr:
                cur.append(p)
            else:
                clusters.append(cur)
                cur = [p]
        clusters.append(cur)
        out[name] = [(float(np.mean(c)), len(c)) for c in clusters]
    return out


def _spacing_families(pos, tol=0.06):
    d = np.diff(np.asarray(pos, np.float64))
    fam = []
    for v in sorted(d):
        if v < 4:
            continue
        m = np.abs(d - v) <= tol * v
        if m.sum() >= 2 and not any(abs(v - f) <= tol * f for f, _ in fam):
            fam.append((float(np.median(d[m])), int(m.sum())))
    return fam


def _hemocytometer_px_per_mm(gray):
    """Pixels per mm from the Improved-Neubauer ruling itself.

    Line spacings must map onto the known structure: single rulings 50 um
    (centre square) or 250 um (corner squares); boundary (multi-line) spacings
    200 um (centre groups) or 1 mm (large squares).  The scale explaining the
    most spacings wins and is refined by averaging all matching spacings.
    Returns (px_per_mm or None, info).
    """
    cl = _grid_line_clusters(gray)
    singles, multis = [], []
    for name in ("x", "y"):
        singles += _spacing_families([p for p, n in cl[name]])
        multis += _spacing_families([p for p, n in cl[name] if n >= 2])
    cands = [v / k for v, _ in singles for k in (50.0, 250.0)] + \
            [v / k for v, _ in multis for k in (200.0, 1000.0)]
    best, best_score = None, -1
    for s in cands:
        score = sum(n for v, n in singles if any(abs(v / s - k) <= 0.06 * k for k in (50.0, 200.0, 250.0)))
        score += sum(n for v, n in multis if any(abs(v / s - k) <= 0.06 * k for k in (200.0, 1000.0)))
        if score > best_score:
            best, best_score = s, score
    if best is None or best_score < 3:
        return None, {"clusters": cl}
    est, wts = [], []
    for fams, ks in ((singles, (50.0, 200.0, 250.0)), (multis, (200.0, 1000.0))):
        for v, n in fams:
            for k in ks:
                if abs(v / best - k) <= 0.06 * k:
                    est.append(v / k)
                    wts.append(n * k)       # long spacings are more precise
    px_per_um = float(np.average(est, weights=wts)) if est else best
    return px_per_um * 1000.0, {"clusters": cl, "score": best_score}


def _dark_cells_to_bright_blobs(gray_std, r=3.8):
    """Bright-field captures: cells are darker than the background (dye-filled
    body and/or a dark refractive rim).  Map 'darker than local background' to
    a bright blob so the tuned bright-cell detector can be reused unchanged."""
    f = gray_std.astype(np.float32)
    bg = cv2.medianBlur(np.clip(f, 0, 255).astype(np.uint8), 2 * int(3 * r) + 1).astype(np.float32)
    dark = np.clip(bg - f, 0, None)
    e = cv2.GaussianBlur(dark, (0, 0), 0.4 * r)
    p = float(np.percentile(e, 99.7))
    return np.clip(40.0 + e * (190.0 / max(p, 1.0)), 0, 255).astype(np.uint8)


def _detect_cells_scaled(q_gray, core_local, det_scale=1.0, polarity="bright", hires_gray=None):
    """Run the tuned detector at the standard magnification and polarity."""
    img = q_gray
    h, w = img.shape[:2]
    small = img
    if abs(det_scale - 1.0) >= 1e-3:
        nw, nh = max(16, int(round(w * det_scale))), max(16, int(round(h * det_scale)))
        small = cv2.resize(img, (nw, nh), interpolation=cv2.INTER_AREA if det_scale < 1 else cv2.INTER_LINEAR)
    if polarity == "dark":
        small = _dark_cells_to_bright_blobs(small)
    hires = None
    if hires_gray is not None and polarity == "bright":
        fh = hires_gray.shape[1] / float(small.shape[1])
        if fh >= HIRES_SPLIT_MIN_FACTOR:
            hires = (hires_gray, fh)
    if abs(det_scale - 1.0) < 1e-3:
        return _nih3t3_scale_adaptive_detect(small, core_local, hires=hires)
    core_s = None
    if core_local is not None:
        core_s = tuple(int(round(v * det_scale)) for v in core_local)
    det = _nih3t3_scale_adaptive_detect(small, core_s, hires=hires)
    inv = 1.0 / det_scale
    return [(d[0] * inv, d[1] * inv, d[2] * inv) + tuple(d[3:]) for d in det]


def _cell_polarity(gray, det_scale=1.0):
    """'bright' if cells are brighter than the background (phase / dark-field
    like captures), 'dark' if they are darker (bright-field, dye-loaded cells).
    Decided by which polarity yields more cell-sized, cell-covered area."""
    g = gray
    if abs(det_scale - 1.0) > 1e-3:
        g = cv2.resize(gray, (max(16, int(round(gray.shape[1] * det_scale))),
                              max(16, int(round(gray.shape[0] * det_scale)))), interpolation=cv2.INTER_AREA)
    h, w = g.shape[:2]
    m = int(0.05 * min(h, w))
    g = g[m:h - m, m:w - m]
    scores = {}
    for name, img in (("bright", g), ("dark", 255 - g)):
        try:
            det, info = _nih3t3_scale_adaptive_detect(img, None, return_info=True)
            a0 = float(info.get("a0", 0.0)) if isinstance(info, dict) else 0.0
            scores[name] = len(det) * a0
        except Exception:
            scores[name] = 0.0
    return ("dark" if scores["dark"] > 1.5 * max(scores["bright"], 1e-6) else "bright"), scores


# =========================
# Display overlay geometry (cell markers are drawn on the canvas, not burned
# into the image, so they can be sized for the current zoom and animated)
# =========================
def _registered_pair_layout(top_shape, bottom_shape, registration):
    """Exact geometry of _compose_registered_pair_display for point mapping."""
    if registration is None:
        return None
    th, tw = top_shape[:2]
    bh, bw = bottom_shape[:2]
    target_w = min(1600, max(900, max(tw, bw)))
    if int(registration.get('target_w', -1)) != int(target_w):
        return None
    tw2 = max(320, int(target_w))
    ht = max(1, int(round(th * tw2 / float(tw))))
    hb = max(1, int(round(bh * tw2 / float(bw))))
    M3 = np.vstack([np.asarray(registration['matrix'], np.float64), [0.0, 0.0, 1.0]])
    top_corners = np.float64([[0, 0], [tw2, 0], [tw2, ht], [0, ht]])
    bot_corners = (M3 @ np.float64([[0, 0, 1], [tw2, 0, 1], [tw2, hb, 1], [0, hb, 1]]).T).T[:, :2]
    all_pts = np.vstack([top_corners, bot_corners])
    min_x, min_y = np.floor(np.min(all_pts, axis=0) - 8).astype(int)
    max_x, max_y = np.ceil(np.max(all_pts, axis=0) + 8).astype(int)
    out_w, out_h = int(max_x - min_x), int(max_y - min_y)
    if out_w < 100 or out_h < 100 or out_w > int(2.2 * tw2) or out_h > int(1.75 * (ht + hb)):
        return None
    shift = np.array([[1.0, 0.0, -float(min_x)], [0.0, 1.0, -float(min_y)], [0.0, 0.0, 1.0]])
    top_M = shift
    bot_M = shift @ M3
    mask_top = cv2.warpAffine(np.full((ht, tw2), 255, np.uint8), top_M[:2].astype(np.float32),
                              (out_w, out_h), flags=cv2.INTER_NEAREST)
    mask_bot = cv2.warpAffine(np.full((hb, tw2), 255, np.uint8), bot_M[:2].astype(np.float32),
                              (out_w, out_h), flags=cv2.INTER_NEAREST)
    ys, xs = np.where((mask_top > 0) | (mask_bot > 0))
    if xs.size == 0:
        return None
    x0, x1 = max(0, xs.min() - 2), min(out_w, xs.max() + 3)
    y0, y1 = max(0, ys.min() - 2), min(out_h, ys.max() + 3)
    header = 52
    crop = np.array([[1.0, 0.0, -float(x0)], [0.0, 1.0, -float(y0) + header], [0.0, 0.0, 1.0]])
    scale_t = np.diag([tw2 / float(tw), ht / float(th), 1.0])
    scale_b = np.diag([tw2 / float(bw), hb / float(bh), 1.0])
    return {
        "size": (int(y1 - y0) + header, int(x1 - x0)),
        "top": crop @ top_M @ scale_t,
        "bottom": crop @ bot_M @ scale_b,
    }


def _independent_layout(first_shape, second_shape=None):
    """Geometry of _compose_independent_display for point mapping."""
    def panel(shape, target_w):
        h, w = shape[:2]
        s = float(target_w) / float(w)
        ph = max(1, int(round(h * s)))
        return s, ph
    pad, header = 12, 52
    if second_shape is None:
        s, ph = panel(first_shape, 1200)
        A = np.array([[s, 0, pad], [0, s, header + pad], [0, 0, 1.0]])
        return {"size": (ph + header + 2 * pad, 1200 + 2 * pad), "first": A}
    s1, ph1 = panel(first_shape, 760)
    s2, ph2 = panel(second_shape, 760)
    left_w = 760 + 2 * pad
    A1 = np.array([[s1, 0, pad], [0, s1, header + pad], [0, 0, 1.0]])
    A2 = np.array([[s2, 0, left_w + 24 + pad], [0, s2, header + pad], [0, 0, 1.0]])
    h = max(ph1, ph2) + header + 2 * pad
    return {"size": (h, left_w + 24 + left_w), "first": A1, "second": A2}


class _OverlayMapper:
    """Maps analysis-image coordinates of each capture onto the display image."""

    def __init__(self, transforms, size):
        self.transforms = transforms      # mode -> 3x3 affine
        self.size = tuple(size)           # (h, w) of the display image

    def has(self, mode):
        return mode in self.transforms

    def point(self, mode, x, y):
        A = self.transforms[mode]
        return (A[0, 0] * x + A[0, 1] * y + A[0, 2], A[1, 0] * x + A[1, 1] * y + A[1, 2])

    def scale(self, mode):
        A = self.transforms[mode]
        return float(np.sqrt(abs(A[0, 0] * A[1, 1] - A[0, 1] * A[1, 0])))


def _build_overlay_mapper(entries, registration, display_shape):
    """entries: list of (mode, analysis_shape) in display order (top first).

    Returns a mapper whose predicted display size matches display_shape, or None.
    """
    want = tuple(display_shape[:2])
    candidates = []
    if len(entries) >= 2:
        (m0, s0), (m1, s1) = entries[0], entries[1]
        lay = _registered_pair_layout(s0, s1, registration)
        if lay is not None:
            candidates.append(_OverlayMapper({m0: lay["top"], m1: lay["bottom"]}, lay["size"]))
        ind = _independent_layout(s0, s1)
        candidates.append(_OverlayMapper({m0: ind["first"], m1: ind["second"]}, ind["size"]))
    elif len(entries) == 1:
        (m0, s0) = entries[0]
        ind = _independent_layout(s0, None)
        candidates.append(_OverlayMapper({m0: ind["first"]}, ind["size"]))
    for cand in candidates:
        if abs(cand.size[0] - want[0]) <= 2 and abs(cand.size[1] - want[1]) <= 2:
            return cand
    return None


# =========================
# Ground-truth annotation store, accumulated training, validation (Build 29)
# =========================
# Every analysed capture can be reviewed and corrected by the user:
#   - confirm or change live/dead of detected cells
#   - mark detections that are not cells
#   - add cells the detector missed
#   - mark the capture "fully checked" once every counting square is correct
# Annotations are stored next to the program (cell_annotations/<key>.json)
# keyed by a hash of the analysed pixels, so they survive restarts and are
# reloaded when the same image is analysed again.  They are the ground truth
# for (1) training the live/dead model on ALL labelled images and (2) the
# validation report used for the paper.

ANNOTATION_DIR_NAME = "cell_annotations"
ANNOTATION_FEATURE_VERSION = VIABILITY_PROFILE_VERSION





def _annotation_dir():
    path = os.path.join(_program_dir(), ANNOTATION_DIR_NAME)
    os.makedirs(path, exist_ok=True)
    return path


def _annotation_key(bgr):
    h = hashlib.md5()
    h.update(str(bgr.shape).encode())
    h.update(np.ascontiguousarray(bgr[::2, ::2]).tobytes())
    return h.hexdigest()[:16]


def _annotation_path(key):
    return os.path.join(_annotation_dir(), f"{key}.json")


def _load_annotation(key):
    path = _annotation_path(key)
    if not os.path.exists(path):
        return None
    try:
        import json
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except Exception:
        return None


def _list_annotations():
    import json
    out = []
    folder = _annotation_dir()
    for name in sorted(os.listdir(folder)):
        if not name.endswith(".json"):
            continue
        try:
            with open(os.path.join(folder, name), "r", encoding="utf-8") as handle:
                out.append(json.load(handle))
        except Exception:
            continue
    return out


def _feat_list(f):
    if f is None:
        return None
    return [None if not np.isfinite(v) else float(v) for v in np.asarray(f, np.float64)]


def _feat_array(f):
    if f is None:
        return None
    return np.array([np.nan if v is None else float(v) for v in f], np.float32)


def _features_for_points(record, points):
    """Viability features for user-added cells, computed together with the
    detected cells so the population-relative normalisation is unchanged."""
    if not points:
        return []
    base = [(c[0], c[1], c[2]) for c in record["cells"]]
    fn = _classify_viability_brightfield if record.get("polarity") == "dark" else _classify_viability_v7
    try:
        _, feats = fn(record["bgr"], base + [tuple(p[:3]) for p in points], grid_mask=record.get("grid_mask"))
        return feats[len(base):]
    except Exception:
        return [None] * len(points)


def _save_annotation(record, labels, added, checked):
    """labels: {cell_index: 'live'|'dead'|'not_cell'}; added: [[x, y, r, label], ...]."""
    import json
    feats_added = _features_for_points(record, added)
    cells = []
    for ci, (cx, cy, r, feat, auto) in enumerate(record["cells"]):
        cells.append({
            "x": round(float(cx), 2), "y": round(float(cy), 2), "r": round(float(r), 2),
            "q": int(record["cell_q"][ci]) if ci < len(record.get("cell_q", [])) else None,
            "auto": auto,
            "p_auto": round(float(record["cell_p"][ci]), 4) if ci < len(record.get("cell_p", [])) else None,
            "label": labels.get(ci),
            "feat": _feat_list(feat),
        })
    adds = []
    for (x, y, r, lab), feat in zip(added, feats_added):
        adds.append({"x": round(float(x), 2), "y": round(float(y), 2), "r": round(float(r), 2),
                     "label": lab, "feat": _feat_list(feat)})
    doc = {
        "key": record["key"], "image_name": record.get("name", ""),
        "polarity": record.get("polarity", "bright"),
        "px_per_mm": record.get("px_per_mm"),
        "rois": [list(map(int, r)) for r in record.get("rois", [])],
        "roi_q": list(record.get("roi_q", [])),
        "roi_area_mm2": list(record.get("roi_area_mm2", [1.0] * len(record.get("rois", [])))),
        "feature_version": ANNOTATION_FEATURE_VERSION,
        "checked": bool(checked),
        "saved": time.strftime("%Y-%m-%d %H:%M:%S"),
        "cells": cells, "added": adds,
    }
    with open(_annotation_path(record["key"]), "w", encoding="utf-8") as handle:
        json.dump(doc, handle)
    return doc


def _training_set(polarity, docs=None, exclude_key=None):
    """Explicit user labels (live/dead) of one image type from all annotations."""
    feats, ys = [], []
    for doc in (docs if docs is not None else _list_annotations()):
        if doc.get("polarity", "bright") != polarity or doc.get("key") == exclude_key:
            continue
        if int(doc.get("feature_version", -1)) != ANNOTATION_FEATURE_VERSION:
            continue
        for c in doc.get("cells", []) + doc.get("added", []):
            if c.get("label") in ("live", "dead") and c.get("feat") is not None:
                feats.append(_feat_array(c["feat"]))
                ys.append(1 if c["label"] == "dead" else 0)
    return feats, ys


def _inside_counting_square(x, y, r, roi):
    x0, y0, x1, y1 = roi
    r = max(1.0, float(r))
    if x + r < x0 or y + r < y0:
        return False
    if x + r >= x1 or y + r >= y1:
        return False
    return True


def _cohen_kappa(cm):
    cm = np.asarray(cm, np.float64)
    n = cm.sum()
    if n <= 0:
        return float("nan")
    po = np.trace(cm) / n
    pe = float((cm.sum(0) * cm.sum(1)).sum()) / (n * n)
    return float((po - pe) / (1 - pe)) if pe < 1 else float("nan")


def _validation_rows(docs, use_profile_loio=True):
    """Per counting square: program vs ground truth.  Only fully-checked images.

    Ground truth for a checked image = detected cells not marked 'not a cell'
    (with the user's label, or the program's label if the user accepted it)
    plus cells the user added.  Live/dead agreement is also reported on the
    cells the user labelled explicitly, which is not biased by acceptance.
    """
    rows, cell_pairs = [], []
    checked = [d for d in docs if d.get("checked")]
    for doc in checked:
        pol = doc.get("polarity", "bright")
        prof_loio = None
        if use_profile_loio:
            f_tr, y_tr = _training_set(pol, docs, exclude_key=doc.get("key"))
            if y_tr.count(0) >= 5 and y_tr.count(1) >= 5:
                try:
                    prof_loio = _fit_viability_profile(f_tr, y_tr)
                except Exception:
                    prof_loio = None
        for ri, roi in enumerate(doc.get("rois", [])):
            q = doc["roi_q"][ri] if ri < len(doc.get("roi_q", [])) else ri + 1
            area = doc.get("roi_area_mm2", [1.0] * len(doc["rois"]))[ri]
            cells = [c for c in doc.get("cells", []) if c.get("q") == q]
            added = [a for a in doc.get("added", []) if _inside_counting_square(a["x"], a["y"], a["r"], roi)]
            prog_live = sum(1 for c in cells if c["auto"] == "live")
            prog_dead = sum(1 for c in cells if c["auto"] == "dead")
            fp = sum(1 for c in cells if c.get("label") == "not_cell")
            tp_cells = [c for c in cells if c.get("label") != "not_cell"]
            gt = [(c.get("label") or c["auto"]) for c in tp_cells] + [a["label"] for a in added if a["label"] in ("live", "dead")]
            gt_live = sum(1 for g in gt if g == "live"); gt_dead = sum(1 for g in gt if g == "dead")
            cal_live = cal_dead = None
            if prof_loio is not None:
                cal_live = cal_dead = 0
                for c in tp_cells:
                    f = _feat_array(c.get("feat"))
                    p = _profile_dead_probability(f, prof_loio) if f is not None else (1.0 if c["auto"] == "dead" else 0.0)
                    if p >= 0.5:
                        cal_dead += 1
                    else:
                        cal_live += 1
            rows.append({
                "image": doc.get("image_name") or doc.get("key"), "key": doc.get("key"), "type": pol,
                "square": q, "area_mm2": area,
                "program_total": prog_live + prog_dead, "program_live": prog_live, "program_dead": prog_dead,
                "manual_total": gt_live + gt_dead, "manual_live": gt_live, "manual_dead": gt_dead,
                "true_pos": len(tp_cells), "false_pos": fp, "missed": len(added),
                "calibrated_live": cal_live, "calibrated_dead": cal_dead,
            })
            for c in tp_cells:
                truth = c.get("label") or c["auto"]
                f = _feat_array(c.get("feat"))
                cal = None
                if prof_loio is not None and f is not None:
                    cal = "dead" if _profile_dead_probability(f, prof_loio) >= 0.5 else "live"
                cell_pairs.append({"truth": truth, "program": c["auto"], "calibrated": cal,
                                   "explicit": c.get("label") in ("live", "dead"), "type": pol})
    return rows, cell_pairs


def _validation_summary(rows, cells):
    def safe(a, b):
        return float(a) / float(b) if b else float("nan")
    tp = sum(r["true_pos"] for r in rows); fp = sum(r["false_pos"] for r in rows); fn = sum(r["missed"] for r in rows)
    prec, rec = safe(tp, tp + fp), safe(tp, tp + fn)
    f1 = safe(2 * prec * rec, prec + rec) if np.isfinite(prec) and np.isfinite(rec) else float("nan")
    prog = np.array([r["program_total"] for r in rows], np.float64)
    man = np.array([r["manual_total"] for r in rows], np.float64)
    out = {"images": len({r["key"] for r in rows}), "squares": len(rows), "manual_cells": int(man.sum()),
           "precision": prec, "recall": rec, "f1": f1}
    if len(rows):
        diff = prog - man
        out["count_mape_pct"] = float(np.mean(np.abs(diff) / np.maximum(man, 1)) * 100)
        out["count_bias"] = float(diff.mean())
        out["count_loa"] = (float(diff.mean() - 1.96 * diff.std(ddof=1)) if len(rows) > 1 else float("nan"),
                            float(diff.mean() + 1.96 * diff.std(ddof=1)) if len(rows) > 1 else float("nan"))
        if len(rows) > 2 and man.std() > 0 and prog.std() > 0:
            out["count_r2"] = float(np.corrcoef(prog, man)[0, 1] ** 2)
        pv = np.array([safe(r["program_live"], r["program_total"]) for r in rows]) * 100
        mv = np.array([safe(r["manual_live"], r["manual_total"]) for r in rows]) * 100
        out["viability_mae_pct_points"] = float(np.nanmean(np.abs(pv - mv)))
        if all(r["calibrated_live"] is not None for r in rows):
            cv = np.array([safe(r["calibrated_live"], r["calibrated_live"] + r["calibrated_dead"]) for r in rows]) * 100
            out["viability_mae_calibrated"] = float(np.nanmean(np.abs(cv - mv)))
    for name, subset in (("all", cells), ("explicit", [c for c in cells if c["explicit"]])):
        for model in ("program", "calibrated"):
            pairs = [(c["truth"], c[model]) for c in subset if c[model] is not None]
            if not pairs:
                continue
            cm = np.zeros((2, 2), int)          # rows truth live/dead, cols predicted live/dead
            for t, p in pairs:
                cm[int(t == "dead"), int(p == "dead")] += 1
            acc = np.trace(cm) / cm.sum()
            sens = safe(cm[1, 1], cm[1].sum()); spec = safe(cm[0, 0], cm[0].sum())
            out[f"{model}_{name}"] = {"n": int(cm.sum()), "accuracy": float(acc), "dead_sensitivity": sens,
                                      "live_specificity": spec, "kappa": _cohen_kappa(cm), "cm": cm.tolist()}
    return out


def _write_validation_report(folder, rows, cells, summary):
    import csv, json
    os.makedirs(folder, exist_ok=True)
    stamp = time.strftime("%Y%m%d_%H%M%S")
    csv_path = os.path.join(folder, f"validation_{stamp}.csv")
    with open(csv_path, "w", newline="", encoding="utf-8-sig") as handle:
        w = csv.DictWriter(handle, fieldnames=list(rows[0].keys()))
        w.writeheader()
        w.writerows(rows)
    with open(os.path.join(folder, f"validation_{stamp}_summary.json"), "w", encoding="utf-8") as handle:
        json.dump(summary, handle, indent=2, default=float)
    fig_path = None
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        prog = np.array([r["program_total"] for r in rows], float)
        man = np.array([r["manual_total"] for r in rows], float)
        fig, ax = plt.subplots(1, 4, figsize=(17, 4.2))
        lim = max(1.0, prog.max(), man.max()) * 1.08
        ax[0].scatter(man, prog, s=22, color="#1F4FD1")
        ax[0].plot([0, lim], [0, lim], color="#888", lw=1, ls="--")
        ax[0].set_xlim(0, lim); ax[0].set_ylim(0, lim)
        ax[0].set_xlabel("Manual count per square"); ax[0].set_ylabel("Program count per square")
        ax[0].set_title(f"Count  (R² {summary.get('count_r2', float('nan')):.3f})", loc="left")
        mean = (prog + man) / 2; diff = prog - man
        ax[1].scatter(mean, diff, s=22, color="#1F4FD1")
        ax[1].axhline(diff.mean(), color="#333", lw=1)
        if len(diff) > 1:
            for v in summary["count_loa"]:
                ax[1].axhline(v, color="#888", lw=1, ls="--")
        ax[1].set_xlabel("Mean of program and manual"); ax[1].set_ylabel("Program − manual")
        ax[1].set_title("Bland–Altman", loc="left")
        pv = np.array([r["program_live"] / max(1, r["program_total"]) for r in rows]) * 100
        mv = np.array([r["manual_live"] / max(1, r["manual_total"]) for r in rows]) * 100
        ax[2].scatter(mv, pv, s=22, color="#2E9E44", label="default rule")
        if all(r["calibrated_live"] is not None for r in rows):
            cv = np.array([r["calibrated_live"] / max(1, r["calibrated_live"] + r["calibrated_dead"]) for r in rows]) * 100
            ax[2].scatter(mv, cv, s=22, color="#E8590C", marker="^", label="calibrated (LOIO)")
            ax[2].legend(frameon=False, fontsize=8)
        ax[2].plot([0, 100], [0, 100], color="#888", lw=1, ls="--")
        ax[2].set_xlim(0, 100); ax[2].set_ylim(0, 100)
        ax[2].set_xlabel("Manual viability (%)"); ax[2].set_ylabel("Program viability (%)")
        ax[2].set_title("Viability", loc="left")
        key = "calibrated_explicit" if "calibrated_explicit" in summary else "program_explicit"
        if key not in summary:
            key = "program_all"
        cm = np.array(summary[key]["cm"])
        ax[3].imshow(cm, cmap="Blues")
        for i in range(2):
            for j in range(2):
                ax[3].text(j, i, str(cm[i, j]), ha="center", va="center",
                           color="white" if cm[i, j] > cm.max() / 2 else "black", fontsize=12)
        ax[3].set_xticks([0, 1]); ax[3].set_xticklabels(["Live", "Dead"])
        ax[3].set_yticks([0, 1]); ax[3].set_yticklabels(["Live", "Dead"])
        ax[3].set_xlabel("Predicted"); ax[3].set_ylabel("Manual")
        ax[3].set_title(f"{key.replace('_', ' ')}  (κ {summary[key]['kappa']:.2f})", loc="left")
        for a in ax[:3]:
            a.spines["top"].set_visible(False); a.spines["right"].set_visible(False)
        fig.tight_layout()
        fig_path = os.path.join(folder, f"validation_{stamp}.png")
        fig.savefig(fig_path, dpi=300)
        plt.close(fig)
    except Exception:
        fig_path = None
    return csv_path, fig_path


class ViabilityCalibrationWindow(tk.Toplevel):
    """Review / annotate detected cells and build ground truth.

    Mouse (on a detected cell):  left = LIVE, right = DEAD,
        Shift+right or key X (pointer on the cell) = NOT A CELL,
        middle or Shift+left = clear the label.
    Mouse (on an empty spot): left / right = ADD a missed live / dead cell
        (middle click on an added cell removes it).
    Review uncertain (U): L / D / X / S(kip) / <- (back).
    "Fully checked" marks the image as complete ground truth (all squares).
    """
    ZOOMS = (1.0, 1.5, 2.0, 3.0, 4.0)
    LABEL_COLORS = {"live": "#00FF55", "dead": "#FF2222", "not_cell": "#CBD5E1"}

    def __init__(self, app, records):
        super().__init__(app)
        self.app = app
        self.records = records
        self.index = 0
        self.zoom_i = 2
        self.labels = {}           # (record_index, cell_index) -> 'live' | 'dead' | 'not_cell'
        self.added = {}            # record_index -> [[x, y, r, label], ...]
        self.checked = set()       # record indices marked fully checked
        self.dirty = False
        self._restore_saved()
        self.title("Review / Annotate cells — ground truth for training and validation")
        self.geometry("1200x880")
        self.configure(bg=CLR_BG)
        top = tk.Frame(self, bg=CLR_BG); top.pack(fill=tk.X, padx=12, pady=8)
        tk.Label(
            top, bg=CLR_BG, fg=CLR_TXT, font=FONT_BDY, justify=tk.LEFT,
            text=("점선 = 프로그램 판정(초록 생 / 빨강 사).  실선 = 사용자가 확인한 정답.  회색 X = 세포 아님.  + = 추가한 세포\n"
                  "세포 위: 왼쪽 클릭 = 생,  오른쪽 클릭 = 사,  Shift+오른쪽 클릭 또는 X키 = 세포 아님,  가운데 클릭 = 지우기\n"
                  "빈 곳(놓친 세포): 왼쪽 클릭 = 생세포 추가,  오른쪽 클릭 = 사세포 추가  (추가한 것은 가운데 클릭으로 삭제)\n"
                  "'Review uncertain'(U): 애매한 세포를 하나씩 — L 생 / D 사 / X 세포 아님 / S 건너뛰기 / ← 이전\n"
                  "검증용: 사분면 안의 모든 세포가 맞게 되었으면 'Fully checked ✓'를 누르세요 (틀린 것만 고치면 됩니다).")
        ).pack(side=tk.LEFT)
        inset_box = tk.Frame(top, bg=CLR_BG); inset_box.pack(side=tk.RIGHT)
        self.inset = tk.Canvas(inset_box, width=170, height=170, bg=CLR_CANV, highlightthickness=1,
                               highlightbackground="#94A3B8")
        self.inset.pack()
        self.review_lbl = tk.Label(inset_box, text="", bg=CLR_BG, fg=CLR_TXT, font=("Segoe UI", 9, "bold"),
                                   wraplength=230, justify=tk.CENTER)
        self.review_lbl.pack(pady=(2, 0))
        self._inset_img = None
        self.reviewing = False
        self.review_queue, self.review_pos = [], 0

        bar = tk.Frame(self, bg=CLR_BG); bar.pack(fill=tk.X, padx=12)
        tk.Button(bar, text="< Prev image", command=lambda: self.change_image(-1)).pack(side=tk.LEFT)
        tk.Button(bar, text="Next image >", command=lambda: self.change_image(1)).pack(side=tk.LEFT, padx=6)
        tk.Button(bar, text="Zoom -", command=lambda: self.change_zoom(-1)).pack(side=tk.LEFT, padx=(14, 2))
        tk.Button(bar, text="Zoom +", command=lambda: self.change_zoom(1)).pack(side=tk.LEFT)
        tk.Button(bar, text="Review uncertain (U)", command=self.start_review, bg="#F59E0B", fg="black").pack(side=tk.LEFT, padx=(14, 0))
        self.check_btn = tk.Button(bar, text="", command=self.toggle_checked, width=18)
        self.check_btn.pack(side=tk.LEFT, padx=(10, 0))
        tk.Button(bar, text="Train (Fit & Save)", command=self.fit_and_save, bg=CLR_PRM, fg="white").pack(side=tk.RIGHT)
        tk.Button(bar, text="Save", command=self.save_all).pack(side=tk.RIGHT, padx=6)
        tk.Button(bar, text="Close", command=self.close).pack(side=tk.RIGHT)
        self.count_lbl = tk.Label(self, text="", bg=CLR_BG, fg=CLR_PRM, font=("Segoe UI", 10, "bold"), anchor="w")
        self.count_lbl.pack(fill=tk.X, padx=14, pady=(4, 0))

        frame = tk.Frame(self); frame.pack(fill=tk.BOTH, expand=True, padx=12, pady=8)
        self.canvas = tk.Canvas(frame, bg=CLR_CANV, highlightthickness=0)
        hbar = tk.Scrollbar(frame, orient=tk.HORIZONTAL, command=self.canvas.xview)
        vbar = tk.Scrollbar(frame, orient=tk.VERTICAL, command=self.canvas.yview)
        self.canvas.configure(xscrollcommand=hbar.set, yscrollcommand=vbar.set)
        hbar.pack(side=tk.BOTTOM, fill=tk.X); vbar.pack(side=tk.RIGHT, fill=tk.Y)
        self.canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        self.canvas.bind("<Button-1>", lambda e: self.on_click(e, "live"))
        self.canvas.bind("<Shift-Button-1>", lambda e: self.on_click(e, None))
        self.canvas.bind("<Button-2>", lambda e: self.on_click(e, None))
        self.canvas.bind("<Button-3>", lambda e: self.on_click(e, "dead"))
        self.canvas.bind("<Shift-Button-3>", lambda e: self.on_click(e, "not_cell"))
        self.canvas.bind("<Motion>", self._on_motion)
        self.canvas.bind("<MouseWheel>", self.on_wheel)
        self.canvas.bind("<Control-MouseWheel>", self.on_ctrl_wheel)
        self.canvas.bind("<Button-4>", lambda e: self.canvas.yview_scroll(-3, "units"))
        self.canvas.bind("<Button-5>", lambda e: self.canvas.yview_scroll(3, "units"))
        self._tk_img = None
        self._pointer = None
        for key, label in (("l", "live"), ("L", "live"), ("d", "dead"), ("D", "dead")):
            self.bind(f"<Key-{key}>", lambda e, lab=label: self.review_answer(lab))
        for key in ("x", "X"):
            self.bind(f"<Key-{key}>", lambda e: self.key_not_cell())
        for key in ("s", "S", "Right"):
            self.bind(f"<Key-{key}>", lambda e: self.review_answer(None))
        self.bind("<Key-Left>", lambda e: self.review_back())
        self.bind("<Key-BackSpace>", lambda e: self.review_back())
        self.bind("<Key-u>", lambda e: self.start_review())
        self.bind("<Key-U>", lambda e: self.start_review())
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.transient(app)
        self.render()
        self.after(50, self.scroll_to_roi)

    # ---- persistence ----------------------------------------------------
    def _restore_saved(self):
        for ri, rec in enumerate(self.records):
            doc = _load_annotation(rec.get("key", ""))
            if not doc:
                continue
            pts = np.array([[c[0], c[1]] for c in rec["cells"]], np.float32) if rec["cells"] else np.zeros((0, 2))
            for c in doc.get("cells", []):
                if c.get("label") is None or pts.shape[0] == 0:
                    continue
                d = np.hypot(pts[:, 0] - c["x"], pts[:, 1] - c["y"])
                j = int(np.argmin(d))
                if d[j] <= 2.0:
                    self.labels[(ri, j)] = c["label"]
            self.added[ri] = [[a["x"], a["y"], a["r"], a["label"]] for a in doc.get("added", [])]
            if doc.get("checked"):
                self.checked.add(ri)

    def save_all(self, quiet=True):
        n = 0
        for ri, rec in enumerate(self.records):
            labels = {ci: lab for (r_, ci), lab in self.labels.items() if r_ == ri}
            added = self.added.get(ri, [])
            if not labels and not added and ri not in self.checked and _load_annotation(rec["key"]) is None:
                continue
            _save_annotation(rec, labels, added, ri in self.checked)
            n += 1
        self.dirty = False
        if not quiet:
            messagebox.showinfo("Annotations", f"{n}장의 정답 데이터를 저장했습니다.\n{_annotation_dir()}", parent=self)
        self.render()
        return n

    def close(self):
        if self.dirty:
            self.save_all()
        self.destroy()

    def toggle_checked(self):
        if self.index in self.checked:
            self.checked.discard(self.index)
        else:
            self.checked.add(self.index)
        self.dirty = True
        self.save_all()

    # ---- review of the most uncertain cells (active labelling) ------------
    def _build_review_queue(self, limit=80):
        profs = {pol: _load_viability_profile(pol) for pol in ("bright", "dark")}
        items = []
        for ri, rec in enumerate(self.records):
            prof = profs.get(rec.get("polarity", "bright"))
            for ci, (cx, cy, r, feat, auto) in enumerate(rec["cells"]):
                if feat is None or (ri, ci) in self.labels:
                    continue
                p = _profile_dead_probability(feat, prof) if prof is not None else _rule_dead_probability(feat)
                items.append((abs(p - 0.5), ri, ci, p))
        items.sort(key=lambda t: t[0])
        self.review_queue = [(ri, ci, p) for _, ri, ci, p in items[:limit]]
        self.review_pos = 0

    def start_review(self):
        if not self.review_queue or self.review_pos >= len(self.review_queue):
            self._build_review_queue()
        self.reviewing = True
        self.focus_force()
        self._show_review()

    def _show_review(self):
        if self.review_pos >= len(self.review_queue):
            self.reviewing = False
            self.canvas.delete("focus")
            self.inset.delete("all")
            self.review_lbl.config(text="검토 완료 — 'Train'을 누르세요.")
            self.save_all()
            return
        ri, ci, p = self.review_queue[self.review_pos]
        self.index = ri
        self.zoom_i = len(self.ZOOMS) - 1
        self.render()
        rec = self.records[ri]
        cx, cy, r, feat, auto = rec["cells"][ci]
        zoom = self.ZOOMS[self.zoom_i]
        h, w = rec["bgr"].shape[:2]
        cw, ch = max(1, self.canvas.winfo_width()), max(1, self.canvas.winfo_height())
        self.canvas.xview_moveto(max(0.0, (cx * zoom - cw / 2.0) / (w * zoom)))
        self.canvas.yview_moveto(max(0.0, (cy * zoom - ch / 2.0) / (h * zoom)))
        s = (r + 6) * zoom
        self.canvas.create_rectangle(cx * zoom - s, cy * zoom - s, cx * zoom + s, cy * zoom + s,
                                     outline="#FACC15", width=2, dash=(4, 2), tags=("focus",))
        half = int(max(10, round(3.2 * r)))
        pad = cv2.copyMakeBorder(rec["bgr"], half, half, half, half, cv2.BORDER_REFLECT)
        crop = pad[int(round(cy)):int(round(cy)) + 2 * half + 1, int(round(cx)):int(round(cx)) + 2 * half + 1]
        crop = cv2.resize(crop, (170, 170), interpolation=cv2.INTER_CUBIC)
        self._inset_img = ImageTk.PhotoImage(Image.fromarray(cv2.cvtColor(crop, cv2.COLOR_BGR2RGB)))
        self.inset.delete("all")
        self.inset.create_image(0, 0, anchor="nw", image=self._inset_img)
        rr = r * 170.0 / (2 * half + 1) + 4
        self.inset.create_oval(85 - rr, 85 - rr, 85 + rr, 85 + rr, outline="#FACC15", dash=(3, 2))
        given = self.labels.get((ri, ci))
        given_txt = {"live": "  [표시: 생]", "dead": "  [표시: 사]", "not_cell": "  [표시: 세포 아님]"}.get(given, "")
        self.review_lbl.config(
            text=f"애매한 세포 {self.review_pos + 1}/{len(self.review_queue)}{given_txt}\n"
                 f"프로그램: 사세포 확률 {p * 100:.0f}%\nL 생  D 사  X 세포 아님  S 건너뛰기  ← 이전")

    def review_answer(self, label):
        if not self.reviewing or self.review_pos >= len(self.review_queue):
            return
        ri, ci, _ = self.review_queue[self.review_pos]
        if label is not None:
            self.labels[(ri, ci)] = label
            self.dirty = True
        self.review_pos += 1
        self._show_review()

    def review_back(self):
        if not self.reviewing and self.review_pos == 0:
            return
        self.reviewing = True
        self.review_pos = max(0, self.review_pos - 1)
        self._show_review()

    def key_not_cell(self):
        if self.reviewing and self.review_pos < len(self.review_queue):
            self.review_answer("not_cell")
            return
        if self._pointer is not None:
            hit = self._hit(*self._pointer)
            if hit is not None and hit[0] == "cell":
                self.labels[(self.index, hit[1])] = "not_cell"
                self.dirty = True
                self.render()

    def scroll_to_roi(self):
        rec = self.records[self.index]
        rois = rec.get("rois") or []
        if not rois:
            return
        h, w = rec["bgr"].shape[:2]
        x0, y0 = rois[0][0], rois[0][1]
        self.canvas.xview_moveto(max(0.0, (x0 - 20) / w))
        self.canvas.yview_moveto(max(0.0, (y0 - 20) / h))

    # ---- drawing -------------------------------------------------------
    def render(self):
        rec = self.records[self.index]
        zoom = self.ZOOMS[self.zoom_i]
        img = rec["bgr"]
        h, w = img.shape[:2]
        rois = rec.get("rois") or []
        if rois:   # dim everything outside the counted squares
            inside = np.zeros((h, w), bool)
            for x0, y0, x1, y1 in rois:
                inside[max(0, y0):max(0, y1), max(0, x0):max(0, x1)] = True
            img = img.copy()
            img[~inside] = (img[~inside].astype(np.float32) * 0.35).astype(np.uint8)
        disp = cv2.resize(img, (int(w * zoom), int(h * zoom)),
                          interpolation=cv2.INTER_NEAREST if zoom >= 2 else cv2.INTER_LINEAR)
        self._tk_img = ImageTk.PhotoImage(Image.fromarray(cv2.cvtColor(disp, cv2.COLOR_BGR2RGB)))
        self.canvas.delete("all")
        self.canvas.create_image(0, 0, anchor="nw", image=self._tk_img)
        self.canvas.configure(scrollregion=(0, 0, disp.shape[1], disp.shape[0]))
        for ci, (cx, cy, r, feat, auto) in enumerate(rec["cells"]):
            lab = self.labels.get((self.index, ci))
            rr = (r + 2) * zoom
            x, y = cx * zoom, cy * zoom
            if lab is None:
                self.canvas.create_oval(x - rr, y - rr, x + rr, y + rr,
                                        outline="#22FF66" if auto == "live" else "#FF4D4D",
                                        dash=(3, 3), width=1)
            elif lab == "not_cell":
                k = rr * 0.8
                self.canvas.create_line(x - k, y - k, x + k, y + k, fill="#CBD5E1", width=2)
                self.canvas.create_line(x - k, y + k, x + k, y - k, fill="#CBD5E1", width=2)
            else:
                self.canvas.create_oval(x - rr - 1, y - rr - 1, x + rr + 1, y + rr + 1, outline="white", width=4)
                self.canvas.create_oval(x - rr, y - rr, x + rr, y + rr, outline=self.LABEL_COLORS[lab], width=3)
        for ax_, ay_, ar_, lab in self.added.get(self.index, []):
            rr = (ar_ + 2) * zoom
            x, y = ax_ * zoom, ay_ * zoom
            self.canvas.create_oval(x - rr - 1, y - rr - 1, x + rr + 1, y + rr + 1, outline="white", width=4)
            self.canvas.create_oval(x - rr, y - rr, x + rr, y + rr, outline=self.LABEL_COLORS[lab], width=3)
            self.canvas.create_text(x + rr, y - rr, text="+", fill="white", font=("Segoe UI", 11, "bold"))
        self._update_status()

    def _update_status(self):
        mine = [v for (r_, c_), v in self.labels.items() if r_ == self.index]
        add = self.added.get(self.index, [])
        tot_live = sum(1 for v in self.labels.values() if v == "live") + sum(1 for a in self.added.values() for x in a if x[3] == "live")
        tot_dead = sum(1 for v in self.labels.values() if v == "dead") + sum(1 for a in self.added.values() for x in a if x[3] == "dead")
        rec = self.records[self.index]
        kind = "명시야(어두운 세포)" if rec.get("polarity") == "dark" else "밝은 세포"
        self.count_lbl.config(text=(
            f"Image {self.index + 1}/{len(self.records)}  [{rec.get('name') or rec.get('key')}, {kind}]   "
            f"이 이미지: 생 {mine.count('live')}  사 {mine.count('dead')}  세포아님 {mine.count('not_cell')}  추가 {len(add)}   |   "
            f"이 창 전체 라벨: 생 {tot_live}  사 {tot_dead}"))
        on = self.index in self.checked
        self.check_btn.config(text="Fully checked ✓" if on else "Mark fully checked",
                              bg="#16A34A" if on else CLR_MUTE, fg="white" if on else "black")

    def change_image(self, step):
        if self.dirty:
            self.save_all()
        self.index = (self.index + step) % len(self.records)
        self.render()
        self.scroll_to_roi()

    def change_zoom(self, step):
        self.zoom_i = int(np.clip(self.zoom_i + step, 0, len(self.ZOOMS) - 1))
        self.render()

    def on_wheel(self, event):
        self.canvas.yview_scroll(-1 if event.delta > 0 else 1, "units")

    def on_ctrl_wheel(self, event):
        self.change_zoom(1 if event.delta > 0 else -1)

    # ---- labelling -----------------------------------------------------
    def _on_motion(self, event):
        zoom = self.ZOOMS[self.zoom_i]
        self._pointer = (self.canvas.canvasx(event.x) / zoom, self.canvas.canvasy(event.y) / zoom)

    def _hit(self, x, y):
        rec = self.records[self.index]
        best, best_d = None, None
        for k, (ax_, ay_, ar_, lab) in enumerate(self.added.get(self.index, [])):
            d = (ax_ - x) ** 2 + (ay_ - y) ** 2
            if d <= max(5.0, 1.4 * ar_) ** 2 and (best_d is None or d < best_d):
                best, best_d = ("added", k), d
        for ci, (cx, cy, r, feat, auto) in enumerate(rec["cells"]):
            d = (cx - x) ** 2 + (cy - y) ** 2
            if d <= max(6.0, 1.6 * r) ** 2 and (best_d is None or d < best_d):
                best, best_d = ("cell", ci), d
        return best

    def on_click(self, event, label):
        zoom = self.ZOOMS[self.zoom_i]
        x = self.canvas.canvasx(event.x) / zoom
        y = self.canvas.canvasy(event.y) / zoom
        hit = self._hit(x, y)
        if hit is None:
            if label in ("live", "dead"):           # a missed cell: add it
                rec = self.records[self.index]
                r = float(np.median([c[2] for c in rec["cells"]])) if rec["cells"] else 4.0
                self.added.setdefault(self.index, []).append([float(x), float(y), r, label])
                self.dirty = True
        elif hit[0] == "added":
            if label is None:
                self.added[self.index].pop(hit[1])
            elif label in ("live", "dead"):
                self.added[self.index][hit[1]][3] = label
            self.dirty = True
        else:
            key = (self.index, hit[1])
            if label is None:
                self.labels.pop(key, None)
            else:
                self.labels[key] = label
            self.dirty = True
        self.render()

    def fit_and_save(self):
        self.save_all()
        docs = _list_annotations()
        names = {"bright": "밝은 세포 사진", "dark": "명시야(어두운 세포) 사진"}
        lines, short = [], []
        for pol in ("bright", "dark"):
            feats, ys = _training_set(pol, docs)
            if not ys:
                continue
            n_img = len({d.get("key") for d in docs if d.get("polarity", "bright") == pol and
                         any(c.get("label") in ("live", "dead") for c in d.get("cells", []) + d.get("added", []))})
            if ys.count(0) < 5 or ys.count(1) < 5:
                short.append(f"{names[pol]}: 생 {ys.count(0)} / 사 {ys.count(1)} (각 5개 이상 필요)")
                continue
            profile = _fit_viability_profile(feats, ys)
            loo = profile["loo_balanced_accuracy"]; rule = profile["rule_balanced_accuracy"]
            if loo <= rule + 1e-9:
                if not messagebox.askyesno(
                    "Train",
                    f"[{names[pol]}] 학습 모델의 교차검증 정확도({loo * 100:.1f}%)가 기본 규칙({rule * 100:.1f}%)보다 "
                    "높지 않습니다.\n프로그램이 틀린 세포를 더 표시하면 좋아집니다.\n\n그래도 저장할까요? (권장: 아니오)",
                    default=messagebox.NO, parent=self):
                    continue
            profile["n_images"] = n_img
            _save_viability_profile(profile)
            lines.append(f"[{names[pol]}] 이미지 {n_img}장, 생 {ys.count(0)} / 사 {ys.count(1)} — "
                         f"교차검증 {loo * 100:.1f}% (기본 규칙 {rule * 100:.1f}%)")
        self.app.calib_status_lbl.config(text=_viability_mode_text())
        msg = ("학습 완료 (저장된 모든 정답 데이터 사용)\n" + "\n".join(lines)) if lines else "학습할 수 있는 데이터가 아직 부족합니다."
        if short:
            msg += "\n\n" + "\n".join(short)
        if lines:
            msg += "\n\nAuto-Detect & Analyze를 다시 실행하면 학습된 기준이 적용됩니다."
        messagebox.showinfo("Train", msg, parent=self)



# =========================
# Yeast (low magnification, e.g. 4x objective): one 1 mm corner square per
# capture.  Budding pairs are not resolvable at this magnification, so the
# number of cells in an object is taken from its area relative to the single
# cell area of THIS image.  The two thresholds reproduce the 1/2/3-cell mix
# counted by the user on 40x captures of the same preparation (48/46/6 %;
# cells per object 1.58 vs 1.60).
# =========================
YEAST_PAIR_AREA_RATIO = 1.25    # object >= 1.25 single-cell areas -> mother + bud (2 cells)
YEAST_TRIPLE_AREA_RATIO = 4.2   # >= 4.2 single-cell areas -> 3 cells
YEAST_MAX_OBJECT_RATIO = 8.0    # > 8 single-cell areas: debris / aggregate, not counted


def _yeast_line_peaks(g, axis, L):
    th = g - cv2.GaussianBlur(g, (0, 0), 6)
    if axis == 'x':
        op = cv2.morphologyEx(th, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, L)))
        prof = np.percentile(op, 60, axis=0)
    else:
        op = cv2.morphologyEx(th, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (L, 1)))
        prof = np.percentile(op, 60, axis=1)
    prof = prof - cv2.GaussianBlur(prof.reshape(1, -1).astype(np.float32), (0, 0), 25).reshape(-1)
    noise = float(np.median(np.abs(prof - np.median(prof)))) + 1e-3
    pk = [i for i in range(2, len(prof) - 2) if prof[i] >= prof[i - 2:i + 3].max() and prof[i] > 4 * noise]
    merged = []
    for p in pk:
        if merged and p - merged[-1][-1] <= 6:
            merged[-1].append(p)
        else:
            merged.append([p])
    return [float(np.mean(m)) for m in merged]


def _yeast_square_1d(peaks, n_len):
    """Five evenly spaced rulings (1/4 mm apart) with no other ruling between
    them: the edges of the 1 mm corner square."""
    best = None
    P = sorted(peaks)
    for i in range(len(P)):
        for l in range(i + 1, len(P)):
            g = (P[l] - P[i]) / 4.0
            if g < 0.06 * n_len or g > 0.2 * n_len:
                continue
            run, ok = [P[i]], True
            for k in range(1, 4):
                tgt = P[i] + k * g
                c = min(P, key=lambda p: abs(p - tgt))
                if abs(c - tgt) > 0.06 * g:
                    ok = False
                    break
                run.append(c)
            if not ok:
                continue
            run.append(P[l])
            inner = [p for p in P if run[0] + 0.1 * g < p < run[-1] - 0.1 * g and min(abs(p - r) for r in run) > 0.1 * g]
            if inner:
                continue
            if best is None or g > best[1]:
                best = (run, g)
    return best


def _yeast_find_square(bgr):
    sc = 1368.0 / bgr.shape[1]
    g = cv2.cvtColor(cv2.resize(bgr, None, fx=sc, fy=sc, interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2GRAY).astype(np.float32)
    bx = _yeast_square_1d(_yeast_line_peaks(g, 'x', 61), g.shape[1])
    by = _yeast_square_1d(_yeast_line_peaks(g, 'y', 61), g.shape[0])
    if bx is None or by is None or not (0.85 <= bx[1] / by[1] <= 1.15):
        return None
    return (bx[0][0] / sc, by[0][0] / sc, bx[0][-1] / sc, by[0][-1] / sc, bx[1] / sc, by[1] / sc)


def _yeast_analyze(bgr, bud_separate=True, k=6.0):
    """Count yeast inside the 1 mm square of one capture.
    Returns dict(square, markers [(x, y, r, n)], objects, cells, pairs, a0,
    px_per_mm, warning) or None when no complete 1 mm square is visible."""
    sq = _yeast_find_square(bgr)
    if sq is None:
        return None
    x0, y0, x1, y1 = [int(round(v)) for v in sq[:4]]
    g_px = 0.5 * (sq[4] + sq[5])                       # pixels per 1/4 mm
    pad = int(0.15 * g_px)
    X0, Y0 = max(0, x0 - pad), max(0, y0 - pad)
    X1, Y1 = min(bgr.shape[1], x1 + pad), min(bgr.shape[0], y1 + pad)
    lab = cv2.cvtColor(bgr[Y0:Y1, X0:X1], cv2.COLOR_BGR2LAB).astype(np.float32)
    L = lab[..., 0]
    med_k = max(3, int(round(g_px / 10)) | 1)
    bg = np.dstack([cv2.medianBlur(lab[..., i].astype(np.uint8), med_k).astype(np.float32) for i in range(3)])
    d = lab - bg
    D = cv2.GaussianBlur(np.sqrt(d[..., 0] ** 2 + 2 * d[..., 1] ** 2 + 2 * d[..., 2] ** 2), (0, 0), 1.2)
    th = L - cv2.GaussianBlur(L, (0, 0), 6)
    Ll = max(15, int(0.5 * g_px))
    ln = np.maximum(cv2.morphologyEx(th, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (Ll, 1))),
                    cv2.morphologyEx(th, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (1, Ll))))
    lmed = float(np.median(ln)); lmad = float(np.median(np.abs(ln - lmed))) + 1e-3
    line = cv2.dilate((ln > lmed + 4 * lmad).astype(np.uint8), cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (9, 9))) > 0
    v = D[~line]
    med = float(np.median(v)); mad = float(np.median(np.abs(v - med))) + 1e-3
    m = ((D > med + k * mad) & ~line).astype(np.uint8)
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)))
    n, lab_i, st, cen = cv2.connectedComponentsWithStats(m, 8)
    objs = []
    for i in range(1, n):
        a = int(st[i, 4])
        if a < 10:
            continue
        cx, cy = cen[i][0] + X0, cen[i][1] + Y0
        if not (x0 <= cx < x1 and y0 <= cy < y1):
            continue                                     # centre inside the 1 mm square
        bx, by_, w, h = st[i, 0], st[i, 1], st[i, 2], st[i, 3]
        comp = lab_i[by_:by_ + h, bx:bx + w] == i
        on_line = float(line[by_:by_ + h, bx:bx + w][comp].mean())
        asp = max(w, h) / max(1, min(w, h)); fill = a / max(1, w * h)
        if on_line >= 0.5 or asp > 3.0 or fill < 0.3:
            continue                                     # ruling residue / fibre
        if a >= 60:
            cs_, _ = cv2.findContours(comp.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            hull_a = cv2.contourArea(cv2.convexHull(max(cs_, key=cv2.contourArea))) if cs_ else 0
            if hull_a > 0 and a / hull_a < 0.65:
                continue                                 # branched / star-shaped debris
        ys_, xs_ = np.nonzero(comp)
        pts_ = np.c_[xs_ + bx + X0, ys_ + by_ + Y0].astype(np.float64)
        if len(pts_) >= 3:
            cov_ = np.cov((pts_ - pts_.mean(0)).T); ev_, evec_ = np.linalg.eigh(cov_)
            axis_ = evec_[:, 1]; half_ = 2.0 * math.sqrt(max(ev_[1], 0.0))
        else:
            axis_, half_ = np.array([1.0, 0.0]), 0.0
        objs.append((cx, cy, a, asp, fill, axis_, half_))
    compact = [o[2] for o in objs if o[3] < 1.5 and o[4] > 0.5]
    cell_circles = []
    if len(compact) < 20:
        return dict(square=sq, markers=[], objects=0, cells=0, pairs=0, a0=None,
                    px_per_mm=4.0 * g_px, warning="효모를 충분히 찾지 못했습니다")
    a0 = float(np.median(compact))
    markers, cells, pairs, large = [], 0, 0, 0
    for cx, cy, a, asp, fill, axis_, half_ in objs:
        r = a / a0
        if r < 0.5:
            continue                                     # fragments / noise below half a cell
        if r > YEAST_MAX_OBJECT_RATIO:
            continue                                     # aggregate / large debris (not counted)
        if r >= 3.5:
            large += 1
        nc = 1 if r < YEAST_PAIR_AREA_RATIO else (2 if r < YEAST_TRIPLE_AREA_RATIO else 3)
        if not bud_separate:
            nc = 1
        cells += nc
        pairs += int(nc >= 2)
        markers.append((cx, cy, math.sqrt(a / math.pi), nc))
        # one circle per cell: overlapping circles along the object's major axis
        if nc == 1:
            cell_circles.append((cx, cy, math.sqrt(a / math.pi), 1))
        else:
            rc = math.sqrt(a / nc / math.pi) * 1.1
            span = max(half_ - rc, 0.6 * rc)
            for j in range(nc):
                t = -span + 2.0 * span * j / (nc - 1)
                cell_circles.append((cx + t * axis_[0], cy + t * axis_[1], rc, nc))
    warning = ""
    if markers and large / len(markers) > 0.2:
        warning = "초점/대비가 고르지 않아 쌍 판정 신뢰도가 낮습니다"
    return dict(square=sq, markers=markers, cell_circles=cell_circles, objects=len(markers), cells=cells, pairs=pairs, a0=a0,
                px_per_mm=4.0 * g_px, warning=warning)


def _yeast_result_panel(bgr, res, title):
    """Display copy of one capture with the square and the counted objects."""
    sc = min(1.0, 2400.0 / bgr.shape[1])
    vis = cv2.resize(bgr, None, fx=sc, fy=sc, interpolation=cv2.INTER_AREA)
    if res is not None:
        x0, y0, x1, y1 = [int(round(v * sc)) for v in res["square"][:4]]
        cv2.rectangle(vis, (x0, y0), (x1, y1), (0, 0, 255), 4)
        for cx, cy, r, nc in res.get("cell_circles", res["markers"]):
            col = (40, 200, 40)                              # every counted cell: green circle
            cv2.circle(vis, (int(cx * sc), int(cy * sc)), max(3, int(r * sc) + 3), col, 2, cv2.LINE_AA)
    cv2.rectangle(vis, (0, 0), (vis.shape[1], 56), (20, 20, 20), -1)
    cv2.putText(vis, title, (14, 40), cv2.FONT_HERSHEY_SIMPLEX, 1.15, (255, 255, 255), 2, cv2.LINE_AA)
    return vis


def _yeast_mosaic(panels):
    if not panels:
        return None
    h = max(p.shape[0] for p in panels); w = max(p.shape[1] for p in panels)
    tiles = [cv2.copyMakeBorder(p, 0, h - p.shape[0], 0, w - p.shape[1], cv2.BORDER_CONSTANT, value=(30, 30, 30)) for p in panels]
    if len(tiles) == 1:
        return tiles[0]
    while len(tiles) % 2:
        tiles.append(np.full_like(tiles[0], 30))
    rows = [np.hstack([tiles[i], np.full((h, 8, 3), 30, np.uint8), tiles[i + 1]]) for i in range(0, len(tiles), 2)]
    out = rows[0]
    for r_ in rows[1:]:
        out = np.vstack([out, np.full((8, out.shape[1], 3), 30, np.uint8), r_])
    return out


class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Cell Counting Program")
        try:
            icon = _resource_path(APP_ICON_FILENAME)
            if os.path.exists(icon):
                self.iconbitmap(icon)
        except Exception:
            pass
        self.geometry("1600x980")
        self.configure(bg=CLR_BG)

        self.image_paths = []
        self.mosaic_bgr = None
        self.annotated_bgr = None
        self.reference_model = _load_reference_model()
        self.microalgae_model = _load_microalgae_model()
        self.quad_data = {i: {"total": 0, "live": 0, "dead": 0, "counted": False} for i in range(1, 5)}
        
        self.target_type = tk.StringVar(value="Cells")
        self.yeast_bud_separate = tk.BooleanVar(value=True)
        self.dilution = tk.DoubleVar(value=2.0)
        self.target_cells = tk.IntVar(value=100)
        self.use_stitching = tk.BooleanVar(value=False)
        self.manual_mode = tk.BooleanVar(value=False)
        
        self.manual_boxes_coords, self.current_rect = [], None
        self.image_pair_modes = {}
        self.image_pair_details = {}
        
        self._build_ui()

    # ------------------------------------------------------------------ UI
    def _ui_button(self, parent, text, command, kind="secondary", font=None):
        styles = {
            "primary":   dict(bg=CLR_PRM, fg="white", activebackground="#4338CA", activeforeground="white"),
            "secondary": dict(bg="#EEF2FF", fg=CLR_PRM, activebackground="#E0E7FF", activeforeground=CLR_PRM),
            "ghost":     dict(bg="#F1F5F9", fg=CLR_TXT, activebackground=CLR_MUTE, activeforeground=CLR_TXT),
        }
        return tk.Button(parent, text=text, command=command, relief="flat", bd=0, highlightthickness=0,
                         cursor="hand2", font=font or ("Segoe UI", 10), **styles[kind])

    def _ui_card(self, parent, title, height):
        card = tk.Frame(parent, bg=CLR_CARD, width=UI_SIDE_W, height=height,
                        highlightthickness=1, highlightbackground=CLR_LINE)
        card.pack(pady=(0, 12)); card.pack_propagate(False)
        tk.Label(card, text=title, bg=CLR_CARD, fg=CLR_TXT, font=("Segoe UI", 10, "bold")).place(x=UI_PAD, y=12)
        return card

