        self.canvas = tk.Canvas(main, bg=CLR_CANV, highlightthickness=0); self.canvas.pack(fill=tk.BOTH, expand=True)

        # --- results strip: status line, per-square counts | totals and viability on the right
        qa = tk.Frame(main, bg=CLR_CARD, highlightthickness=1, highlightbackground=CLR_LINE)
        qa.pack(fill=tk.X, pady=(12, 0))
        qa.grid_columnconfigure(4, weight=1)
        self.engine_summary_lbl = tk.Label(
            qa, text="Adaptive detector: waiting", font=("Segoe UI", 9), fg=CLR_SUB, bg=CLR_CARD, anchor="w"
        ); self.engine_summary_lbl.grid(row=0, column=0, columnspan=5, sticky="w", padx=(20, 0), pady=(12, 2))
